static std::pair<int64, int64> hostedWsConnectTimingTelemetry(bool isConnectingState, int64 connectStartedAtMs, int connectTimeoutMs)
{
    if (!isConnectingState || connectStartedAtMs <= 0 || connectTimeoutMs <= 0) {
        return { 0, 0 };
    }

    const auto elapsedMs = jmax((int64) 0, Time::currentTimeMillis() - connectStartedAtMs);
    const auto remainingMs = jmax((int64) 0, (int64) connectTimeoutMs - elapsedMs);
    return { elapsedMs, remainingMs };
}

static String hostedControlCanonicalReplayBootstrapReason(const String & reason, bool * eligibleOut = nullptr)
{
    auto normalized = reason.trim().toLowerCase();
    normalized = normalized.replaceCharacter('_', '-')
                           .replaceCharacter(' ', '-')
                           .replaceCharacter('/', '-')
                           .replaceCharacter('.', '-')
                           .replace("--", "-");
    while (normalized.contains("--")) {
        normalized = normalized.replace("--", "-");
    }

    const auto hasToken = [&normalized](const String & token) {
        return normalized.contains(token);
    };

    String canonical;
    if (hasToken("on-connect")
        || (hasToken("on") && hasToken("connect") && !hasToken("reconnect"))) {
        canonical = "on-connect";
    } else if (hasToken("socket-reconnect")
               || ((hasToken("socket") || hasToken("ws")) && hasToken("reconnect"))
               || hasToken("reconnect")) {
        canonical = "socket-reconnect";
    } else if (hasToken("connect-timeout")
               || (hasToken("connect") && hasToken("timeout"))
               || hasToken("timeout")) {
        canonical = "connect-timeout";
    }

    if (eligibleOut) {
        *eligibleOut = canonical.isNotEmpty();
    }
    return canonical;
}

static bool hostedControlShouldReplayAfterWsQueueFlushReason(const String & flushReason)
{
    bool eligible = false;
    hostedControlCanonicalReplayBootstrapReason(flushReason, &eligible);
    return eligible;
}

static String hostedControlBuildReplayBootstrapReasonFromWsQueueFlush(const String & flushReason)
{
    bool eligible = false;
    const auto canonical = hostedControlCanonicalReplayBootstrapReason(flushReason, &eligible);
    if (!eligible || canonical.isEmpty()) {
        return "post-flush";
    }

    return "post-flush-" + canonical;
}

static String hostedControlCanonicalizeReplayReasonForDiagnostics(const String & replayReason)
{
    auto normalized = replayReason.trim();
    if (normalized.isEmpty()) {
        return "replay";
    }

    if (normalized.equalsIgnoreCase("post-flush")) {
        return "post-flush";
    }

    if (normalized.startsWithIgnoreCase("post-flush-")) {
        const auto rawTrigger = normalized.fromFirstOccurrenceOf("post-flush-", false, false);
        const auto canonical = hostedControlBuildReplayBootstrapReasonFromWsQueueFlush(rawTrigger);
        return canonical.isNotEmpty() ? canonical : String("post-flush");
    }

    return normalized;
}

static String hostedControlCanonicalizeResyncReasonForDiagnostics(const String & resyncReason)
{
    auto normalized = resyncReason.trim();
    if (normalized.isEmpty()) {
        return "resync";
    }

    if (normalized.startsWithIgnoreCase("replay-")) {
        const auto replayTail = normalized.fromFirstOccurrenceOf("replay-", false, false);
        return "replay-" + hostedControlCanonicalizeReplayReasonForDiagnostics(replayTail);
    }

    return normalized;
}

static float hostedComputeRecordingInputContributionGain()
{
    return 1.0f;
}

static float hostedComputeSelfRecordingContributionGain(float /*monitorWetGain*/)
{
    // Self-record captures should not follow monitor/output gain.
    // Keeping this at unity avoids monitor-driven attenuation and avoids wet>1.0 boosts/clipping.
    return 1.0f;
}

static bool hostedShouldFallbackToPreFxSelfTap(bool recordPreFx,
                                               bool silenceWhenMuted,
                                               bool mainInputMuted,
                                               bool channelGroupMuted)
{
    if (recordPreFx || silenceWhenMuted) {
        return false;
    }

    // Post-FX capture is sourced from inputPostBuffer, which is already muted by
    // main input mute / channel mute. When the user explicitly disables
    // "silence when muted", fall back to the pre-FX tap for those muted states.
    return mainInputMuted || channelGroupMuted;
}

static StringArray hostedFallbackChannelLabels(int channels)
{
    StringArray labels;
    for (int i = 0; i < channels; ++i)
        labels.add("Channel " + String(i + 1));
    return labels;
}

static bool hostedValidateStemFile(AudioFormatManager& formatManager,
                                   const File& stemFile,
                                   int expectedSampleRate,
                                   int expectedChannels)
{
    if (!stemFile.existsAsFile()) {
        return false;
    }

    std::unique_ptr<AudioFormatReader> reader(formatManager.createReaderFor(stemFile));
    if (reader == nullptr) {
        return false;
    }

    const bool sampleRateOk = std::abs((int) reader->sampleRate - expectedSampleRate) <= 1;
    const bool channelsOk = expectedChannels <= 0 || (int) reader->numChannels == expectedChannels;
    return sampleRateOk && channelsOk && reader->lengthInSamples > 0;
}


static bool hostedDiagIsWsGuardrailCompactLineFormatStable(const String & line)
{
    return line.contains("Websocket debug copy guardrails (timing/triage/queue/smoke):")
           && line.contains(" [reasons: ")
           && line.contains("]");
}

static int hostedDiagCountLineOccurrences(const String& text, const String& needle)
{
    if (text.isEmpty() || needle.isEmpty()) {
        return 0;
    }

    int count = 0;
    int start = 0;
    while (start < text.length()) {
        const auto index = text.indexOf(start, needle);
        if (index < 0) {
            break;
        }

        ++count;
        start = index + needle.length();
    }

    return count;
}

static bool hostedDiagHasSingleTrailingWsGuardrailLineBlock(const String& debugCopyText, const String& wsGuardrailLine)
{
    if (debugCopyText.isEmpty() || wsGuardrailLine.isEmpty()) {
        return false;
    }

    const auto occurrenceCount = hostedDiagCountLineOccurrences(debugCopyText, wsGuardrailLine);
    if (occurrenceCount != 1) {
        return false;
    }

    const auto trimmed = debugCopyText.trimEnd();
    return trimmed.endsWith("\n\n" + wsGuardrailLine);
}

static String hostedDiagFindLineStartingWith(const String& text, const String& prefix)
{
    if (text.isEmpty() || prefix.isEmpty()) {
        return {};
    }

    StringArray lines;
    lines.addLines(text);
    for (const auto& line : lines) {
        const auto trimmed = line.trim();
        if (trimmed.startsWith(prefix)) {
            return trimmed;
        }
    }

    return {};
}

static String hostedDiagResolveWsGuardrailDebugCopyLine(const String& fromJsonLine, const String& liveLine)
{
    const auto fromJson = fromJsonLine.trim();
    if (hostedDiagIsWsGuardrailCompactLineFormatStable(fromJson)) {
        return fromJson;
    }

    const auto live = liveLine.trim();
    if (hostedDiagIsWsGuardrailCompactLineFormatStable(live)) {
        return live;
    }

    return fromJson.isNotEmpty() ? fromJson : live;
}

