static void appendHostedDiagnosticEventLimited(StringArray & events, int maxEvents, const String & line)
{
    auto trimmed = line.trim();
    if (trimmed.isEmpty()) {
        return;
    }

    constexpr int kMaxLineLength = 220;
    if (trimmed.length() > kMaxLineLength) {
        trimmed = trimmed.substring(0, kMaxLineLength - 3) + "...";
    }

    events.add(trimmed);
    while (events.size() > maxEvents) {
        events.remove(0);
    }
}

static void hostedDiagCountWsGuardrailCopyOutcomes(const StringArray & events, int & allowedCount, int & blockedCount)
{
    allowedCount = 0;
    blockedCount = 0;

    for (const auto & line : events) {
        if (!line.containsIgnoreCase("ws-guardrail-copy")) {
            continue;
        }
        if (line.containsIgnoreCase("outcome=allowed")) {
            ++allowedCount;
        } else if (line.containsIgnoreCase("outcome=blocked")) {
            ++blockedCount;
        }
    }
}

static String hostedDiagSerializeStringArrayToJson(const StringArray & values)
{
    Array<var> arr;
    for (const auto & v : values) {
        arr.add(v);
    }
    return JSON::toString(var(arr), false);
}

static StringArray hostedDiagDeserializeStringArrayFromJson(const String & jsonText, int maxItems)
{
    StringArray out;
    if (jsonText.trim().isEmpty() || maxItems <= 0) {
        return out;
    }

    auto parsed = JSON::parse(jsonText);
    if (!parsed.isArray()) {
        return out;
    }

    const auto * arr = parsed.getArray();
    if (arr == nullptr) {
        return out;
    }

    for (const auto & item : *arr) {
        if (out.size() >= maxItems) {
            break;
        }
        out.add(item.toString());
    }
    return out;
}

static bool hostedDiagTimingAndReconnectBundleHasExpectedSections(const String & telemetryBundleText)
{
    const auto text = telemetryBundleText.trim();
    if (text.isEmpty()) {
        return false;
    }

    return text.containsIgnoreCase("Hosted WS timing:")
            && text.containsIgnoreCase("Hosted WS reconnect telemetry:");
}

static bool hostedDiagTriageBundleHasExpectedSections(const String & triageBundleText)
{
    const auto text = triageBundleText.trim();
    if (text.isEmpty()) {
        return false;
    }

    return text.containsIgnoreCase("Hosted control diagnostics")
            && hostedDiagTimingAndReconnectBundleHasExpectedSections(text);
}

static String hostedDiagDeriveStatusChipTextFromEvents(const StringArray & diagnosticEvents)
{
    auto derived = String("Self-check: n/a");
    for (int i = diagnosticEvents.size(); --i >= 0;) {
        const auto eventLine = diagnosticEvents[i];
        if (eventLine.containsIgnoreCase("FAILED") || eventLine.containsIgnoreCase("FAIL")) {
            derived = "Self-check: FAIL";
            break;
        }
        if (eventLine.containsIgnoreCase("self-check") && eventLine.containsIgnoreCase("OK")) {
            derived = "Self-check: PASS";
            break;
        }
    }
    return derived;
}

