// get sockaddr, IPv4 or IPv6:
static void *get_in_addr(struct sockaddr *sa)
{
    if (sa->sa_family == AF_INET)
        return &(((struct sockaddr_in*)sa)->sin_addr);
    return &(((struct sockaddr_in6*)sa)->sin6_addr);
}

static int get_in_port(struct sockaddr *sa)
{
    if (sa->sa_family == AF_INET)
        return (((struct sockaddr_in*)sa)->sin_port);

    return (((struct sockaddr_in6*)sa)->sin6_port);
}

static addrinfo* getAddressInfo (bool isDatagram, const String& hostName, int portNumber)
{
    struct addrinfo hints;
    zerostruct (hints);

    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = isDatagram ? SOCK_DGRAM : SOCK_STREAM;
    hints.ai_flags = AI_NUMERICSERV;

    struct addrinfo* info = nullptr;

    if (getaddrinfo (hostName.toRawUTF8(), String (portNumber).toRawUTF8(), &hints, &info) == 0)
        return info;

    return nullptr;
}

struct SonobusAudioProcessor::EndpointState {
    EndpointState(String ipaddr_="", int port_=0) : ipaddr(ipaddr_), port(port_) {
        rawaddr.sa_family = AF_UNSPEC;
        // Integer identity for the recv-thread lookup. Only dotted-quad ipaddr strings parse;
        // hostnames leave ipv4 == 0, which never matches a real sender, so a packet from that host
        // mints a numeric-IP endpoint.
        struct in_addr a;
        if (ipaddr.isNotEmpty() && inet_pton(AF_INET, ipaddr.toRawUTF8(), &a) == 1) {
            ipv4 = a.s_addr;
        }
    }


    DatagramSocket *owner;
    //struct sockaddr_storage addr;
    //socklen_t addrlen;
    std::unique_ptr<DatagramSocket::RemoteAddrInfo> peer;
    String ipaddr;
    int port = 0;
    uint32_t ipv4 = 0; // network byte order, 0 = not a numeric IPv4

    // The recv thread already has the sender sockaddr; seed rawaddr from it so getRawAddr() never
    // has to getaddrinfo() on the RT thread for endpoints learned from inbound traffic.
    void setRawAddrIfUnset(const struct sockaddr_in & sin) {
        if (rawaddr.sa_family == AF_UNSPEC) {
            static_assert(sizeof(rawaddr) >= sizeof(sin), "sockaddr_in must fit in sockaddr");
            memcpy(&rawaddr, &sin, sizeof(sin));
        }
    }

    struct sockaddr * getRawAddr() {
        if (rawaddr.sa_family == AF_UNSPEC) {
            struct addrinfo * info = getAddressInfo(true, ipaddr, port);
            if (info) {
                memcpy(&rawaddr, info->ai_addr, info->ai_addrlen);

                freeaddrinfo(info);
            }
        }
        return &rawaddr;
    }
    
    
    // runtime state
    int64_t sentBytes = 0;
    int64_t recvBytes = 0;
    
private:
    struct sockaddr rawaddr;
    
};




