bool SonobusAudioProcessor::hostedControlApplyServerAckScaffold(const String & command, const String & payloadJson, bool accepted)
{
    String trimmedCommand;
    String payloadCommand;
    String commandResolveFailure;
    const bool commandResolved = hostedControlTryResolveAckCommandToken(command,
                                                                         payloadJson,
                                                                         trimmedCommand,
                                                                         payloadCommand,
                                                                         commandResolveFailure);

    auto room = hostedControlExtractStringProperty(payloadJson, "room");
    auto participant = hostedControlExtractStringProperty(payloadJson, "participant");

    const auto activeRoom = mHostedControlCurrentRoomName.trim();
    const auto activeParticipant = mCurrentUsername.trim();
    const auto canonicalResolvedCommand = commandResolved ? trimmedCommand : String();
    const auto ackContextTags = hostedControlBuildAckContextTags(canonicalResolvedCommand,
                                                                 room,
                                                                 participant,
                                                                 activeRoom,
                                                                 activeParticipant);

    if (room.isEmpty() && activeRoom.isNotEmpty()) {
        room = activeRoom;
    }

    if (participant.isEmpty() && canonicalResolvedCommand == "uplink.publish" && activeParticipant.isNotEmpty()) {
        participant = activeParticipant;
    }

    const String ackContext = hostedControlFormatAckContextSuffix(ackContextTags);

    if (!commandResolved) {
        const bool hasCanonicalResolvedCommand = hostedControlIsCanonicalPendingAckCommandTokenRaw(trimmedCommand);
        const String expectedPreview = hostedControlBuildPendingAckExpectedPreview(mHostedControlReplayPendingAckKeys,
                                                                                    hasCanonicalResolvedCommand ? trimmedCommand : String());
        String blockedLine = "room-state-replay ack blocked (";
        if (commandResolveFailure == "empty-command") {
            blockedLine << "empty command)";
        } else if (commandResolveFailure == "non-canonical-command-token") {
            blockedLine << "non-canonical command token) command=" << trimmedCommand;
        } else if (commandResolveFailure == "non-canonical-payload-command-token") {
            blockedLine << "non-canonical payload command token) command=" << trimmedCommand
                        << " payloadCommand=" << payloadCommand;
        } else if (commandResolveFailure == "malformed-payload-json") {
            blockedLine << "malformed payload json) command=" << trimmedCommand;
        } else if (commandResolveFailure == "payload-command-mismatch") {
            blockedLine << "payload command mismatch) command=" << trimmedCommand
                        << " payloadCommand=" << payloadCommand;
        } else {
            blockedLine << "command resolution failure) command=" << trimmedCommand
                        << " payloadCommand=" << payloadCommand;
        }

        blockedLine << ackContext
                    << " pendingAck=" << String(mHostedControlReplayPendingAckKeys.size())
                    << " expected=" << expectedPreview;
        addHostedControlDiagnosticEvent(blockedLine);

        const auto overwriteRules = hostedControlApplyDeterministicResyncOverwriteRules(mHostedControlSubscribedMixRoom,
                                                                                         mHostedControlReplayPendingAckKeys,
                                                                                         activeRoom);
        addHostedControlDiagnosticEvent(String("room-state-replay local-overwrite for resync reason=ack-") + commandResolveFailure
                                        + " command=" + (trimmedCommand.isNotEmpty() ? trimmedCommand : String("<none>"))
                                        + " rules=" + hostedControlBuildDeterministicOverwriteRulesText(overwriteRules)
                                        + " pendingAck=" + String(mHostedControlReplayPendingAckKeys.size()));

        String resyncReason = "ack-" + commandResolveFailure;
        if (resyncReason.trim().isEmpty() || resyncReason == "ack-") {
            resyncReason = "ack-command-resolution";
        }
        hostedControlRequestStateResync(resyncReason);
        return false;
    }

    const bool allowParticipantWildcard = (participant.isEmpty() && canonicalResolvedCommand == "participant.mix.set");
    const int pendingIndex = hostedControlFindPendingReplayAckIndex(mHostedControlReplayPendingAckKeys,
                                                                    trimmedCommand,
                                                                    room,
                                                                    participant,
                                                                    allowParticipantWildcard);

    if (!accepted) {
        hostedControlRemovePendingReplayAckAtIndex(mHostedControlReplayPendingAckKeys, pendingIndex);
        const String expectedPreview = hostedControlBuildPendingAckExpectedPreview(mHostedControlReplayPendingAckKeys,
                                                                                    trimmedCommand);
        addHostedControlDiagnosticEvent(hostedControlBuildAckDiagnosticLine("rejected",
                                                                             trimmedCommand,
                                                                             room,
                                                                             participant,
                                                                             ackContext,
                                                                             mHostedControlReplayPendingAckKeys.size(),
                                                                             expectedPreview));
        const auto overwriteRules = hostedControlApplyDeterministicResyncOverwriteRules(mHostedControlSubscribedMixRoom,
                                                                                         mHostedControlReplayPendingAckKeys,
                                                                                         activeRoom);
        addHostedControlDiagnosticEvent(String("room-state-replay local-overwrite for resync reason=ack-rejected")
                                        + " command=" + (trimmedCommand.isNotEmpty() ? trimmedCommand : String("<none>"))
                                        + " rules=" + hostedControlBuildDeterministicOverwriteRulesText(overwriteRules)
                                        + " pendingAck=" + String(mHostedControlReplayPendingAckKeys.size()));
        hostedControlRequestStateResync("ack-rejected-" + (trimmedCommand.isNotEmpty() ? trimmedCommand : String("unknown")));
        return false;
    }

    if (pendingIndex >= 0) {
        hostedControlRemovePendingReplayAckAtIndex(mHostedControlReplayPendingAckKeys, pendingIndex);
        addHostedControlDiagnosticEvent(hostedControlBuildAckDiagnosticLine("reconciled",
                                                                             trimmedCommand,
                                                                             room,
                                                                             participant,
                                                                             ackContext,
                                                                             mHostedControlReplayPendingAckKeys.size()));
        return true;
    }

    const String expectedPreview = hostedControlBuildPendingAckExpectedPreview(mHostedControlReplayPendingAckKeys,
                                                                                trimmedCommand);

    addHostedControlDiagnosticEvent(hostedControlBuildAckDiagnosticLine("mismatch",
                                                                         trimmedCommand,
                                                                         room,
                                                                         participant,
                                                                         ackContext,
                                                                         mHostedControlReplayPendingAckKeys.size(),
                                                                         expectedPreview));
    const auto overwriteRules = hostedControlApplyDeterministicResyncOverwriteRules(mHostedControlSubscribedMixRoom,
                                                                                     mHostedControlReplayPendingAckKeys,
                                                                                     activeRoom);
    addHostedControlDiagnosticEvent(String("room-state-replay local-overwrite for resync reason=ack-mismatch")
                                    + " command=" + (trimmedCommand.isNotEmpty() ? trimmedCommand : String("<none>"))
                                    + " rules=" + hostedControlBuildDeterministicOverwriteRulesText(overwriteRules)
                                    + " pendingAck=" + String(mHostedControlReplayPendingAckKeys.size()));
    hostedControlRequestStateResync("ack-mismatch-" + (trimmedCommand.isNotEmpty() ? trimmedCommand : String("unknown")));
    return false;
}

bool SonobusAudioProcessor::debugHostedControlApplyServerAckScaffold(const String & command, const String & payloadJson, bool accepted)
{
    // Debug entry point delegates to the shared hosted ack/reconcile scaffold path so live-path and
    // debug-path behavior remain aligned.
    return hostedControlApplyServerAckScaffold(command, payloadJson, accepted);
}

bool SonobusAudioProcessor::debugHostedControlEvaluateWsConnectTimeoutScaffoldForElapsedMs(int elapsedMs, const String & triggerReason)
{
    if (elapsedMs < 0) {
        elapsedMs = 0;
    }

    const auto nowMs = Time::currentTimeMillis();
    mHostedControlWsConnectStartedAtMs = nowMs - static_cast<int64>(elapsedMs);
    if (mHostedControlWsConnectTimeoutMs <= 0) {
        mHostedControlWsConnectTimeoutMs = 4000;
    }

    auto wsState = static_cast<HostedControlWsLifecycleState>(mHostedControlWsLifecycleState.get());
    if (wsState != HostedControlWsConnecting) {
        hostedControlSetWsLifecycleState(HostedControlWsConnecting);
    }

    auto reason = triggerReason.trim();
    if (reason.isEmpty()) {
        reason = "debug-sim";
    }
    return hostedControlEvaluateWebSocketConnectTimeoutScaffold(reason + " elapsed=" + String(elapsedMs) + "ms");
}

bool SonobusAudioProcessor::canFlushHostedQueuedSendsScaffold(String * reason) const
{
    if (getHostedControlTransportMode() != HostedControlTransportWebSocket) {
        if (reason) *reason = "transport not websocket";
        return false;
    }
    if (!isHostedControlConnected()) {
        if (reason) *reason = "control disconnected";
        return false;
    }
    if (mHostedControlWsQueuedCommands.isEmpty()) {
        if (reason) *reason = "queue is empty";
        return false;
    }

    if (reason) reason->clear();
    return true;
}

