SonobusAudioProcessor::EndpointState * SonobusAudioProcessor::findOrAddRawEndpoint(void * rawaddr)
{
    String ipaddr;
    int port = 0 ;

    char hostip[INET6_ADDRSTRLEN];
    if (inet_ntop(AF_INET, get_in_addr((struct sockaddr *)rawaddr), hostip, sizeof(hostip)) == nullptr) {
        DBG("Error converting raw addr to IP");
        return nullptr;
    } else {
        ipaddr = hostip;
        port = ntohs(get_in_port((struct sockaddr *)rawaddr));        
        return findOrAddEndpoint(ipaddr, port);    
    }    
}

SonobusAudioProcessor::EndpointState * SonobusAudioProcessor::findOrAddEndpoint(const String & host, int port)
{
    const ScopedLock sl (mEndpointsLock);        
    
    EndpointState * endpoint = 0;
    
    for (auto ep : mEndpoints) {
        if (ep->ipaddr == host && ep->port == port) {
            endpoint = ep;
            break;
        }
    }
    
    if (!endpoint) {
        // add it as new
        endpoint = mEndpoints.add(new EndpointState(host, port));
        endpoint->owner = mUdpSocket.get();
        endpoint->peer = std::make_unique<DatagramSocket::RemoteAddrInfo>(host, port);
        DBG("Added new endpoint for " << host << ":" << port);
    }
    return endpoint;
}

SonobusAudioProcessor::EndpointState * SonobusAudioProcessor::findEndpointFast(uint32_t ipv4, int port)
{
    // Same identity as findOrAddEndpoint
    // (dotted-quad + port) but compared as integers; no String, no alloc.
    const ScopedLock sl (mEndpointsLock);
    for (auto ep : mEndpoints) {
        if (ep->ipv4 == ipv4 && ep->port == port) {
            return ep;
        }
    }
    return nullptr;
}

void SonobusAudioProcessor::updateSafetyMuting(RemotePeer * peer)
{
    // assumed corelock already held
    //const float droprate =  (peer->dataPacketsDropped) / ((nowtime - peer->resetDroptime)*1e-3);
    const float droprate = peer->fastDropRate.xbar;
    const float safetyunmutethreshrate = 2.0f;
    const float safetyunmutethreshmintime = 0.5f;
    const float safetyunmutethreshtime = 0.75f;
    const float jitterbufthresh = 15.0f;

    double nowtime = Time::getMillisecondCounterHiRes();
    double timesincereset = (nowtime - peer->resetDroptime) * 1e-3;
    double deltadroptime = peer->lastDroptime > 0 ? (nowtime - peer->lastDroptime) * 1e-3 : timesincereset;


    if ((timesincereset > safetyunmutethreshmintime)
        && ((droprate > 0.0f && droprate < safetyunmutethreshrate)
            || (droprate == 0.0f && deltadroptime > safetyunmutethreshtime)
            || (peer->buffertimeMs > jitterbufthresh))) {
        DBG("Droprate: " << droprate << "  deltatime: " << deltadroptime << " buftimems: " << peer->buffertimeMs);
        DBG("Unmuting after reset drop");
        peer->resetSafetyMuted = false;
    }

    peer->fastDropRate.Z *= 0.965;

    float realdroprate =  (peer->dataPacketsDropped - peer->lastDropCount) / deltadroptime;
    peer->fastDropRate.push(realdroprate);

}

// Compact data message layout (deps/aoo
// source.cpp endpoint::send_data_compact / sink.cpp handle_compact_data_message):
//   OSC address "/d" -> padded to 4 bytes  "/d\0\0"
//   typetag     ",iib" (salt, seq, blob) or ",iidb" (salt, seq, srate, blob)
//               -> both pad to 8 bytes
//   args        int32 salt (big-endian) at byte offset 12
// The sink identifies the source purely by (endpoint, salt) —
// sink::find_source_by_salt — so (endpoint, salt) is exactly the key the
// sink itself uses; we just remember which sink answered last time.
static inline bool sbParseCompactSalt(const char * buf, int nbytes, int32_t & salt)
{
    if (nbytes < 16) return false;
    if (buf[0] != '/' || buf[1] != 'd' || buf[2] != 0 || buf[3] != 0) return false;
    if (buf[4] != ',' || buf[5] != 'i' || buf[6] != 'i') return false;
    uint32_t be;
    memcpy(&be, buf + 12, 4);
    salt = (int32_t) ntohl(be);
    return true;
}

static inline unsigned sbSinkDispatchSlot(const void * ep, int32_t salt, int slots)
{
    const uintptr_t p = (uintptr_t) ep;
    uint32_t h = (uint32_t) (p >> 4) ^ (uint32_t) salt;
    h ^= h >> 16;
    h *= 0x7feb352dU;
    h ^= h >> 15;
    return (unsigned) (h & (uint32_t)(slots - 1));
}

// Recvmsg with the kernel's monotonic receive timestamp (ns since boot on the mach clock; 0 = none).
// Mirrors hubRecvKts in SonobusHubServer.cpp. Flags are passed through (MSG_DONTWAIT on the drain loop).
#if !JUCE_WINDOWS
static ssize_t sbRecvKts(int fd, char* buf, size_t len, int flags, struct sockaddr* sa, socklen_t* salen, uint64_t* ktsNs) {
    struct iovec iov; iov.iov_base = buf; iov.iov_len = len;
    alignas(8) char cbuf[64];
    struct msghdr mh; memset(&mh, 0, sizeof(mh));
    mh.msg_name = sa; mh.msg_namelen = *salen; mh.msg_iov = &iov; mh.msg_iovlen = 1; mh.msg_control = cbuf; mh.msg_controllen = sizeof(cbuf);
    ssize_t n = ::recvmsg(fd, &mh, flags);
    *ktsNs = 0;
    if (n >= 0) {
        *salen = mh.msg_namelen;
        for (struct cmsghdr* c = CMSG_FIRSTHDR(&mh); c; c = CMSG_NXTHDR(&mh, c)) {
#if defined(__APPLE__)
            if (c->cmsg_level == SOL_SOCKET && c->cmsg_type == SCM_TIMESTAMP_MONOTONIC && c->cmsg_len >= CMSG_LEN(sizeof(uint64_t))) {
                uint64_t t; memcpy(&t, CMSG_DATA(c), sizeof(t));
                static mach_timebase_info_data_t tb = {0, 0};
                if (tb.denom == 0) mach_timebase_info(&tb);
                *ktsNs = t * tb.numer / tb.denom;
            }
#elif defined(__linux__)
            if (c->cmsg_level == SOL_SOCKET && c->cmsg_type == SCM_TIMESTAMPNS && c->cmsg_len >= CMSG_LEN(sizeof(struct timespec))) {
                struct timespec rt; memcpy(&rt, CMSG_DATA(c), sizeof(rt));
                static const int64_t off = []{ struct timespec m, r; clock_gettime(CLOCK_MONOTONIC, &m); clock_gettime(CLOCK_REALTIME, &r);
                    return ((int64_t) m.tv_sec * 1000000000LL + m.tv_nsec) - ((int64_t) r.tv_sec * 1000000000LL + r.tv_nsec); }();
                *ktsNs = (uint64_t)(((int64_t) rt.tv_sec * 1000000000LL + rt.tv_nsec) + off);
            }
#endif
        }
    }
    return n;
}
static uint64_t sbNowNs() {
#if defined(__APPLE__)
    static mach_timebase_info_data_t tb = {0, 0};
    if (tb.denom == 0) mach_timebase_info(&tb);
    return mach_absolute_time() * tb.numer / tb.denom;
#else
    struct timespec m; clock_gettime(CLOCK_MONOTONIC, &m); return (uint64_t) m.tv_sec * 1000000000ULL + (uint64_t) m.tv_nsec;
#endif
}
#endif

void SonobusAudioProcessor::doReceiveData()
{
    // One select wake drains every datagram already queued, so only the first packet pays select()
    // + fcntl(F_GETFL) + String construction. Bounded so the thread still observes
    // threadShouldExit() under a flood; leftover packets make the next waitUntilReady() return at
    // once.
    char buf[AOO_MAXPACKETSIZE];
    constexpr int kMaxPacketsPerWake = 128;
    int npackets = 0;
    bool needNotify = false;

#if JUCE_WINDOWS
    // portable fallback: JUCE path (no MSG_DONTWAIT on WinSock), one packet
    {
        String senderIP;
        int senderPort = 0;
        int nbytes = mUdpSocket->read(buf, AOO_MAXPACKETSIZE, false, senderIP, senderPort);
        if (nbytes <= 0) return;
        EndpointState * endpoint = findOrAddEndpoint(senderIP, senderPort);
        if (!endpoint) return;
        endpoint->recvBytes += nbytes + UDP_OVERHEAD_BYTES;
        ++npackets;
        needNotify = handleReceivedPacket(buf, nbytes, endpoint);
    }
#else
    const int fd = mUdpSocket->getRawSocketHandle();
    if (fd < 0) return;

    while (npackets < kMaxPacketsPerWake) {
        struct sockaddr_in from;
        socklen_t fromlen = sizeof(from);
        uint64_t ktsNs = 0;
        const ssize_t nbytes = sbRecvKts(fd, buf, sizeof(buf), MSG_DONTWAIT, (struct sockaddr *) &from, &fromlen, &ktsNs);
        if (nbytes > 0 && ktsNs != 0) {   // How late is the recv thread behind the kernel's arrival?
            const uint64_t now = sbNowNs();
            const uint32_t latUs = now > ktsNs ? (uint32_t) ((now - ktsNs) / 1000ULL) : 0u;
            uint32_t cur = mSbRxLatMaxUs.load(std::memory_order_relaxed);
            while (latUs > cur && !mSbRxLatMaxUs.compare_exchange_weak(cur, latUs, std::memory_order_relaxed)) {}
            if (latUs > 2000) mSbRxLatOver2ms.fetch_add(1, std::memory_order_relaxed);
            mSbRxPackets.fetch_add(1, std::memory_order_relaxed);
        }

        if (nbytes < 0) {
            // EAGAIN/EWOULDBLOCK = drained; EINTR = retry on next wake; anything else reports
            // "Error receiving UDP".
            break;
        }
        if (nbytes == 0) {
            continue; // zero-length datagram: consumed, nothing to parse
        }

        // Endpoint identity by (addr, port) integers, no String. Same identity as findOrAddEndpoint
        // (dotted-quad + port), so a NAT port change mints a distinct endpoint.
        const uint32_t addr = from.sin_addr.s_addr;
        const int port = (int) ntohs(from.sin_port);
        EndpointState * endpoint = nullptr;

        if (mRecvLastEndpoint != nullptr && mRecvLastAddr == addr && mRecvLastPort == port) {
            endpoint = mRecvLastEndpoint;
        } else {
            mNetStatEndpointCacheMiss.fetch_add(1, std::memory_order_relaxed);
            endpoint = findEndpointFast(addr, port);
            if (endpoint == nullptr) {
                // New endpoint only: build the String once (allocates) and go through
                // findOrAddEndpoint so EndpointState::ipaddr and peer are populated.
                mNetStatEndpointStringPath.fetch_add(1, std::memory_order_relaxed);
                char hostip[INET_ADDRSTRLEN];
                if (inet_ntop(AF_INET, &from.sin_addr, hostip, sizeof(hostip)) == nullptr) {
                    continue;
                }
                endpoint = findOrAddEndpoint(String::fromUTF8(hostip), port);
                if (endpoint == nullptr) continue;
            }
            endpoint->setRawAddrIfUnset(from);
            mRecvLastEndpoint = endpoint;
            mRecvLastAddr = addr;
            mRecvLastPort = port;
        }

        endpoint->recvBytes += nbytes + UDP_OVERHEAD_BYTES;
        ++npackets;

        if (handleReceivedPacket(buf, (int) nbytes, endpoint)) {
            needNotify = true;
        }
    }
    {   // Biggest drain per wake (a backlog = the recv thread was away)
        uint32_t c = mSbRxMaxPerWake.load(std::memory_order_relaxed);
        while ((uint32_t) npackets > c && !mSbRxMaxPerWake.compare_exchange_weak(c, (uint32_t) npackets, std::memory_order_relaxed)) {}
    }
#endif

    if (npackets > 0) {
        mNetStatRecvWakes.fetch_add(1, std::memory_order_relaxed);
        mNetStatRecvPackets.fetch_add((uint64_t) npackets, std::memory_order_relaxed);
        if ((uint64_t) npackets > mNetStatRecvMaxBurst.load(std::memory_order_relaxed)) {
            mNetStatRecvMaxBurst.store((uint64_t) npackets, std::memory_order_relaxed);
        }
    }

    // Notify the send thread once per burst, not per AOO packet; the sink/source replies queued by
    // handle_message() are flushed by the same doSendData() pass, at most a burst-drain (µs) later.
    if (needNotify) {
        notifySendThread();
    }
}

bool SonobusAudioProcessor::handleReceivedPacket(const char * buf, int nbytes, EndpointState * endpoint, int depth)
{
    // A bundling hub packs one listener slot's feed datagrams into one OSC bundle. Unpack here,
    // before any single-message handling, and push every element through the code path a bare
    // datagram takes below, so the (endpoint,salt) dispatch cache and the dup-skip work per
    // element. Hand-rolled, exception-free, no allocation: this is the recv thread. Malformed input
    // is dropped silently (counted). Bare datagrams fall through unchanged.
    if (nbytes >= 16 && memcmp(buf, "#bundle\0", 8) == 0) {
        if (depth >= 2) {   // nested deeper than one level: not ours, drop
            mNetStatBundleBad.fetch_add(1, std::memory_order_relaxed);
            return false;
        }
        mNetStatBundlesRecv.fetch_add(1, std::memory_order_relaxed);
        bool anyAoo = false;
        int off = 16;   // skip "#bundle\0" + 8-byte timetag (immediate; ignored)
        while (off + 4 <= nbytes) {
            uint32_t be;
            memcpy(&be, buf + off, 4);
            const int32_t size = (int32_t) ntohl(be);
            off += 4;
            if (size <= 0 || (size & 3) != 0 || off + size > nbytes) {
                mNetStatBundleBad.fetch_add(1, std::memory_order_relaxed);
                return anyAoo;   // element is corrupt: stop, keep what was already dispatched
            }
            mNetStatBundleMsgs.fetch_add(1, std::memory_order_relaxed);
            if (handleReceivedPacket(buf + off, size, endpoint, depth + 1)) {
                anyAoo = true;
            }
            off += size;
        }
        if (off != nbytes) {   // trailing bytes that are not a full size prefix
            mNetStatBundleBad.fetch_add(1, std::memory_order_relaxed);
        }
        return anyAoo;
    }

    // parse packet for AOO events

    int32_t type, id, dummyid;
    if ((aoo_parse_pattern(buf, nbytes, &type, &id) > 0)
        || (aoonet_parse_pattern(buf, nbytes, &type) > 0))
    {
        {

            if (type == AOO_TYPE_SINK){
                // forward OSC packet to matching sink(s)
                const ScopedReadLock sl (mCoreLock);

                // Compact data ("/d") fast path. Try the sink that last accepted this (endpoint,
                // salt) before scanning all peers. Nothing here allocates; the sink's own
                // handle_message() is the validator.
                if (id == AOO_ID_NONE) {
                    int32_t salt = 0;
                    const bool haveSalt = sbParseCompactSalt(buf, nbytes, salt);
                    SinkDispatchEntry * slot = nullptr;
                    bool cachedSinkRejected = false;
                    if (haveSalt) {
                        slot = &mSinkDispatch[sbSinkDispatchSlot(endpoint, salt, kSinkDispatchSlots)];
                        // mRemotePeers is re-indexed on every join/leave, so a cached peerIndex can
                        // point at the wrong peer's sink after a rejoin. The cached entry must also
                        // match by peer identity, and a rejection from a mismatched or stale entry
                        // falls through to the full scan.
                        if (slot->ep == endpoint && slot->salt == salt
                            && slot->peerIndex >= 0 && slot->peerIndex < mRemotePeers.size()
                            && slot->peer == (const void *) mRemotePeers.getUnchecked(slot->peerIndex))
                        {
                            auto * remote = mRemotePeers.getUnchecked(slot->peerIndex);
                            if (!remote->infoOnly && remote->oursink) {
                                if (remote->oursink->handle_message(buf, nbytes, endpoint, endpoint_send)) {
                                    mNetStatDispatchHits.fetch_add(1, std::memory_order_relaxed);
                                    remote->dataPacketsReceived += 1;
                                    if (remote->recvAllow && !remote->recvActive) {
                                        remote->recvActive = true;
                                    }
                                    if (remote->resetSafetyMuted) {
                                        updateSafetyMuting(remote);
                                    }
                                    return true;
                                }
                                cachedSinkRejected = true;
                            }
                        }
                    }
                    // The cached sink is the only sink that can own this (endpoint, salt); it
                    // accepted that exact pair before. A rejection by the identity-verified cached
                    // sink is most likely a redundancy duplicate or late packet (check_packet or
                    // add_packet said no) that every other sink would reject too, so skip the peer
                    // scan. Rescan every 64th rejection so a sink that has gone bad (format reset,
                    // salt change) can never park a stream forever.
                    if (cachedSinkRejected) {
                        mNetStatDispatchDups.fetch_add(1, std::memory_order_relaxed);
                        static thread_local uint32_t dupRescan = 0;
                        if ((++dupRescan & 63u) != 0u) return true;
                        if (slot) slot->peerIndex = -1;   // force re-learn below
                    }
                    mNetStatDispatchMisses.fetch_add(1, std::memory_order_relaxed);

                    // full scan (original behaviour): first sink to accept wins
                    for (int pi = 0; pi < mRemotePeers.size(); ++pi) {
                        auto * remote = mRemotePeers.getUnchecked(pi);
                        if (remote->infoOnly) continue;
                        if (!remote->oursink) continue;

                        if (remote->oursink->handle_message(buf, nbytes, endpoint, endpoint_send)) {
                            remote->dataPacketsReceived += 1;
                            if (remote->recvAllow && !remote->recvActive) {
                                remote->recvActive = true;
                            }
                            if (remote->resetSafetyMuted) {
                                updateSafetyMuting(remote);
                            }
                            if (slot) {
                                slot->ep = endpoint;
                                slot->salt = salt;
                                slot->peerIndex = pi;
                                slot->peer = (const void *) remote;   // Identity, not just index
                            }
                            break;
                        }
                        // (id == AOO_ID_NONE can never equal a real sink id, so the
                        // wildcard/echo/latency checks below are unreachable for compact packets.)
                    }
                    return true;
                }

                for (auto & remote : mRemotePeers) {
                    if (remote->infoOnly) continue;
                    if (!remote->oursink) continue;

                    if (id == AOO_ID_WILDCARD || (remote->oursink->get_id(dummyid) && id == dummyid) ) {
                        if (remote->oursink->handle_message(buf, nbytes, endpoint, endpoint_send)) {
                            remote->dataPacketsReceived += 1;
                            if (remote->recvAllow && !remote->recvActive) {
                                remote->recvActive = true;
                            }
                            if (remote->resetSafetyMuted) {
                                updateSafetyMuting(remote);
                            }
                        }
                        
                        if (id != AOO_ID_WILDCARD) break;
                    }
                    
                    if (remote->echosink && remote->echosink->get_id(dummyid) && id == dummyid) {
                        remote->echosink->handle_message(buf, nbytes, endpoint, endpoint_send);
                        break;
                    }
                    else if (remote->latencysink && remote->latencysink->get_id(dummyid) && id == dummyid) {
                        remote->latencysink->handle_message(buf, nbytes, endpoint, endpoint_send);
                        break;
                    }
                    
                }
                
            } else if (type == AOO_TYPE_SOURCE){
                // forward OSC packet to matching sources(s)
                const ScopedReadLock sl (mCoreLock);        

                
                if (mAooDummySource->get_id(dummyid) && id == dummyid) {
                    // this is the special one that can accept blind invites
                    mAooDummySource->handle_message(buf, nbytes, endpoint, endpoint_send);
                }
                else {
                    for (auto & remote : mRemotePeers) {
                        if (remote->infoOnly) continue;
                        if (!remote->oursource) continue;
                        if (id == AOO_ID_WILDCARD || (remote->oursource->get_id(dummyid) && id == dummyid)) {
                            remote->oursource->handle_message(buf, nbytes, endpoint, endpoint_send);
                            if (id != AOO_ID_WILDCARD) break;
                        }
                        
                        if (remote->echosource && remote->echosource->get_id(dummyid) && id == dummyid) {
                            remote->echosource->handle_message(buf, nbytes, endpoint, endpoint_send);
                            break;
                        }
                        else if (remote->latencysource && remote->latencysource->get_id(dummyid) && id == dummyid) {
                            remote->latencysource->handle_message(buf, nbytes, endpoint, endpoint_send);
                            break;
                        }
                    }
                }

                
            } else if (type == AOO_TYPE_CLIENT || type == AOO_TYPE_PEER){
                // forward OSC packet to matching client

                //DBG("Got AOO_CLIENT or PEER data");

                if (mAooClient) {
                    mAooClient->handle_message(buf, nbytes, endpoint->getRawAddr());
                }
                
                /*
                 for (int i = 0; i < x->x_numclients; ++i){
                 if (pd_class(x->x_clients[i].c_obj) == aoo_client_class)
                 {
                 t_aoo_client *c = (t_aoo_client *)x->x_clients[i].c_obj;
                 aoo_client_handle_message(c, buf, nbytes,
                 ep, (aoo_replyfn)endpoint_send);
                 break;
                 }
                 }
                 */
            } else if (type == AOO_TYPE_SERVER){
                // ignore
                DBG("Got AOO_SERVER data");

                if (mAooServer) {
                    // mAooServer->handle_message(buf, nbytes, endpoint);
                }
                
            } else {
                DBG("SonoBus bug: unknown aoo type: " << type);
            }
        }

        // caller notifies the send thread once per drained burst
        return true;
    }
    else if (handleOtherMessage(endpoint, buf, nbytes)) {

    }
    else {
        // not a valid AoO OSC message
        DBG("SonoBus: not a valid AOO message!");
    }

    return false;
}

// XXX
// all of this should be refactored into its own class

#define SONOBUS_MSG_DOMAIN "/sb"
#define SONOBUS_MSG_DOMAIN_LEN 3

#define SONOBUS_MSG_PEERINFO "/pinfo"
#define SONOBUS_MSG_PEERINFO_LEN 6
#define SONOBUS_FULLMSG_PEERINFO SONOBUS_MSG_DOMAIN SONOBUS_MSG_PEERINFO

#define SONOBUS_MSG_LAYOUTINFO "/clayinfo"
#define SONOBUS_MSG_LAYOUTINFO_LEN 9
#define SONOBUS_FULLMSG_LAYOUTINFO SONOBUS_MSG_DOMAIN SONOBUS_MSG_LAYOUTINFO

#define SONOBUS_MSG_CHAT "/chat"
#define SONOBUS_MSG_CHAT_LEN 5
#define SONOBUS_FULLMSG_CHAT SONOBUS_MSG_DOMAIN SONOBUS_MSG_CHAT

#define SONOBUS_MSG_PING "/ping"
#define SONOBUS_MSG_PING_LEN 5
#define SONOBUS_FULLMSG_PING SONOBUS_MSG_DOMAIN SONOBUS_MSG_PING

#define SONOBUS_MSG_PINGACK "/pngack"
#define SONOBUS_MSG_PINGACK_LEN 7
#define SONOBUS_FULLMSG_PINGACK SONOBUS_MSG_DOMAIN SONOBUS_MSG_PINGACK

#define SONOBUS_MSG_REQLATINFO "/reqlatinfo"
#define SONOBUS_MSG_REQLATINFO_LEN 12
#define SONOBUS_FULLMSG_REQLATINFO SONOBUS_MSG_DOMAIN SONOBUS_MSG_REQLATINFO

#define SONOBUS_MSG_LATINFO "/latinfo"
#define SONOBUS_MSG_LATINFO_LEN 8
#define SONOBUS_FULLMSG_LATINFO SONOBUS_MSG_DOMAIN SONOBUS_MSG_LATINFO

#define SONOBUS_MSG_SUGGESTLAT "/suggestlat"
#define SONOBUS_MSG_SUGGESTLAT_LEN 11
#define SONOBUS_FULLMSG_SUGGESTLAT SONOBUS_MSG_DOMAIN SONOBUS_MSG_SUGGESTLAT

#define SONOBUS_MSG_BLOCKEDINFO "/blockedinfo"
#define SONOBUS_MSG_BLOCKEDINFO_LEN 13
#define SONOBUS_FULLMSG_BLOCKEDINFO SONOBUS_MSG_DOMAIN SONOBUS_MSG_BLOCKEDINFO

#define SONOBUS_MSG_SUGGEST_GROUP "/suggestgroup"
#define SONOBUS_MSG_SUGGEST_GROUP_LEN 14
#define SONOBUS_FULLMSG_SUGGEST_GROUP SONOBUS_MSG_DOMAIN SONOBUS_MSG_SUGGEST_GROUP

// Per-peer pre-mix level message for virtual meters on info-only rows. See SonobusHubMixControl.h.
#define SONOBUS_MSG_HXLEVEL "/hxlevel"
#define SONOBUS_MSG_HXLEVEL_LEN 8
#define SONOBUS_FULLMSG_HXLEVEL SONOBUS_MSG_DOMAIN SONOBUS_MSG_HXLEVEL

// Fires once at peer-join when the hub adds the client, telling the client "I am the hub, here's my
// user name + audio UDP port." Self-heals the case where AOO PEER_JOIN for the hub peer never fired
// at the client. See SonobusHubMixControl.h SB_HXFULLMSG_HUBHELLO for the wire format.
#define SONOBUS_MSG_HXHUBHELLO "/hxhubhello"
#define SONOBUS_MSG_HXHUBHELLO_LEN 11
#define SONOBUS_FULLMSG_HXHUBHELLO SONOBUS_MSG_DOMAIN SONOBUS_MSG_HXHUBHELLO

// Hub -> every hosted client, ~1 Hz per other player: "/sb/hxlat s:userName f:toHubMs f:fromHubMs".
// toHub = that player's uplink one-way (sink-ping RTT/2) + the hub's inbound buffer for them;
// fromHub = hub->player one-way (source-ping RTT/2).
#define SONOBUS_MSG_HXLAT "/hxlat"
#define SONOBUS_MSG_HXLAT_LEN 6
// Hub -> every player the moment someone starts/stops recording: "/sb/hxrecstate s:userName i:rec".
#define SONOBUS_MSG_HXRECSTATE "/hxrecstate"
#define SONOBUS_MSG_HXRECSTATE_LEN 11
// Hub -> every player when someone mutes/unmutes their send: "/sb/hxsendmutestate s:userName i:muted".
#define SONOBUS_MSG_HXSENDMUTESTATE "/hxsendmutestate"
#define SONOBUS_MSG_HXSENDMUTESTATE_LEN 16
// Hub -> one WAN player: "/sb/fwprobe/req h:token i:udpPort i:serverPort" — probe the hub's ports from outside.
#define SONOBUS_MSG_FWPROBEREQ "/fwprobe/req"
#define SONOBUS_MSG_FWPROBEREQ_LEN 12
#define SONOBUS_FULLMSG_HXLAT SONOBUS_MSG_DOMAIN SONOBUS_MSG_HXLAT


enum {
    SONOBUS_MSGTYPE_UNKNOWN = 0,
    SONOBUS_MSGTYPE_PEERINFO,
    SONOBUS_MSGTYPE_LAYOUTINFO,
    SONOBUS_MSGTYPE_CHAT,
    SONOBUS_MSGTYPE_PING,
    SONOBUS_MSGTYPE_PINGACK,
    SONOBUS_MSGTYPE_REQLATINFO,
    SONOBUS_MSGTYPE_LATINFO,
    SONOBUS_MSGTYPE_SUGGESTLAT,
    SONOBUS_MSGTYPE_BLOCKEDINFO,
    SONOBUS_MSGTYPE_SUGGESTGROUP,
    SONOBUS_MSGTYPE_HXLEVEL,
    SONOBUS_MSGTYPE_HXHUBHELLO,
    SONOBUS_MSGTYPE_HXLAT,
    SONOBUS_MSGTYPE_HXRECSTATE,
    SONOBUS_MSGTYPE_HXSENDMUTESTATE,   
    SONOBUS_MSGTYPE_FWPROBEREQ   
};

static int32_t sonobusOscParsePattern(const char *msg, int32_t n, int32_t & rettype)
{
    int32_t offset = 0;
    if (n >= SONOBUS_MSG_DOMAIN_LEN
        && !memcmp(msg, SONOBUS_MSG_DOMAIN, SONOBUS_MSG_DOMAIN_LEN))
    {
        offset += SONOBUS_MSG_DOMAIN_LEN;

        if (n >= (offset + SONOBUS_MSG_PING_LEN)
            && !memcmp(msg + offset, SONOBUS_MSG_PING, SONOBUS_MSG_PING_LEN))
        {
            rettype = SONOBUS_MSGTYPE_PING;
            offset += SONOBUS_MSG_PING_LEN;
            return offset;
        }
        else if (n >= (offset + SONOBUS_MSG_PINGACK_LEN)
            && !memcmp(msg + offset, SONOBUS_MSG_PINGACK, SONOBUS_MSG_PINGACK_LEN))
        {
            rettype = SONOBUS_MSGTYPE_PINGACK;
            offset += SONOBUS_MSG_PINGACK_LEN;
            return offset;
        }
        else if (n >= (offset + SONOBUS_MSG_PEERINFO_LEN)
            && !memcmp(msg + offset, SONOBUS_MSG_PEERINFO, SONOBUS_MSG_PEERINFO_LEN))
        {
            rettype = SONOBUS_MSGTYPE_PEERINFO;
            offset += SONOBUS_MSG_PEERINFO_LEN;
            return offset;
        }
        else if (n >= (offset + SONOBUS_MSG_LAYOUTINFO_LEN)
            && !memcmp(msg + offset, SONOBUS_MSG_LAYOUTINFO, SONOBUS_MSG_LAYOUTINFO_LEN))
        {
            rettype = SONOBUS_MSGTYPE_LAYOUTINFO;
            offset += SONOBUS_MSG_LAYOUTINFO_LEN;
            return offset;
        }
        else if (n >= (offset + SONOBUS_MSG_CHAT_LEN)
            && !memcmp(msg + offset, SONOBUS_MSG_CHAT, SONOBUS_MSG_CHAT_LEN))
        {
            rettype = SONOBUS_MSGTYPE_CHAT;
            offset += SONOBUS_MSG_CHAT_LEN;
            return offset;
        }
        else if (n >= (offset + SONOBUS_MSG_REQLATINFO_LEN)
            && !memcmp(msg + offset, SONOBUS_MSG_REQLATINFO, SONOBUS_MSG_REQLATINFO_LEN))
        {
            rettype = SONOBUS_MSGTYPE_REQLATINFO;
            offset += SONOBUS_MSG_REQLATINFO_LEN;
            return offset;
        }
        else if (n >= (offset + SONOBUS_MSG_LATINFO_LEN)
            && !memcmp(msg + offset, SONOBUS_MSG_LATINFO, SONOBUS_MSG_LATINFO_LEN))
        {
            rettype = SONOBUS_MSGTYPE_LATINFO;
            offset += SONOBUS_MSG_LATINFO_LEN;
            return offset;
        }
        else if (n >= (offset + SONOBUS_MSG_SUGGESTLAT_LEN)
            && !memcmp(msg + offset, SONOBUS_MSG_SUGGESTLAT, SONOBUS_MSG_SUGGESTLAT_LEN))
        {
            rettype = SONOBUS_MSGTYPE_SUGGESTLAT;
            offset += SONOBUS_MSG_SUGGESTLAT_LEN;
            return offset;
        }
        else if (n >= (offset + SONOBUS_MSG_BLOCKEDINFO_LEN)
            && !memcmp(msg + offset, SONOBUS_MSG_BLOCKEDINFO, SONOBUS_MSG_BLOCKEDINFO_LEN))
        {
            rettype = SONOBUS_MSGTYPE_BLOCKEDINFO;
            offset += SONOBUS_MSG_BLOCKEDINFO_LEN;
            return offset;
        }
        else if (n >= (offset + SONOBUS_MSG_SUGGEST_GROUP_LEN)
            && !memcmp(msg + offset, SONOBUS_MSG_SUGGEST_GROUP, SONOBUS_MSG_SUGGEST_GROUP_LEN))
        {
            rettype = SONOBUS_MSGTYPE_SUGGESTGROUP;
            offset += SONOBUS_MSG_SUGGEST_GROUP_LEN;
            return offset;
        }
        else if (n >= (offset + SONOBUS_MSG_HXHUBHELLO_LEN)
            && !memcmp(msg + offset, SONOBUS_MSG_HXHUBHELLO, SONOBUS_MSG_HXHUBHELLO_LEN))
        {
            rettype = SONOBUS_MSGTYPE_HXHUBHELLO;
            offset += SONOBUS_MSG_HXHUBHELLO_LEN;
            return offset;
        }
        else if (n >= (offset + SONOBUS_MSG_HXLAT_LEN)
            && !memcmp(msg + offset, SONOBUS_MSG_HXLAT, SONOBUS_MSG_HXLAT_LEN))
        {
            rettype = SONOBUS_MSGTYPE_HXLAT;
            offset += SONOBUS_MSG_HXLAT_LEN;
            return offset;
        }
        else if (n >= (offset + SONOBUS_MSG_HXRECSTATE_LEN)
            && !memcmp(msg + offset, SONOBUS_MSG_HXRECSTATE, SONOBUS_MSG_HXRECSTATE_LEN))
        {
            rettype = SONOBUS_MSGTYPE_HXRECSTATE;
            offset += SONOBUS_MSG_HXRECSTATE_LEN;
            return offset;
        }
        else if (n >= (offset + SONOBUS_MSG_HXSENDMUTESTATE_LEN)
            && !memcmp(msg + offset, SONOBUS_MSG_HXSENDMUTESTATE, SONOBUS_MSG_HXSENDMUTESTATE_LEN))
        {
            rettype = SONOBUS_MSGTYPE_HXSENDMUTESTATE;   
            offset += SONOBUS_MSG_HXSENDMUTESTATE_LEN;
            return offset;
        }
        else if (n >= (offset + SONOBUS_MSG_FWPROBEREQ_LEN)
            && !memcmp(msg + offset, SONOBUS_MSG_FWPROBEREQ, SONOBUS_MSG_FWPROBEREQ_LEN))
        {
            rettype = SONOBUS_MSGTYPE_FWPROBEREQ;
            offset += SONOBUS_MSG_FWPROBEREQ_LEN;
            return offset;
        }
        else {
            return 0;
        }
    }
    return 0;
}

bool SonobusAudioProcessor::handleOtherMessage(EndpointState * endpoint, const char *msg, int32_t n)
{
    // try to parse it as an OSC /sb  message
    int32_t type = SONOBUS_MSGTYPE_UNKNOWN;
    int32_t onset = 0;

    if (! (onset = sonobusOscParsePattern(msg, n, type))) {
        return false;
    }

    try {
        osc::ReceivedPacket packet(msg, n);
        osc::ReceivedMessage message(packet);

        if (type == SONOBUS_MSGTYPE_PING) {
            // received from the other side
            // args: t:origtime

            auto it = message.ArgumentsBegin();
            auto tt = (it++)->AsTimeTag();

            // now prepare and send ack immediately
            auto tt2 = aoo_osctime_get(); // use real system time

            char buf[AOO_MAXPACKETSIZE];
            osc::OutboundPacketStream outmsg(buf, sizeof(buf));

            try {
                outmsg << osc::BeginMessage(SONOBUS_FULLMSG_PINGACK)
                << osc::TimeTag(tt) << osc::TimeTag(tt2)
                << osc::EndMessage;
            }
            catch (const osc::Exception& e){
                DBG("exception in pingack message constructions: " << e.what());
                return false;
            }

            endpoint_send(endpoint, outmsg.Data(), (int) outmsg.Size());

            DBG("Received ping from " << endpoint->ipaddr << ":" << endpoint->port << "  stamp: " << tt);

        }
        else if (type == SONOBUS_MSGTYPE_PINGACK) {
            // received from the other side
            // args: t:origtime t:theirtime

            auto it = message.ArgumentsBegin();
            auto tt = (it++)->AsTimeTag();
            auto tt2 = (it++)->AsTimeTag();
            auto tt3 = aoo_osctime_get(); // use real system time

            handlePingEvent(endpoint, tt, tt2, tt3); // jlc

        }
        else if (type == SONOBUS_MSGTYPE_PEERINFO) {
            // peerinfo message arguments:
            // blob containing JSON
            auto it = message.ArgumentsBegin();

            const void *infojson;
            osc::osc_bundle_element_size_t size;

            (it++)->AsBlob(infojson, size);

            String jsonstr = String::createStringFromData(infojson, size);

            juce::var infodata;
            auto result = juce::JSON::parse(jsonstr, infodata);
            if (result.failed()) {
                DBG("Peerinfo Json parsing failed: " << result.getErrorMessage());
                return false;
            }

            {
                const ScopedReadLock sl (mCoreLock);

                // find remote peer
                RemotePeer * peer = findRemotePeer(endpoint, -1);
                if (!peer) {
                    DBG("Could not find peer for endpoint");
                    return false;
                }

                handleRemotePeerInfoUpdate(peer, infodata);
            }

        }
        else if (type == SONOBUS_MSGTYPE_LAYOUTINFO) {
            // layout info message arguments:
            // i:sourceid  b:<blob containing valuetree in binary form>
            auto it = message.ArgumentsBegin();
            auto sourceid = (it++)->AsInt32();

            const void *info;
            osc::osc_bundle_element_size_t size;

            (it++)->AsBlob(info, size);
            // jlc

            ValueTree tree = ValueTree::readFromData (info, size);

            if (!tree.isValid()) {
                DBG("layoutinfo parsing failed ");
                return false;
            }
            else {
                DBG("Got layoutinfo");
            }

            bool changed = false;

            {
                const ScopedReadLock sl (mCoreLock);

                // find remote peer
                RemotePeer * peer = findRemotePeer(endpoint, sourceid);
                if (!peer) {
                    DBG("Could not find peer for endpoint: " << endpoint->ipaddr << "src: " <<  sourceid);
                }
                else {
                    peer->recvdChanLayout = true;
                    applyLayoutFormatToPeer(peer, tree);
                    changed = true;
                }
            }

            if (changed) {
                clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientPeerChangedState, this, "format");
            }


        }
        else if (type == SONOBUS_MSGTYPE_CHAT) {
            // layout info message arguments:
            // s:groupname s:from s:targets s:tags s:message
            auto it = message.ArgumentsBegin();

            String group (CharPointer_UTF8((it++)->AsString()));
            String from (CharPointer_UTF8((it++)->AsString()));
            String targets (CharPointer_UTF8((it++)->AsString()));
            String tags (CharPointer_UTF8((it++)->AsString()));
            String message (CharPointer_UTF8((it++)->AsString()));

            SBChatEvent chatevent(SBChatEvent::UserType, group, from, targets, tags, message);
            
            if (!isAddressBlocked(endpoint->ipaddr)) {
                
                mAllChatEvents.add(chatevent);
                clientListeners.call(&SonobusAudioProcessor::ClientListener::sbChatEventReceived, this, chatevent);
            }

        }
        else if (type == SONOBUS_MSGTYPE_REQLATINFO) {
            // received from the other side
            // args: none

            if (!isAddressBlocked(endpoint->ipaddr)) {

                
                auto latinfo = getAllLatInfo();
                
                char buf[AOO_MAXPACKETSIZE];
                osc::OutboundPacketStream outmsg(buf, sizeof(buf));
                
                String jsonstr = JSON::toString(latinfo, true, 6);
                
                if (jsonstr.getNumBytesAsUTF8() > AOO_MAXPACKETSIZE - 100) {
                    DBG("Info too big for packet!");
                    return false;
                }
                
                
                try {
                    outmsg << osc::BeginMessage(SONOBUS_FULLMSG_LATINFO)
                    << osc::Blob(jsonstr.toRawUTF8(), (int) jsonstr.getNumBytesAsUTF8())
                    << osc::EndMessage;
                }
                catch (const osc::Exception& e){
                    DBG("exception in reqlat message constructions: " << e.what());
                    return false;
                }
                
                endpoint_send(endpoint, outmsg.Data(), (int) outmsg.Size());
                
                DBG("Received REQLAT from " << endpoint->ipaddr << ":" << endpoint->port);
            }

        }
        else if (type == SONOBUS_MSGTYPE_LATINFO) {
            // peerinfo message arguments:
            // blob containing JSON
            auto it = message.ArgumentsBegin();

            const void *infojson;
            osc::osc_bundle_element_size_t size;

            (it++)->AsBlob(infojson, size);

            String jsonstr = String::createStringFromData(infojson, size);

            juce::var infodata;
            auto result = juce::JSON::parse(jsonstr, infodata);
            if (result.failed()) {
                DBG("Peerinfo Json parsing failed: " << result.getErrorMessage());
                return false;
            }

            handleLatInfo(infodata);

        }
        else if (type == SONOBUS_MSGTYPE_SUGGESTLAT) {
            // received from the other side
            // args: s:username  f:latency

            auto it = message.ArgumentsBegin();
            auto username = String(CharPointer_UTF8((it++)->AsString()));
            auto latency = (it++)->AsFloat();

            if (!isAddressBlocked(endpoint->ipaddr)) {
                clientListeners.call(&SonobusAudioProcessor::ClientListener::peerRequestedLatencyMatch, this, username, latency);
            }
        }
        else if (type == SONOBUS_MSGTYPE_SUGGESTGROUP) {
            // received from the other side
            // args: s:username  s:newgroup s:ispublic

            auto it = message.ArgumentsBegin();
            if (message.ArgumentCount() >= 1) {
                const void *infojson;
                osc::osc_bundle_element_size_t size;

                (it++)->AsBlob(infojson, size);

                String jsonstr = String::createStringFromData(infojson, size);

                juce::var infodata;
                auto result = juce::JSON::parse(jsonstr, infodata);

                if (!isAddressBlocked(endpoint->ipaddr) && infodata.isObject()) {
                    auto username = infodata.getProperty("user", "");
                    auto newgroup = infodata.getProperty("group", "");
                    auto grouppass = infodata.getProperty("group_pass", "");
                    auto ispublic = infodata.getProperty("public", false);
                    auto others = infodata.getProperty("others", {});
                    StringArray otherpeers;
                    if (others.isArray()) {
                        for (auto item : *others.getArray()) {
                            otherpeers.add(item);
                        }
                    }

                    clientListeners.call(&SonobusAudioProcessor::ClientListener::peerSuggestedNewGroup, this, username, newgroup, grouppass, ispublic, otherpeers);
                }
            }
        }
        else if (type == SONOBUS_MSGTYPE_BLOCKEDINFO) {
            // received from the other side when they have blocked/unblocked us
            // args: s:username  b:blocked

            auto it = message.ArgumentsBegin();
            auto username = String(CharPointer_UTF8((it++)->AsString()));
            auto blocked = (it++)->AsBool();

            {
                const ScopedReadLock sl (mCoreLock);

                // find remote peer
                RemotePeer * peer = findRemotePeer(endpoint, -1);
                if (!peer) {
                    DBG("Could not find peer recv blockinfo for endpoint: " << endpoint->ipaddr);
                }
                else {
                    peer->blockedUs = blocked;
                    DBG("Remote peer " << username << " set blocked = " << (int) blocked);
                    
                    int ind = 0;
                    int retind = -1;
                    for (auto s : mRemotePeers) {
                        if (s->endpoint == endpoint) {
                            retind = ind;
                            break;
                        }
                        ++ind;
                    }
                    
                    if (retind >= 0) {
                        setRemotePeerSendActive(retind, false);
                    }
                }
            }
            
            clientListeners.call(&SonobusAudioProcessor::ClientListener::peerBlockedInfoChanged, this, username, blocked);
        }
        else if (type == SONOBUS_MSGTYPE_FWPROBEREQ) {
            // The hub asks us to probe its ports from outside. Only our hub may ask.
            if (!isHostedMixModeEnabled() || !endpoint || endpoint->ipaddr.isEmpty()) return true;
            auto it = message.ArgumentsBegin();
            const int64 token = (it++)->AsInt64();
            const int32_t udpPort = (it++)->AsInt32();
            const int32_t serverPort = (it++)->AsInt32();
            sbServePortProbe(endpoint->ipaddr, token, udpPort, serverPort);
            return true;
        }
        else if (type == SONOBUS_MSGTYPE_HXSENDMUTESTATE) {
            // Immediate send-mute change for one player (the 10-s /sb/hxlat re-asserts it).
            auto it = message.ArgumentsBegin();
            String who = CharPointer_UTF8((it++)->AsString());
            const int32_t muted = (it++)->AsInt32();
            if (who == mCurrentUsername) return true;
            const ScopedReadLock sl(mCoreLock);
            for (auto* p : mRemotePeers) {
                if (p && p->userName == who) { p->remoteSendMutedViaHub = muted != 0; break; }
            }
            return true;
        }
        else if (type == SONOBUS_MSGTYPE_HXRECSTATE) {
            // Immediate recording start/stop for one player (the 10-s /sb/hxlat re-asserts it).
            auto it = message.ArgumentsBegin();
            String who = CharPointer_UTF8((it++)->AsString());
            const int32_t rec = (it++)->AsInt32();
            if (who == mCurrentUsername) return true;
            const ScopedReadLock sl(mCoreLock);
            for (auto* p : mRemotePeers) {
                if (p && p->userName == who) { p->remoteIsRecording = rec != 0; break; }
            }
            return true;
        }
        else if (type == SONOBUS_MSGTYPE_HXLAT) {
            // Per-player to/from-hub latency from the hub (1 Hz).
            // args: s:userName f:toHubMs f:fromHubMs. Relaxed stores, read by the GUI timer.
            auto it = message.ArgumentsBegin();
            String who = CharPointer_UTF8((it++)->AsString());
            mHxlatRx.fetch_add(1, std::memory_order_relaxed); mHxlatLastRxStampMs.store(Time::getMillisecondCounter(), std::memory_order_relaxed);
            float toHub = (it++)->AsFloat();
            float fromHub = (it++)->AsFloat();
            int32_t uplinkLost = -1;
            if (it != message.ArgumentsEnd()) uplinkLost = (it++)->AsInt32();   // Hub's lost blocks on THEIR uplink
            float rtt = -1.0f;
            if (it != message.ArgumentsEnd()) rtt = (it++)->AsFloat();
            int32_t rec = -1;   // That player is recording (older hubs omit it)
            if (it != message.ArgumentsEnd()) rec = (it++)->AsInt32();
            float upKbps = -1.0f;   // Their uplink rate (older hubs omit it)
            if (it != message.ArgumentsEnd()) upKbps = (it++)->AsFloat();
            int32_t sendMuted = -1;   // That player muted their send (older hubs omit it)
            if (it != message.ArgumentsEnd()) sendMuted = (it++)->AsInt32();
            if (who == mCurrentUsername) {   // Our own legs, same model as everyone's rows → header
                mSelfHubLatToMs = toHub; mSelfHubLatFromMs = fromHub; mSelfHubRttMs = rtt; mSelfHubUplinkLost = uplinkLost;
                mSelfHubLatStampMs = Time::getMillisecondCounter();
                mHxlatSelf.fetch_add(1, std::memory_order_relaxed);
                return true;
            }
            bool matched = false;
            const ScopedReadLock sl(mCoreLock);
            for (auto* p : mRemotePeers) {
                if (p && p->userName == who) {
                    matched = true;
                    p->hubLatToMs = toHub; p->hubLatFromMs = fromHub;
                    if (uplinkLost >= 0) p->hubUplinkLost = uplinkLost;
                    if (rec >= 0) p->remoteIsRecording = rec != 0;   // lights the stock REC icon; status line names who
                    if (sendMuted >= 0) p->remoteSendMutedViaHub = sendMuted != 0;   
                    p->hubRttMs = rtt; p->hubUpKbps = upKbps;   
                    p->hubLatStampMs = Time::getMillisecondCounter();
                    break;
                }
            }
            if (matched) mHxlatPeer.fetch_add(1, std::memory_order_relaxed);
            else { mHxlatUnmatched.fetch_add(1, std::memory_order_relaxed); who.copyToUTF8(mHxlatLastUnmatched, sizeof(mHxlatLastUnmatched)); }
            return true;
        }
        else if (type == SONOBUS_MSGTYPE_HXHUBHELLO) {
            // HXHUBHELLO with full retry chain. The hub broadcasts hub-hello on every peer-join. If
            // AOO PEER_JOIN for the hub did not fire, the hub peer is missing from mRemotePeers, so
            // there is no source for hub-peer-id, the hub's sink invites land in nothing, and
            // upstream stays silent with no recovery short of a restart.
            //
            // This mirrors what the AOONET_CLIENT_PEER_JOIN_EVENT handler does for the hub peer
            // (connectRemotePeerRaw + 500/1500/3000/6000 ms retry chain that re-asserts sendAllow
            // and calls oursource->start()), triggered by the wire-level hub-hello broadcast
            // instead of the AOO peer event. Deferred onto the message thread because
            // connectRemotePeerRaw is unsafe on the UDP recv thread.
            auto it = message.ArgumentsBegin();
            String hubUser = CharPointer_UTF8((it++)->AsString());
            int32_t hubPort = (it++)->AsInt32();
            // Args 3+4 = the public host + AOO
            // server port the hub wants shared. Parsed BEFORE the already-known
            // early return below so a rejoin refreshes it. Older hubs send 2 args.
            if (message.ArgumentCount() >= 4) {
                String linkHost = CharPointer_UTF8((it++)->AsString());
                int32_t linkPort = (it++)->AsInt32();
                if (linkHost.isNotEmpty() && linkPort > 0 && linkPort < 65536) {
                    const ScopedLock sl(mHubLinkLock);
                    mHubLinkHost = linkHost;
                    mHubLinkPort = (int)linkPort;
                }
            }
            // Args 5+6 = hub block size + sample rate → grey out smaller device buffers.
            if (message.ArgumentCount() >= 6) {
                const int32_t hb = (it++)->AsInt32();
                const int32_t hsr = (it++)->AsInt32();
                if (hb >= 16 && hb <= 1024 && hb != sHubBlockSize.load(std::memory_order_relaxed)) {
                    sHubBlockSize.store((int) hb, std::memory_order_relaxed);
                    std::cout << "[HUB-HELLO] hub block size " << hb << " @ " << hsr << " Hz" << std::endl;
                    // rebuild the Setup Audio buffer list if it is showing (device manager change → selector refresh)
                    juce::MessageManager::callAsync([]() { if (sHubBlockChanged) sHubBlockChanged(); });
                }
                if (hsr > 0) sHubSampleRate.store((int) hsr, std::memory_order_relaxed);
            }
            (void)hubPort;  // we use the packet source endpoint, not the
                            // advertised audio port — the packet's actual
                            // source endpoint is what the AOO library binds
                            // to internally for the peer's data path.

            {
                const ScopedReadLock sl(mCoreLock);
                for (auto* p : mRemotePeers) {
                    if (p && p->userName == hubUser) {
                        return true;  // already in mRemotePeers, no-op
                    }
                }
            }

            if (isHostedMixModeEnabled() && hubUser == mHubPeerUsername) {
                String hubIp     = endpoint->ipaddr;
                int    hubEpPort = endpoint->port;
                String hubUserCopy = hubUser;
                MessageManager::callAsync(
                    [this, hubUserCopy, hubIp, hubEpPort]() {
                        {
                            const ScopedReadLock sl(mCoreLock);
                            for (auto* p : mRemotePeers) {
                                if (p && p->userName == hubUserCopy) return;
                            }
                        }
                        DBG("[HXHUBHELLO-v4] hub-peer missing — force-adding '"
                            << hubUserCopy << "' at "
                            << hubIp << ":" << hubEpPort);
                        struct sockaddr_in sa{};
                        sa.sin_family = AF_INET;
                        sa.sin_port   = htons((uint16_t)hubEpPort);
                        inet_pton(AF_INET, hubIp.toRawUTF8(), &sa.sin_addr);
                        String gn = getCurrentJoinedGroup();
                        connectRemotePeerRaw((void*)&sa, hubUserCopy, gn,
                                             !mMainRecvMute.get());

                        // Mirror the PEER_JOIN handler's retry chain so the hub peer's oursource
                        // actually starts. Without it the hub peer stays in a half-state, marked
                        // MUTED in the UI.
                        juce::String hubNameCap = hubUserCopy;
                        for (int delayMs : {500, 1500, 3000, 6000}) {
                            juce::Timer::callAfterDelay(delayMs,
                                [this, hubNameCap]() {
                                    const juce::ScopedReadLock sl(mCoreLock);
                                    for (int i = 0; i < mRemotePeers.size(); ++i) {
                                        auto* p = mRemotePeers.getUnchecked(i);
                                        if (p && !p->infoOnly
                                            && p->userName == hubNameCap) {
                                            if (!mMainSendMute.get()) {
                                                p->sendAllow      = true;
                                                p->sendAllowCache = true;
                                                if (p->oursource) p->oursource->start();
                                                setRemotePeerSendActive(i, true);
                                            }
                                        }
                                    }
                                });
                        }
                    });
            }
        }
        return true;
    } catch (const osc::Exception& e){
        DBG("exception in handleOtherMessage: " << e.what());
    }
    return false;
}


bool SonobusAudioProcessor::sendChatEvent(const SBChatEvent & event)
{
    // /sb/chat s:groupname s:from s:targets s:tags s:message

    // if peerindex < 0 - send to all peers
    char buf[AOO_MAXPACKETSIZE];
    osc::OutboundPacketStream msg(buf, sizeof(buf));

    try {

        msg << osc::BeginMessage(SONOBUS_FULLMSG_CHAT)
        << event.group.toRawUTF8()
        << event.from.toRawUTF8()
        << event.targets.toRawUTF8()
        << event.tags.toRawUTF8()
        << event.message.toRawUTF8()
        << osc::EndMessage;

    }
    catch (const osc::Exception& e){
        DBG("exception in chat message constructions: " << e.what());
        return false;
    }

    StringArray targetnames = StringArray::fromTokens(event.targets, "|", "");


    const ScopedReadLock sl (mCoreLock);

    // In HostedMix every peer row shares the hub endpoint, so send exactly one copy to the hub row;
    // the hub relays it to the other peers and honors the 'targets' field itself.
    if (isHostedMixModeEnabled()) {
        RemotePeer * hubPeer = nullptr;
        for (auto * p : mRemotePeers) {
            if (p && !p->infoOnly && p->userName == mHubPeerUsername) {
                hubPeer = p;
                break;
            }
        }
        if (!hubPeer) {
            DBG("sendChatEvent: no hub peer connected, chat not sent");
            return false;
        }
        DBG("Sending chat message via hub relay");
        this->sendPeerMessage(hubPeer, msg.Data(), (int32_t) msg.Size());
        return true;
    }

    for (int i=0;  i < mRemotePeers.size(); ++i) {
        auto * peer = mRemotePeers.getUnchecked(i);

        // Skip info-only rows; they aren't real network peers.
        if (peer->infoOnly)
            continue;

        if (!targetnames.isEmpty() && !targetnames.contains(peer->userName))
            continue;

        DBG("Sending chat message to " << i);
        this->sendPeerMessage(peer, msg.Data(), (int32_t) msg.Size());

    }

    return true;
}

void SonobusAudioProcessor::handleLatInfo(const juce::var & infolist)
{
    const ScopedLock sl (mLatInfoLock);

    // received a latinfo list from elsewhere, add it to our list
    // todo remove any duplicates

    if (!infolist.isArray()) return;

    for (int i=0; i < infolist.size(); ++i) {
        auto infodata = infolist[i];

        LatInfo latinfo;
        latinfo.sourceName = infodata.getProperty("srcname", "");
        latinfo.destName = infodata.getProperty("destname", "");
        latinfo.latencyMs = infodata.getProperty("latms", 0.0f);

        if (latinfo.sourceName.isNotEmpty() && latinfo.destName.isNotEmpty()) {
            mLatInfoList.add(latinfo);
        }

        DBG("latinfo: srcname: " << latinfo.sourceName << "  dest: " << latinfo.destName << "  latms: " << latinfo.latencyMs);
    }
}

juce::var SonobusAudioProcessor::getAllLatInfo()
{
    juce::var infolist;

    const ScopedReadLock sl (mCoreLock);

    for (int i=0;  i < mRemotePeers.size(); ++i) {
        auto * peer = mRemotePeers.getUnchecked(i);
        if (!peer) continue;
        DynamicObject::Ptr item = new DynamicObject(); // this will delete itself
        LatencyInfo latinfo;
        getRemotePeerLatencyInfo(i, latinfo);

        item->setProperty("srcname", peer->userName);
        item->setProperty("destname", mCurrentUsername);
        item->setProperty("latms", latinfo.incomingMs);

        infolist.append(item.get());
    }

    return infolist;
}

void SonobusAudioProcessor::sendBlockedInfoMessage(EndpointState *endpoint, bool blocked)
{
    if (isHostedMixModeEnabled()) return;   // The hub drops BLOCKEDINFO; stock-only chatter
    char buf[AOO_MAXPACKETSIZE];
    osc::OutboundPacketStream outmsg(buf, sizeof(buf));

    try {

        outmsg << osc::BeginMessage(SONOBUS_FULLMSG_BLOCKEDINFO)
        << mCurrentUsername.toRawUTF8()
        << blocked
        << osc::EndMessage;

    }
    catch (const osc::Exception& e){
        DBG("exception in blockedinfo message constructions: " << e.what());
        return;
    }
    
    endpoint_send(endpoint, outmsg.Data(), (int) outmsg.Size());
}


void SonobusAudioProcessor::sendReqLatInfoToAll()
{
    char buf[AOO_MAXPACKETSIZE];
    osc::OutboundPacketStream msg(buf, sizeof(buf));

    try {

        msg << osc::BeginMessage(SONOBUS_FULLMSG_REQLATINFO)
        << osc::EndMessage;

    }
    catch (const osc::Exception& e){
        DBG("exception in reqlat message constructions: " << e.what());
        return;
    }

    const ScopedReadLock sl (mCoreLock);
    for (int i=0;  i < mRemotePeers.size(); ++i) {
        auto * peer = mRemotePeers.getUnchecked(i);

        DBG("Sending reqlat message to " << i);
        this->sendPeerMessage(peer, msg.Data(), (int32_t) msg.Size());
    }
}

void SonobusAudioProcessor::sendLatencyMatchToAll(float latency)
{
    // suggest to all that they should adjust all receiving latencies to be this value

    char buf[AOO_MAXPACKETSIZE];
    osc::OutboundPacketStream msg(buf, sizeof(buf));

    try {

        msg << osc::BeginMessage(SONOBUS_FULLMSG_SUGGESTLAT)
        << mCurrentUsername.toRawUTF8()
        << latency
        << osc::EndMessage;

    }
    catch (const osc::Exception& e){
        DBG("exception in suggestlat message constructions: " << e.what());
        return;
    }

    const ScopedReadLock sl (mCoreLock);
    for (int i=0;  i < mRemotePeers.size(); ++i) {
        auto * peer = mRemotePeers.getUnchecked(i);

        DBG("Sending suggestlat: " << latency << " message to " << i);
        this->sendPeerMessage(peer, msg.Data(), (int32_t) msg.Size());
    }

}


void SonobusAudioProcessor::beginLatencyMatchProcedure()
{
    {
        const ScopedLock sl (mLatInfoLock);
        mLatInfoList.clearQuick();

        // add our own info
        handleLatInfo(getAllLatInfo());
    }

    sendReqLatInfoToAll();
}

bool SonobusAudioProcessor::isLatencyMatchProcedureReady()
{
    // we expect an entry for every directional path in the mesh
    const ScopedLock sl (mLatInfoLock);
    int totpeers = mRemotePeers.size() + 1;
    int predictedSize =  (totpeers*(totpeers - 1));

    return mLatInfoList.size() >= predictedSize;
}

void SonobusAudioProcessor::getLatencyInfoList(Array<LatInfo> & retlist)
{
    const ScopedLock sl (mLatInfoLock);
    retlist.addArray(mLatInfoList);
}

void SonobusAudioProcessor::commitLatencyMatch(float latency)
{
    // Adjust the jitter buffer for each peer with extra values to pad up to the requested latency

    const ScopedReadLock sl (mCoreLock);
    for (int i=0;  i < mRemotePeers.size(); ++i) {
        auto * peer = mRemotePeers.getUnchecked(i);

        float pingms= peer->smoothPingTime.xbar;
        const auto absizeMs = 1e3*currSamplesPerBlock/getSampleRate();
        float basebuftimeMs = jmax((double) (peer->netBufAutoBaseline > 0.0 ? peer->netBufAutoBaseline : peer->buffertimeMs), absizeMs);
        auto halfping = pingms*0.5f;
        auto recvcodecLat = peer->recvFormat.codec == CodecOpus ? 2.5f : 0.0f; // Opus adds codec latency

        auto baseline = /*absizeMs + */ recvcodecLat +  peer->remoteInLatMs + halfping + basebuftimeMs;

        if (baseline < latency) {
            // we can add some padding
            auto padms =  (latency - baseline);
            auto newbuftime = basebuftimeMs + padms;
            DBG("Adding " << padms << " ms of padding for peer: " << i);
            setRemotePeerBufferTime(i, newbuftime);
            // now set the auto baseline
        }
        peer->latencyMatched = true;

    }
}


void SonobusAudioProcessor::suggestNewGroupToPeers(const String & group, const String & groupPass, const StringArray & peernames, bool ispublic)
{
    // suggest to other peers to join a new group

    // send our info to this remote peer
    DynamicObject::Ptr info = new DynamicObject(); // this will delete itself

    info->setProperty("user", getCurrentUsername());
    info->setProperty("group", group);
    info->setProperty("group_pass", groupPass);
    info->setProperty("public", ispublic);

    info->setProperty("others", peernames);

    char buf[AOO_MAXPACKETSIZE];
    osc::OutboundPacketStream msg(buf, sizeof(buf));


    String jsonstr = JSON::toString(info.get(), true, 6);

    if (jsonstr.getNumBytesAsUTF8() > AOO_MAXPACKETSIZE - 100) {
        DBG("Info too big for packet!");
        return;
    }

    try {
        msg << osc::BeginMessage(SONOBUS_FULLMSG_SUGGEST_GROUP)
        << osc::Blob(jsonstr.toRawUTF8(), (int) jsonstr.getNumBytesAsUTF8())
        << osc::EndMessage;
    }
    catch (const osc::Exception& e){
        DBG("exception in suggest group message constructions: " << e.what());
        return;
    }

    const ScopedReadLock sl (mCoreLock);
    for (int i=0;  i < mRemotePeers.size(); ++i) {
        auto * peer = mRemotePeers.getUnchecked(i);
        if (peernames.contains(peer->userName)) {
            DBG("Sending invite to new group: " << group << " message to " << i);
            this->sendPeerMessage(peer, msg.Data(), (int32_t) msg.Size());
        }
    }

}


void SonobusAudioProcessor::handleRemotePeerInfoUpdate(RemotePeer * peer, const juce::var & infodata)
{
    // core read lock already held

    // infodata should contain useful info

    DBG("peerinfo: Handle remote peerinfo update ");

    if (infodata.hasProperty("jitbuf")) {
        float jitbufms = infodata.getProperty("jitbuf", 0.0f);
        DBG("peerinfo: Got remote jitter buffer: " << jitbufms);
        peer->remoteJitterBufMs = jitbufms;
    }
    if (infodata.hasProperty("inlat")) {
        float latms = infodata.getProperty("inlat", 0.0f);
        DBG("peerinfo: Got remote input latency: " << latms);
        peer->remoteInLatMs = latms;
    }
    if (infodata.hasProperty("outlat")) {
        float latms = infodata.getProperty("outlat", 0.0f);
        DBG("peerinfo: Got remote input latency: " << latms);
        peer->remoteOutLatMs = latms;
    }
    if (infodata.hasProperty("nettype")) {
        int nettype = infodata.getProperty("nettype", (int) RemoteNetTypeUnknown);
        DBG("peerinfo: Got remote net type: " << nettype);
        peer->remoteNetType = nettype;
    }
    if (infodata.hasProperty("rec")) {
        bool isrec = infodata.getProperty("rec", false);
        DBG("peerinfo: Got remote recording: " << (int)isrec);
        peer->remoteIsRecording = isrec;
    }

    peer->hasRemoteInfo = true;

}

void SonobusAudioProcessor::sendRemotePeerInfoUpdate(int index, RemotePeer * topeer)
{
    if (isHostedMixModeEnabled()) return;   // The hub drops PEERINFO; stock-only chatter
    // send our info to this remote peer
    DynamicObject::Ptr info = new DynamicObject(); // this will delete itself

    // not great, better than nothing - TODO make this accurate
    info->setProperty("inlat", 1e3 * currSamplesPerBlock / getSampleRate());
    info->setProperty("outlat", 1e3 * currSamplesPerBlock / getSampleRate());
    info->setProperty("rec", isRecordingToFile());

    // nettype TODO

    char buf[AOO_MAXPACKETSIZE];

    const ScopedReadLock sl (mCoreLock);
    for (int i=0;  i < mRemotePeers.size(); ++i) {
        auto * peer = mRemotePeers.getUnchecked(i);
        if (topeer && topeer != peer) continue;
        if (index >= 0 && index != i) continue;

        osc::OutboundPacketStream msg(buf, sizeof(buf));

        auto buftimeMs = jmax((double)peer->buffertimeMs, 1e3 * currSamplesPerBlock / getSampleRate());
        info->setProperty("jitbuf", buftimeMs);

        String jsonstr = JSON::toString(info.get(), true, 6);

        if (jsonstr.getNumBytesAsUTF8() > AOO_MAXPACKETSIZE - 100) {
            DBG("Info too big for packet!");
            return;
        }

        try {
            msg << osc::BeginMessage(SONOBUS_FULLMSG_PEERINFO)
            << osc::Blob(jsonstr.toRawUTF8(), (int) jsonstr.getNumBytesAsUTF8())
            << osc::EndMessage;
        }
        catch (const osc::Exception& e){
            DBG("exception in PEERINFO message constructions: " << e.what());
            continue;
        }

        DBG("Sending peerinfo message to " << i);
        this->sendPeerMessage(peer, msg.Data(), (int32_t) msg.Size());

        if (index == i || topeer == peer) break;
    }

}


int32_t SonobusAudioProcessor::sendPeerMessage(RemotePeer * peer, const char *msg, int32_t n)
{
    return endpoint_send(peer->endpoint, msg, n);
}


void SonobusAudioProcessor::doSendData()
{
    // just try to send for everybody
    const ScopedReadLock sl (mCoreLock);        

    // send stuff until there is nothing left to send
    
    int32_t didsomething = 1;

    // once per wake (already hoisted out of the while loop)
    auto nowtimems = Time::getMillisecondCounterHiRes();

    mNetStatSendWakes.fetch_add(1, std::memory_order_relaxed);

    while (didsomething) {
        //mAooSource->send();
        didsomething = 0;
        
        didsomething |= mAooDummySource->send();
        
        if (mAooClient) {
            mAooClient->send();
        }
        
        mNetStatSendPasses.fetch_add(1, std::memory_order_relaxed);

        for (auto & remote : mRemotePeers) {
            if (remote->infoOnly) continue;
            if (remote->oursource && !remote->relayedViaHub) {   // Player rows never send
                // Count this peer's send, not the pass-wide accumulator (which would credit later
                // peers for earlier sends).
                const int32_t sent = remote->oursource->send();
                didsomething |= sent;

                if (sent) {
                    remote->dataPacketsSent += 1;
                }
            }
            if (remote->oursink) {
                didsomething |= remote->oursink->send();
            }

            if (remote->latencysource) {
                didsomething |= remote->latencysource->send();
                didsomething |= remote->latencysink->send();
                didsomething |= remote->echosource->send();
                didsomething |= remote->echosink->send();
            }

            if ( nowtimems > (remote->lastSendPingTimeMs + PEER_PING_INTERVAL_MS) ) {
                sendPingEvent(remote);
                remote->lastSendPingTimeMs = nowtimems;
                if (!remote->haveSentFirstPeerInfo) {
                    sendRemotePeerInfoUpdate(-1, remote);
                    remote->haveSentFirstPeerInfo = true;
                }
            }
        }
    }

    if (mPendingUnmute.get() && mPendingUnmuteAtStamp < Time::getMillisecondCounter() ) {
        DBG("UNMUTING ALL");
        mState.getParameter(paramMainRecvMute)->setValueNotifyingHost(0.0f);

        mPendingUnmute = false;
    }

    if (mNeedsSampleSetup.get()) {
        DBG("Doing sample setup for all");
        setupSourceFormatsForAll();
        mNeedsSampleSetup = false;

        // reset all incoming by toggling muting
        if (!mMainRecvMute.get()) {
            DBG("Toggling main recv mute");
            mState.getParameter(paramMainRecvMute)->setValueNotifyingHost(1.0f);
            mPendingUnmuteAtStamp = Time::getMillisecondCounter() + 250;
            mPendingUnmute = true;
        }

        sendRemotePeerInfoUpdate(-1); // send to all

    }


}

struct ProcessorIdPair
{
    ProcessorIdPair(SonobusAudioProcessor *proc, int32_t id_) : processor(proc), id(id_) {}
    SonobusAudioProcessor * processor;
    int32_t id;
};

static int32_t gHandleSourceEvents(void * user, const aoo_event ** events, int32_t n)
{
    ProcessorIdPair * pp = static_cast<ProcessorIdPair*> (user);
    return pp->processor->handleSourceEvents(events, n, pp->id);    
}

static int32_t gHandleSinkEvents(void * user, const aoo_event ** events, int32_t n)
{
    ProcessorIdPair * pp = static_cast<ProcessorIdPair*> (user);
    return pp->processor->handleSinkEvents(events, n, pp->id);
}

static int32_t gHandleServerEvents(void * user, const aoo_event ** events, int32_t n)
{
    ProcessorIdPair * pp = static_cast<ProcessorIdPair*> (user);
    return pp->processor->handleServerEvents(events, n);
}

static int32_t gHandleClientEvents(void * user, const aoo_event ** events, int32_t n)
{
    ProcessorIdPair * pp = static_cast<ProcessorIdPair*> (user);
    return pp->processor->handleClientEvents(events, n);
}


void SonobusAudioProcessor::handleEvents()
{
    const ScopedReadLock sl (mCoreLock);        
    int32_t dummy = 0;
    
    if (mAooServer /*&& mAooServer->events_available()*/) {
        ProcessorIdPair pp(this, dummy);
        mAooServer->handle_events(gHandleServerEvents, &pp);
    }

    if (mAooClient && mAooClient->events_available()) {
        ProcessorIdPair pp(this, dummy);
        mAooClient->handle_events(gHandleClientEvents, &pp);
    }

    
    if (mAooDummySource->events_available() > 0) {
        mAooDummySource->get_id(dummy);
        ProcessorIdPair pp(this, dummy);
        mAooDummySource->handle_events(gHandleSourceEvents, &pp);
    }

    for (auto & remote : mRemotePeers) {
        if (remote->infoOnly) continue;
        if (remote->oursource) {
            remote->oursource->get_id(dummy);
            ProcessorIdPair pp(this, dummy);
            remote->oursource->handle_events(gHandleSourceEvents, &pp);
        }
        if (remote->oursink) {
            remote->oursink->get_id(dummy);
            ProcessorIdPair pp(this, dummy);
            remote->oursink->handle_events(gHandleSinkEvents, &pp);
        }


        if (remote->latencysink) {
            remote->latencysink->get_id(dummy);
            ProcessorIdPair pp(this, dummy);
            remote->latencysink->handle_events(gHandleSinkEvents, &pp);
        }
        if (remote->echosink) {
            remote->echosink->get_id(dummy);
            ProcessorIdPair pp(this, dummy);
            remote->echosink->handle_events(gHandleSinkEvents, &pp);
        }
         
        if (remote->latencysource) {
            remote->latencysource->get_id(dummy);
            ProcessorIdPair pp(this, dummy);
            remote->latencysource->handle_events(gHandleSourceEvents, &pp);
        }
        if (remote->echosource) {
            remote->echosource->get_id(dummy);
            ProcessorIdPair pp(this, dummy);
            remote->echosource->handle_events(gHandleSourceEvents, &pp);
        }

    }

    reportNetDietStatsIfDue();
}

namespace sbtap { static const char* tapConf(const char* key); } // defined below (env / /tmp/sb_taps.conf)

// Audio health, called from the editor's 1 s timer with the device's cumulative
// CoreAudio overload count (JUCE xruns). Every 10 s: callbacks seen vs expected (sr / bufSize * dt),
// overload delta. A callback deficit = the device skipped IO cycles = one block of unconsumed audio
// per skip (the depth the governor later splices out) AND a gap on the output.
static SonobusAudioProcessor::RemotePeer * sb_findHubPeer(
    const OwnedArray<SonobusAudioProcessor::RemotePeer> & peers, const String & hubName);   // defined below (hosted-mode helper)

// Recording indicator across the hub. Sent on record start/stop; the 10-s /sb/hxbuf
// re-asserts it. The hub relays every player's state to everyone on its 1-Hz /sb/hxlat line.
void SonobusAudioProcessor::sbSendRecStateToHub()
{
    if (!isHostedMixModeEnabled()) return;
    const int32_t rec = isRecordingToFile() ? 1 : 0;
    const ScopedReadLock sl (mCoreLock);
    if (auto * hubPeer = sb_findHubPeer(mRemotePeers, mHubPeerUsername)) {
        char b[64];
        osc::OutboundPacketStream m(b, sizeof(b));
        try {
            m << osc::BeginMessage("/sb/hxrec") << rec << osc::EndMessage;
            sendPeerMessage(hubPeer, m.Data(), (int32_t) m.Size());
        } catch (const osc::Exception&) {}
    }
}

// Send-mute indicator across the hub. Sent when the main send mute toggles; the 10-s /sb/hxbuf
// re-asserts it (arg 10). The hub relays it to everyone at once (/sb/hxsendmutestate) and on its /sb/hxlat line.
void SonobusAudioProcessor::sbSendMuteStateToHub()
{
    if (!isHostedMixModeEnabled()) return;
    // Stock semantics: only the lower-left SEND mute is relayed (others see "Muted at their end");
    // the top MUTE is a silent cough mute and nothing is reported.
    const int32_t muted = mMainSendMute.get() ? 1 : 0;
    const ScopedReadLock sl (mCoreLock);
    if (auto * hubPeer = sb_findHubPeer(mRemotePeers, mHubPeerUsername)) {
        char b[64];
        osc::OutboundPacketStream m(b, sizeof(b));
        try {
            m << osc::BeginMessage("/sb/hxsendmute") << muted << osc::EndMessage;
            sendPeerMessage(hubPeer, m.Data(), (int32_t) m.Size());
        } catch (const osc::Exception&) {}
    }
}

// Player-assisted hub port check. We are outside the hub's network, so our fresh UDP
// sockets and TCP connect test the hub's router/firewall the way a new player would. Reply goes to the hub
// over the normal peer path (hub socket), from which the request came. Rate-limited: one probe per 2 s.
void SonobusAudioProcessor::sbServePortProbe(const String& hubIp, int64 token, int udpPort, int serverPort)
{
    if (udpPort <= 0 || udpPort > 65535 || serverPort <= 0 || serverPort > 65535) return;
    static std::atomic<int64_t> lastMs{0};
    const int64_t now = (int64_t) Time::getMillisecondCounter();
    int64_t last = lastMs.load(std::memory_order_relaxed);
    if (now - last < 2000 || !lastMs.compare_exchange_strong(last, now)) return;
    const String ip = hubIp;
    std::thread([this, ip, token, udpPort, serverPort]() {   // JUCE sockets: portable (macOS / Linux / Windows players)
        auto ping = [&](int port, const char* what) {
            DatagramSocket sk(false);
            if (!sk.bindToPort(0)) return;
            char b[128]; osc::OutboundPacketStream m(b, sizeof(b));
            try { m << osc::BeginMessage("/sb/fwprobe/ping") << (osc::int64) token << what << osc::EndMessage; } catch (...) { return; }
            for (int i = 0; i < 3; ++i) { sk.write(ip, port, m.Data(), (int) m.Size()); std::this_thread::sleep_for(std::chrono::milliseconds(20)); }
        };
        ping(udpPort, "udp-audio");
        ping(serverPort, "udp-server");
        int tcpOk = 0;
        { StreamingSocket t; tcpOk = t.connect(ip, serverPort, 2000) ? 1 : 0; t.close(); }
        const ScopedReadLock sl (mCoreLock);
        if (auto * hubPeer = sb_findHubPeer(mRemotePeers, mHubPeerUsername)) {
            char b[96]; osc::OutboundPacketStream m(b, sizeof(b));
            try {
                m << osc::BeginMessage("/sb/fwprobe/result") << (osc::int64) token << (int32_t) tcpOk << osc::EndMessage;
                for (int i = 0; i < 2; ++i) sendPeerMessage(hubPeer, m.Data(), (int32_t) m.Size());
            } catch (const osc::Exception&) {}
        }
        fprintf(stderr, "[SB-PORTPROBE] probed hub %s: TCP %d %s (UDP %d/%d pinged)\n", ip.toRawUTF8(), serverPort, tcpOk ? "OK" : "BLOCKED", udpPort, serverPort);
    }).detach();
}

void SonobusAudioProcessor::sbAudioHealthTick(int xrunsTotal, double sr, int bufSize)
{
    const double now = Time::getMillisecondCounterHiRes();
    if (mSbAudioHealthLastMs <= 0) { mSbAudioHealthLastMs = now; mSbAudioCbLast = mSbAudioCallbacks.load(std::memory_order_relaxed); mSbXrunLast = xrunsTotal; return; }
    const double dt = (now - mSbAudioHealthLastMs) * 1e-3;
    if (dt < 10.0) return;
    const uint64_t cb = mSbAudioCallbacks.load(std::memory_order_relaxed);
    const long long seen = (long long)(cb - mSbAudioCbLast);
    const uint64_t fr = mSbAudioFrames.load(std::memory_order_relaxed);
    const long long frames = (long long)(fr - mSbAudioFramesLast); mSbAudioFramesLast = fr;
    const long long expected = (sr > 0 && bufSize > 0) ? (long long) llround(dt * sr / bufSize) : 0;
    const int xr = xrunsTotal - mSbXrunLast;
    mSbAudioHealthLastMs = now; mSbAudioCbLast = cb; mSbXrunLast = xrunsTotal;
    // Tell the hub our receive buffer (ms) so it can add it to OUR "from hub" leg on
    // everyone else's display (/sb/hxbuf f:ms). Once per health tick (10 s), control path only.
    const int32_t hxAgeS = getSelfHubLatencyAgeS();   // Age of the hub's last latency report for us (-1 = never)
    if (isHostedMixModeEnabled()) {
        const ScopedReadLock sl (mCoreLock);
        if (auto * hubPeer = sb_findHubPeer(mRemotePeers, mHubPeerUsername)) {
            // Receive health rides the SAME report — our concealments in the last
            // 10 s (sink underruns + governor pops summed over the relayed rows) and device xruns.
            // Counters are cumulative atomics in the sink; this is the only reader. No new packets.
            int64_t rxU = 0, rxP = 0;
            for (auto * r : mRemotePeers) {
                if (!r || r->infoOnly || !r->oursink || r->remoteSourceId < 0) continue;
                int32_t u = 0, pp = 0;
                if (r->oursink->get_sourceoption(r->endpoint, r->remoteSourceId, aoo_opt_rx_underruns, AOO_ARG(u)) > 0) rxU += u;
                if (r->oursink->get_sourceoption(r->endpoint, r->remoteSourceId, aoo_opt_rx_pops, AOO_ARG(pp)) > 0) rxP += pp;
            }
            {   // The receive buffer's DECISIONS (quick/commit/grow/emergency/decay) per
                // relayed row, appended to auto.log (universal, one small file, 1 MB cap) so the hub
                // page's recvBuf history can be matched to what the sink decided and why. Control path, once per 10 s.
                static const char* const kinds[] = { "?", "QUICK", "COMMIT", "GROW", "GROW-EMERGENCY", "DECAY" };
                FILE* af = nullptr;
                for (auto * r : mRemotePeers) {
                    if (!r || r->infoOnly || !r->oursink || r->remoteSourceId < 0) continue;
                    // The 'last logged seq' must follow the sink, not the row object: a row
                    // re-created by the hub-hello retry chain restarts at 0 and would re-dump the
                    // ring. Keyed by the sink + source id in mSbAutoLogSeq; a decision is logged
                    // once by seq.
                    const std::string lkey = std::to_string((uintptr_t) r->oursink.get()) + ":" + std::to_string(r->remoteSourceId);
                    uint32_t& lastSeq = mSbAutoLogSeq[lkey];
                    if (r->sbAdaptEvSeq > lastSeq) lastSeq = r->sbAdaptEvSeq;
                    aoo_adapt_events ev; ev.since = lastSeq; ev.count = 0; ev.latest = lastSeq;
                    if (r->oursink->get_sourceoption(r->endpoint, r->remoteSourceId, aoo_opt_adapt_events, AOO_ARG(ev)) <= 0) continue;
                    if (ev.latest < lastSeq) { lastSeq = ev.latest; continue; }   // sink was re-created: resync without replaying
                    for (int i = 0; i < ev.count && i < AOO_ADAPT_EVENTS_MAX; ++i) {
                        const aoo_adapt_event& e = ev.ev[i];
                        if (e.seq <= lastSeq) continue;
                        lastSeq = e.seq; r->sbAdaptEvSeq = e.seq;
                        const int k = (e.kind >= 1 && e.kind <= 5) ? e.kind : 0;
                        char line[256];
                        char late[40] = "";   // The gap the emergency step covered (0 = loss, +1 block)
                        if (k == 4) snprintf(late, sizeof(late), e.late_ms > 0 ? " late=%.1fms" : " late=loss", (double) e.late_ms);
                        else if (k == 5 && e.late_ms > 0) snprintf(late, sizeof(late), " need=%.1fms", (double) e.late_ms);   // Decay toward the measured need
                        snprintf(line, sizeof(line), "%s [SB-AUTO] peer='%s' %s%s -> %d blocks = %.1f ms\n",
                                 Time(int64(e.wall_s * 1000.0)).formatted("%Y-%m-%d %H:%M:%S").toRawUTF8(),
                                 r->userName.toRawUTF8(), kinds[k], late, (int) e.blocks, e.blocks * (double) e.block_ms);
                        if (sbDiagOn()) fputs(line, stderr);
                        if (!af) {
                            if (const char* home = std::getenv("HOME"); home && home[0]) {
                                const std::string lp = sbLogDir() + "/auto.log";
                                struct stat st; if (stat(lp.c_str(), &st) == 0 && st.st_size > 1024 * 1024) { std::rename(lp.c_str(), (lp + ".1").c_str()); }
                                af = fopen(lp.c_str(), "a");
                            }
                        }
                        if (af) fputs(line, af);
                    }
                }
                if (af) fclose(af);
            }
            const int32_t dU = (int32_t) jmax((int64_t) 0, rxU - mSbRxUnderrunsLast), dP = (int32_t) jmax((int64_t) 0, rxP - mSbRxPopsLast);
            mSbRxUnderrunsLast = rxU; mSbRxPopsLast = rxP;
            int32_t hubBufMode = 1;   // 0 = Manual pin, 1 = any Auto mode (the chip's A/M)
            {
                const int hubIdx = mRemotePeers.indexOf(hubPeer);
                bool initDone = false;
                if (hubIdx >= 0 && getRemotePeerAutoresizeBufferMode(hubIdx, initDone) == AutoNetBufferModeOff) hubBufMode = 0;
            }
            char hb[128];
            osc::OutboundPacketStream hm(hb, sizeof(hb));
            try {
                hm << osc::BeginMessage("/sb/hxbuf") << (float) getHostedFeedDepthMs()   // Depth in force, not the request
                   << (int32_t) dU << (int32_t) dP << (int32_t) xr                        // Underruns/pops/xruns in the last 10 s
                   << (int32_t) (isRecordingToFile() ? 1 : 0)                             // Recording (re-asserted every 10 s)
                   << (int32_t) bufSize << (int32_t) lrint(sr)                             // Audio buffer + rate actually in force
                   << hxAgeS                                                               // Seconds since our last applied /sb/hxlat (-1 never)
                   << hubBufMode                                                           // Our receive-buffer mode for the hub feed, 0 Manual / 1 Auto
                   << (int32_t) (mMainSendMute.get() ? 1 : 0)        // Our send mute, re-asserted every 10 s (send mute ONLY, stock semantics)
                   << (int32_t) (sbIdleMaskDecodeOn() ? 1 : 0) << osc::EndMessage;          // Capability bits (bit0 = decodes idle-masked blocks) — sent even when muted, so the hub
                                                                                           // masks its feeds to us although it never sees our own stream
                sendPeerMessage(hubPeer, hm.Data(), (int32_t) hm.Size());
            } catch (const osc::Exception&) {}
            // Our version and system, so the hub can show who runs what. Re-sent with every report; control path only.
            {
                static const String ver = [](){ const auto i = SonobusPlusVersion::get();
                    return i.version.isNotEmpty() ? i.marketing + " (" + i.version + ")" : i.marketing + " (dev)"; }();
               #if JUCE_MAC
                static const char* const os = "Mac";
               #elif JUCE_WINDOWS
                static const char* const os = "Windows";
               #elif JUCE_LINUX
                static const char* const os = "Linux";
               #else
                static const char* const os = "other";
               #endif
                char vb[160];
                osc::OutboundPacketStream vm(vb, sizeof(vb));
                try {
                    vm << osc::BeginMessage("/sb/hxver") << ver.substring(0, 60).toRawUTF8() << os << osc::EndMessage;
                    sendPeerMessage(hubPeer, vm.Data(), (int32_t) vm.Size());
                } catch (const osc::Exception&) {}
            }
        }
    }
    if (isHostedMixModeEnabled() && (++mHxlatTick % 3) == 0) {   // /sb/hxlat feed accounting every 30 s, always on (one line, one small file)
        {   // Per relayed row, sink-level dropped blocks (the header's number) + per-reason
            String line = Time::getCurrentTime().formatted("%Y-%m-%d %H:%M:%S") + " [SB-DROPS]";
            {
                const ScopedReadLock sl (mCoreLock);
                for (auto* p : mRemotePeers) {
                    if (!p) continue;
                    const int64_t tot = p->dataPacketsDropped; int64_t& last = mSbDropsLast[p->userName];
                    line << " peer='" << p->userName << "' ch=" << p->recvChannels << " dropped_total=" << String(tot) << " delta30=" << String(tot - last) << ";";
                    last = tot;
                }
            }
            uint64_t ls[8] = {0}; aoo_sb_lost_sites(ls, 8);
            static const char* kSite[8] = {"recovery_dropped","underrun_recovery","skim","overflow_flush","skipped_range","drop_unresent","outdated_pop","-"};
            line << " | lost_by_reason30:";
            for (int k = 0; k < 7; ++k) { line << " " << kSite[k] << "=" << String((int64) (ls[k] - mSbLostSiteLast[k])); mSbLostSiteLast[k] = ls[k]; }
            line << "\n";
            File f = File(String(sbLogDir())).getChildFile("drops.log");
            f.appendText(line, false, false, nullptr);
        }
        const uint32_t rx = mHxlatRx.load(std::memory_order_relaxed), sf = mHxlatSelf.load(std::memory_order_relaxed), pr = mHxlatPeer.load(std::memory_order_relaxed), un = mHxlatUnmatched.load(std::memory_order_relaxed);
        const uint32 nowms = Time::getMillisecondCounter(); const uint32 lastRx = mHxlatLastRxStampMs.load(std::memory_order_relaxed);
        char line[320];
        snprintf(line, sizeof(line), "[SB-HXLAT] rx=+%u self=+%u peer=+%u unmatched=+%u (last '%s') last_rx_age_ms=%u self_age_s=%d feed=%s user='%s'\n",
                 rx - mHxlatRxLast, sf - mHxlatSelfLast, pr - mHxlatPeerLast, un - mHxlatUnmatchedLast, mHxlatLastUnmatched,
                 lastRx ? (unsigned) (nowms - lastRx) : 0u, hxAgeS, (hxAgeS >= 0 && hxAgeS <= 35) ? "ok" : "DARK", mCurrentUsername.toRawUTF8());
        mHxlatRxLast = rx; mHxlatSelfLast = sf; mHxlatPeerLast = pr; mHxlatUnmatchedLast = un;
        if (sbDiagOn()) fputs(line, stderr);
        if (const char* home = std::getenv("HOME"); home && home[0]) {   // hxlat.log, capped at 1 MB (rotated once)
            const std::string lp = sbLogDir() + "/hxlat.log";
            struct stat st; if (stat(lp.c_str(), &st) == 0 && st.st_size > 1024 * 1024) { std::rename(lp.c_str(), (lp + ".1").c_str()); }
            if (FILE* f = fopen(lp.c_str(), "a")) { fprintf(f, "%s ", Time::getCurrentTime().formatted("%Y-%m-%d %H:%M:%S").toRawUTF8()); fputs(line, f); fclose(f); }
        }
    }
    if (sbDiagOn()) fprintf(stderr, "[SB-AUDIO] %.1fs: callbacks=%lld expected=%lld missing=%lld xruns=+%d (total %d) sr=%.0f buf=%d frames=%lld short=%lld\n",
            dt, seen, expected, expected - seen, xr, xrunsTotal, sr, bufSize, frames, seen * (long long) bufSize - frames);
    if (const char* path = sbtap::tapConf("SB_SINK_EVLOG"); path && *path) {
        if (FILE* f = fopen(path, "a")) {
            const double ts = Time::currentTimeMillis() * 1e-3;
            fprintf(f, "%.3f callbacks %lld\n%.3f callbacks_missing %lld\n%.3f xrun %d\n%.3f frames %lld\n", ts, seen, ts, expected - seen, ts, xr, ts, frames);
            {   // Audio-thread lock-wait diagnostics (reset per tick)
                const uint32_t mx = mSbLockWaitMaxUs.exchange(0, std::memory_order_relaxed);
                const uint32_t nOver = mSbLockWaitsOver1ms.exchange(0, std::memory_order_relaxed);
                fprintf(f, "%.3f corelock_wait_max_us %u\n%.3f corelock_waits_gt1ms %u\n", ts, mx, ts, nOver);
            }
            {   // Recv-thread lateness behind the kernel (reset per tick)
                const uint32_t rmx = mSbRxLatMaxUs.exchange(0, std::memory_order_relaxed), rov = mSbRxLatOver2ms.exchange(0, std::memory_order_relaxed);
                const uint32_t rpk = mSbRxPackets.exchange(0, std::memory_order_relaxed), rpw = mSbRxMaxPerWake.exchange(0, std::memory_order_relaxed);
                fprintf(f, "%.3f rx_lat_max_us %u\n%.3f rx_lat_gt2ms %u\n%.3f rx_pkts %u\n%.3f rx_max_per_wake %u\n", ts, rmx, ts, rov, ts, rpk, ts, rpw);
                if (sbDiagOn()) fprintf(stderr, "[SB-RXLAT] max=%u us  >2ms=%u of %u pkts  max/wake=%u\n", rmx, rov, rpk, rpw);
            }
            {   // Audio-callback interval jitter (reset per tick)
                const uint32_t cmx = mSbCbGapMaxUs.exchange(0, std::memory_order_relaxed), cov = mSbCbGapOver2ms.exchange(0, std::memory_order_relaxed);
                fprintf(f, "%.3f cb_gap_max_us %u\n%.3f cb_gap_gt2ms %u\n", ts, cmx, ts, cov);
                if (sbDiagOn()) fprintf(stderr, "[SB-CBGAP] max=%u us  >2ms=%u\n", cmx, cov);
            }
            fclose(f);
        }
    }
}

void SonobusAudioProcessor::reportNetDietStatsIfDue()
{
    // Event thread only (20 ms cadence). Reads the
    // relaxed counters the RT threads bump and prints 10 s deltas. DBG is
    // compiled out in Release, so the stderr line is gated by
    // SB_NETDIET_STATS=1 (env or /tmp/sb_taps.conf, same mechanism as the taps).
    const double now = Time::getMillisecondCounterHiRes();
    if (mNetStatLastReportMs <= 0) { mNetStatLastReportMs = now; return; }
    if (now - mNetStatLastReportMs < 10000.0) return;
    const double secs = (now - mNetStatLastReportMs) * 1e-3;
    mNetStatLastReportMs = now;

    if (mNetStatEnabled < 0) {
        const char * v = sbtap::tapConf("SB_NETDIET_STATS");
        mNetStatEnabled = (v && *v && *v != '0') ? 1 : 0;
    }

    constexpr int kNetStats = 13;
    const uint64_t cur[kNetStats] = {
        mNetStatRecvWakes.load(std::memory_order_relaxed),
        mNetStatRecvPackets.load(std::memory_order_relaxed),
        mNetStatRecvMaxBurst.exchange(0, std::memory_order_relaxed),
        mNetStatEndpointCacheMiss.load(std::memory_order_relaxed),
        mNetStatEndpointStringPath.load(std::memory_order_relaxed),
        mNetStatDispatchHits.load(std::memory_order_relaxed),
        mNetStatDispatchMisses.load(std::memory_order_relaxed),
        mNetStatSendWakes.load(std::memory_order_relaxed),
        mNetStatSendPasses.load(std::memory_order_relaxed),
        mNetStatDispatchDups.load(std::memory_order_relaxed),
        mNetStatBundlesRecv.load(std::memory_order_relaxed),   // (hub diet v2)
        mNetStatBundleMsgs.load(std::memory_order_relaxed),
        mNetStatBundleBad.load(std::memory_order_relaxed)
    };
    uint64_t d[kNetStats];
    for (int i = 0; i < kNetStats; ++i) { d[i] = cur[i] - mNetStatPrev[i]; mNetStatPrev[i] = cur[i]; }
    d[2] = cur[2]; // max burst is per-interval, not cumulative

    const double wakes = (double) d[0], pkts = (double) d[1];
    const double hits = (double) d[5], misses = (double) d[6];
    const double perWake = wakes > 0 ? pkts / wakes : 0.0;
    const double hitPct = (hits + misses) > 0 ? 100.0 * hits / (hits + misses) : 0.0;
    const double passesPerWake = d[7] > 0 ? (double) d[8] / (double) d[7] : 0.0;
    const double msgsPerBundle = d[10] > 0 ? (double) d[11] / (double) d[10] : 0.0;

    DBG("[netdiet] recv " << (int)(pkts / secs) << " pps in " << (int)(wakes / secs) << " wakes/s ("
        << String(perWake, 2) << " pkt/wake, max " << (int) d[2] << "); ep-cache miss " << (int) d[3]
        << " str-path " << (int) d[4] << "; sink-dispatch hit " << String(hitPct, 1) << "% (" << (int) hits
        << "/" << (int) misses << "); bundles " << (int) d[10] << " (" << String(msgsPerBundle, 2)
        << " msg/bundle, bad " << (int) d[12] << "); send " << (int)(d[7] / secs) << " wakes/s, "
        << String(passesPerWake, 2) << " passes/wake");

    if (mNetStatEnabled == 1) {
        // Also append to SB_NETDIET_FILE (env/taps), for hosts where stderr cannot be captured
        // (Catalina's `open`).
        if (const char* nf = sbtap::tapConf("SB_NETDIET_FILE"); nf && *nf) {
            if (FILE* f = fopen(nf, "a")) {
                fprintf(f, "%.3f [netdiet] recv %.0f pps in %.0f wakes/s (%.2f pkt/wake, max %llu); ep-cache miss %llu str-path %llu; sink-dispatch hit %.1f%% (%llu/%llu) dup-skip %llu; bundles %llu (%.2f msg/bundle, %llu msgs, bad %llu); send %.0f wakes/s, %.2f passes/wake\n",
                        now * 1e-3, pkts / secs, wakes / secs, perWake, (unsigned long long) d[2],
                        (unsigned long long) d[3], (unsigned long long) d[4], hitPct,
                        (unsigned long long) d[5], (unsigned long long) d[6], (unsigned long long) d[9],
                        (unsigned long long) d[10], d[10] > 0 ? (double) d[11] / (double) d[10] : 0.0, (unsigned long long) d[11], (unsigned long long) d[12],
                        d[7] / secs, passesPerWake);
                fclose(f);
            }
        }
        fprintf(stderr, "[netdiet] recv %.0f pps in %.0f wakes/s (%.2f pkt/wake, max %llu); ep-cache miss %llu str-path %llu; sink-dispatch hit %.1f%% (%llu/%llu) dup-skip %llu; bundles %llu (%.2f msg/bundle, %llu msgs, bad %llu); send %.0f wakes/s, %.2f passes/wake\n",
                pkts / secs, wakes / secs, perWake, (unsigned long long) d[2],
                (unsigned long long) d[3], (unsigned long long) d[4], hitPct,
                (unsigned long long) d[5], (unsigned long long) d[6], (unsigned long long) d[9],
                (unsigned long long) d[10], msgsPerBundle, (unsigned long long) d[11], (unsigned long long) d[12],
                d[7] / secs, passesPerWake);
    }
}

void SonobusAudioProcessor::sendPingEvent(RemotePeer * peer)
{

    auto tt = aoo_osctime_get();

    char buf[AOO_MAXPACKETSIZE];
    osc::OutboundPacketStream outmsg(buf, sizeof(buf));

    try {
        outmsg << osc::BeginMessage(SONOBUS_FULLMSG_PING)
        << osc::TimeTag(tt)
        << osc::EndMessage;
    }
    catch (const osc::Exception& e){
        DBG("exception in ping message construction: " << e.what());
        return;
    }

    sendPeerMessage(peer, outmsg.Data(), (int32_t) outmsg.Size());

    DBG("Sent ping to peer: " << peer->endpoint->ipaddr);
}


void SonobusAudioProcessor::handlePingEvent(EndpointState * endpoint, uint64_t tt1, uint64_t tt2, uint64_t tt3)
{
    double diff1 = aoo_osctime_duration(tt1, tt2) * 1000.0;
    double diff2 = aoo_osctime_duration(tt2, tt3) * 1000.0;
    double rtt = aoo_osctime_duration(tt1, tt3) * 1000.0;

    const ScopedReadLock sl (mCoreLock);

    auto * peer = findRemotePeer(endpoint, -1);
    if (!peer) return;

    // smooth it
    peer->pingTime = rtt; // * 0.5;
    if (rtt < 600.0 ) {
        peer->smoothPingTime.Z *= 0.5f;
        peer->smoothPingTime.push(peer->pingTime);
    }

    DBG("ping recvd from " << peer->endpoint->ipaddr << ":" << peer->endpoint->port << " -- " << diff1 << " " << diff2 << " " <<  rtt << " smooth: " << peer->smoothPingTime.xbar << " stdev: " <<peer->smoothPingTime.s2xx);


    if (!peer->hasRealLatency) {
        peer->totalEstLatency =  peer->smoothPingTime.xbar + 2*peer->buffertimeMs + (1e3*currSamplesPerBlock/getSampleRate());
    }

    peer->gotNewStylePing = true;
}


int32_t SonobusAudioProcessor::handleSourceEvents(const aoo_event ** events, int32_t n, int32_t sourceId)
{
    for (int i = 0; i < n; ++i){
        switch (events[i]->type){
        case AOO_PING_EVENT:
        {
            aoo_ping_event *e = (aoo_ping_event *)events[i];
            double diff1 = aoo_osctime_duration(e->tt1, e->tt2) * 1000.0;
            double diff2 = aoo_osctime_duration(e->tt2, e->tt3) * 1000.0;
            double rtt = aoo_osctime_duration(e->tt1, e->tt3) * 1000.0;

            EndpointState * es = (EndpointState *)e->endpoint;
            
            RemotePeer * peer = findRemotePeer(es, sourceId);
            if (peer && !peer->gotNewStylePing) {
                const ScopedReadLock sl (mCoreLock);        

                // smooth it
                peer->pingTime = rtt; // * 0.5;
                if (rtt < 600.0 ) {
                    peer->smoothPingTime.Z *= 0.5f;
                    peer->smoothPingTime.push(peer->pingTime);
                }

                DBG("ping to source " << sourceId << " recvd from " <<  es->ipaddr << ":" << es->port << " -- " << diff1 << " " << diff2 << " " <<  rtt << " smooth: " << peer->smoothPingTime.xbar << " stdev: " <<peer->smoothPingTime.s2xx);
                
                
                if (!peer->hasRealLatency) {
                    peer->totalEstLatency =  peer->smoothPingTime.xbar + 2*peer->buffertimeMs + (1e3*currSamplesPerBlock/getSampleRate());
                }
            }
            break;
        }
        case AOO_INVITE_EVENT:
        {
            aoo_sink_event *e = (aoo_sink_event *)events[i];

            // accepts invites
            if (true){
                EndpointState * es = (EndpointState *)e->endpoint;
                // handle dummy source specially
                
                int32_t dummyid;
                
                if (mAooDummySource->get_id(dummyid) && dummyid == sourceId) {
                    // dummy source is special, and creates a remote peer

                    RemotePeer * peer = findRemotePeerByRemoteSinkId(es, e->id);
                    if (peer) {
                        // we already have a peer for this, interesting
                        DBG("Already had remote peer for " <<   es->ipaddr << ":" << es->port << "  ourId: " << peer->ourId);
                    } else if (!mIsConnectedToServer) {
                        peer = doAddRemotePeerIfNecessary(es);
                    }
                    else {
                        // connected to server, don't just respond to anyone
                        peer = findRemotePeer(es, -1);
                        if (!peer) {
                            DBG("Not reacting to invite from a peer not known in the group");
                            break;
                        }

                        DBG("Got invite from peer in the group");
                    }

                    const ScopedReadLock sl (mCoreLock);

                    // The hub assigns fresh AOO ids on every restart. add_sink(new id) while the
                    // stale id stays registered makes this source stream once per sink. Each
                    // RemotePeer's oursource has exactly one sink, so clear stale ones when the id
                    // moves.
                    if (peer->remoteSinkId != e->id) {
                        peer->oursource->remove_all();
                    }

                    peer->remoteSinkId = e->id;

                    // add their sink
                    peer->oursource->add_sink(es, peer->remoteSinkId, endpoint_send);
                    peer->oursource->set_sinkoption(es, peer->remoteSinkId, aoo_opt_protocol_flags, &e->flags, sizeof(int32_t));

                    if (peer->sendAllow) {
                        peer->oursource->start();
                        peer->sendActive = true;
                    } else {
                        peer->oursource->stop();
                        peer->sendActive = false;
                    }
                    
                    DBG("Was invited by remote peer " <<  es->ipaddr << ":" << es->port << " sourceId: " << peer->remoteSinkId << "  ourId: " <<  peer->ourId);

                    // now try to invite them back at their port , with the same ID, they 
                    // should have a source waiting for us with the same id

                    DBG("Inviting them back to our sink");
                    peer->remoteSourceId = peer->remoteSinkId;
                    peer->oursink->invite_source(es, peer->remoteSourceId, endpoint_send);

                    // now remove dummy handshake one
                    mAooDummySource->remove_sink(es, dummyid);
                    
                }
                else {
                    // invited 
                    DBG("Invite received to our source: " << sourceId << " from " << es->ipaddr << ":" << es->port << "  " << e->id);

                    RemotePeer * peer = findRemotePeer(es, sourceId);
                    if (peer) {

                        // Same stale-sink
                        // clear as the uninvited branch above — one sink per
                        // per-peer source; id moved = old registration leaks
                        // a duplicate stream.
                        if (peer->remoteSinkId != e->id) {
                            peer->oursource->remove_all();
                        }

                        peer->remoteSinkId = e->id;

                        peer->oursource->add_sink(es, peer->remoteSinkId, endpoint_send);
                        peer->oursource->set_sinkoption(es, peer->remoteSinkId, aoo_opt_protocol_flags, &e->flags, sizeof(int32_t));
                        
                        if (peer->sendAllow) {
                            peer->oursource->start();
                            
                            peer->sendActive = true;
                            DBG("Starting to send, we allow it");
                        } else {
                            peer->sendActive = false;
                            peer->oursource->stop();
                        }
                        
                        peer->connected = true;

                        updateRemotePeerUserFormat(-1, peer);
                        sendRemotePeerInfoUpdate(-1, peer);

                        DBG("Finishing peer connection for " << es->ipaddr << ":" << es->port  << "  " << peer->remoteSinkId);
                        
                    }
                    else {
                        // find by echo id
                        if (auto * echopeer = findRemotePeerByEchoId(es, sourceId)) {
                            if (echopeer->echosource) {
                                echopeer->echosource->add_sink(es, e->id, endpoint_send);
                                echopeer->echosource->start();
                            }
                            DBG("Invite to echo source adding sink " << e->id);
                        }
                        else if (auto * latpeer = findRemotePeerByLatencyId(es, sourceId)) {
                            if (latpeer->latencysource) {   // Was echopeer-> (null in this branch) — stock bug
                                latpeer->latencysource->add_sink(es, e->id, endpoint_send);
                                latpeer->latencysource->start();
                            }
                            DBG("Invite to our latency source adding sink " << e->id);
                        }
                        else {
                            // not one of our sources
                            DBG("No source " << sourceId << " invited, how is this possible?");

                            // In HostedMix the only entity that should ever invite our source is
                            // the hub. Arriving here with sourceId=1 (kSbClientOurId, what the hub
                            // uses) and no peer matching the endpoint means the hub peer is missing
                            // from mRemotePeers because the AOO PEER_JOIN race was lost. Force-add
                            // the hub peer at this endpoint so the invite can be re-processed.
                            //
                            // Safe because INVITE only fires when a real sink is actively trying to
                            // reach us, not on every broadcast packet, and this acts only in
                            // HostedMix, where hub-as-the-only-inviter is the invariant.
                            if (isHostedMixModeEnabled() && sourceId == 1) {
                                String hubUserCopy = mHubPeerUsername;
                                String hubIp       = es->ipaddr;
                                int    hubPort     = es->port;
                                int32_t inviteId   = e->id;
                                int32_t inviteFlags = e->flags;
                                MessageManager::callAsync(
                                    [this, hubUserCopy, hubIp, hubPort, inviteId, inviteFlags]() {
                                        {
                                            const ScopedReadLock sl(mCoreLock);
                                            for (auto* p : mRemotePeers) {
                                                if (p && p->userName == hubUserCopy) return;
                                            }
                                        }
                                        DBG("[INVITE-FORCEADD] hub-peer missing "
                                            "from list — force-adding '"
                                            << hubUserCopy << "' at " << hubIp
                                            << ":" << hubPort);
                                        struct sockaddr_in sa{};
                                        sa.sin_family = AF_INET;
                                        sa.sin_port   = htons((uint16_t)hubPort);
                                        inet_pton(AF_INET, hubIp.toRawUTF8(),
                                                  &sa.sin_addr);
                                        String gn = getCurrentJoinedGroup();
                                        connectRemotePeerRaw((void*)&sa,
                                                             hubUserCopy, gn,
                                                             !mMainRecvMute.get());
                                    });
                            }
                        }

                    }
                }
                
            } else {
                DBG("Invite received");
            }

            break;
        }
        case AOO_UNINVITE_EVENT:
        {
            aoo_sink_event *e = (aoo_sink_event *)events[i];

            // accepts uninvites
            if (true){
                EndpointState * es = (EndpointState *)e->endpoint;
                int32_t dummyid;

                
                RemotePeer * peer = findRemotePeerByRemoteSinkId(es, e->id);
                
                if (peer) {
                    int ourid = AOO_ID_NONE;
                    {
                        const ScopedReadLock sl (mCoreLock);        
                        ourid = peer->ourId;
                        peer->oursource->remove_all();
                        //peer->oursink->uninvite_all(); // ??
                        //peer->connected = false;
                        peer->sendActive = false;
                        peer->dataPacketsSent = 0;

                        if (!peer->recvActive) {
                            peer->connected = false;
                        }
                    }
                    
                    //doRemoveRemotePeerIfNecessary(es, ourid);
                    
                    DBG("Uninvited, removed remote peer " << es->ipaddr << ":" << es->port);
                    
                }
                else if (auto * echopeer = findRemotePeerByEchoId(es, sourceId)) {
                    if (echopeer->echosource) {
                        echopeer->echosource->remove_sink(es, e->id);
                        echopeer->echosource->stop();
                    }
                    DBG("UnInvite to echo source adding sink " << e->id);
                }
                else if (auto * latpeer = findRemotePeerByLatencyId(es, sourceId)) {
                    if (latpeer->latencysource) {   // Was echopeer-> (null here) — stock bug
                        latpeer->latencysource->remove_sink(es, e->id);
                        latpeer->latencysource->stop();
                    }
                    DBG("UnInvite to latency source adding sink " << e->id);
                }

                else {
                    DBG("Uninvite received to unknown");
                }

            } else {
                DBG("Uninvite received");
            }

            break;
        }
        case AOO_CHANGECODEC_EVENT:
        {
            aoo_source_event *e = (aoo_source_event *)events[i];
            DBG("Change codec received from sink " << e->id);
            
            EndpointState * es = (EndpointState *)e->endpoint;
            RemotePeer * peer = findRemotePeerByRemoteSinkId(es, e->id);
            
            if (peer) {
                // now we need to set our latency and echo source to match our main source's format
                aoo_format_storage fmt;
                if (peer->oursource && peer->oursource->get_format(fmt) > 0) {
                    if (peer->latencysource) peer->latencysource->set_format(fmt.header);
                    if (peer->echosource) peer->echosource->set_format(fmt.header);

                    AudioCodecFormatCodec codec = String(fmt.header.codec) == AOO_CODEC_OPUS ? CodecOpus : CodecPCM;
                    if (codec == CodecOpus) {
                        aoo_format_opus *ofmt = (aoo_format_opus *)&fmt;
                        int retindex = findFormatIndex(codec, ofmt->bitrate / ofmt->header.nchannels, 0);
                        if (retindex >= 0) {
                            peer->formatIndex = retindex; // new sending format index
                        }
                    }
                    else if (codec == CodecPCM) {
                        aoo_format_pcm *pfmt = (aoo_format_pcm *)&fmt;
                        int bdepth = pfmt->bitdepth == AOO_PCM_FLOAT32 ? 4 : pfmt->bitdepth == AOO_PCM_INT24 ? 3 : pfmt->bitdepth == AOO_PCM_FLOAT64 ? 8 : 2;
                        int retindex = findFormatIndex(codec, 0, bdepth);
                        if (retindex >= 0) {
                            peer->formatIndex = retindex; // new sending format index
                        }                        
                    }

                    // The hub upstream is
                    // pinned to PCM 16-bit. Our hub never issues codec-change
                    // requests, but the aoo source honours them
                    // (respect_codec_change_requests=1), so if one ever lands
                    // on the hub peer, re-assert PCM 16-bit right here (same
                    // set_format path this handler already uses above).
                    const int hubidx = getHubUpstreamFormatIndex();
                    if (hubidx >= 0 && isHubPeer(peer->userName) && peer->formatIndex != hubidx) {
                        DBG("Hub sink requested non-PCM16 codec for our upstream — re-asserting PCM 16-bit");
                        peer->formatIndex = hubidx;
        g_sbFmtWhy = "codecchange";
                        setupSourceFormat(peer, peer->oursource.get());
                        if (peer->latencysource) setupSourceFormat(peer, peer->latencysource.get(), true);
                        if (peer->echosource) setupSourceFormat(peer, peer->echosource.get(), true);
                    }
                }
                

            }
        }
        default:
            break;
        }
    }
    return 1;

}

int32_t SonobusAudioProcessor::handleSinkEvents(const aoo_event ** events, int32_t n, int32_t sinkId)
{
    for (int i = 0; i < n; ++i){
        switch (events[i]->type){
        case AOO_SOURCE_ADD_EVENT:
        {
            aoo_source_event *e = (aoo_source_event *)events[i];
            EndpointState * es = (EndpointState *)e->endpoint;

            RemotePeer * peer = findRemotePeer(es, sinkId);
            if (peer) {
                // someone has added us, thus accepting our invitation
                int32_t dummyid;
                                            
                if (mAooDummySource->get_id(dummyid) && dummyid == e->id ) {
                    // ignoring dummy add
                    DBG("Got dummy handshake add from " << es->ipaddr << ":" << es->port);
                }
                else {
                    DBG("Added source " << es->ipaddr << ":" << es->port << "  " <<  e->id  << " to our " << sinkId);
                    peer->remoteSourceId = e->id;
                    
                    peer->oursink->uninvite_source(es, 0, endpoint_send); // get rid of existing bogus one

                    if (peer->recvAllow) {
                        peer->oursink->invite_source(es, peer->remoteSourceId, endpoint_send);
                        //peer->recvActive = true;
                    } else {
                        DBG("we aren't accepting recv right now, politely decline it");
                        peer->oursink->uninvite_source(es, peer->remoteSourceId, endpoint_send);
                        peer->recvActive = false;                        
                    }
                    
                    peer->connected = true;
                    
                }
                
                // do invite here?
            }
            else {
                DBG("Added source to unknown " << e->id);
            }
            // add remote source
            //doAddRemoteSourceIfNecessary(es, e->id);


            break;
        }
        case AOO_SOURCE_FORMAT_EVENT:
        {
            aoo_source_event *e = (aoo_source_event *)events[i];
            EndpointState * es = (EndpointState *)e->endpoint;
            
            const ScopedReadLock sl (mCoreLock);        

            RemotePeer * peer = findRemotePeer(es, sinkId);
            if (peer) {
                aoo_format_storage f;
                if (peer->oursink->get_source_format(e->endpoint, e->id, f) > 0) {
                    DBG("Got source format event from " << es->ipaddr << ":" << es->port << "  " <<  e->id  << "  channels: " << f.header.nchannels);
                    // A
                    // /format from the (possibly restarted) hub source means
                    // the feed is bound again — stop the rebind watchdog.
                    peer->hostedFeedStale = false;
                    peer->recvMeterSource.resize(f.header.nchannels, meterRmsWindow);

                    // check for layout
                    bool gotuserformat = false;
                    char userfmtdata[1024];
                    int32_t retsize = peer->oursink->get_sourceoption(e->endpoint, e->id, aoo_opt_userformat, userfmtdata, sizeof(userfmtdata));
                    if (retsize > 0) {
                        ValueTree tree = ValueTree::readFromData (userfmtdata, retsize);

                        if (tree.isValid()) {
                            applyLayoutFormatToPeer(peer, tree);
                            gotuserformat = true;
                        }
                        else {
                            DBG("Error parsing userformat");
                        }
                    }
                    else {
                        DBG("No userformat: " << retsize);
                    }

                    if (peer->recvChannels != f.header.nchannels) {

                        {
                            const ScopedWriteLock sl (peer->sinkLock);

                            peer->recvChannels = std::min(MAX_PANNERS, f.header.nchannels);

                            // set up this sink with new channel count

                            int sinkchan = std::max(getMainBusNumOutputChannels(), peer->recvChannels);

                            peer->oursink->setup(getSampleRate(), currSamplesPerBlock, sinkchan);
                        }
                        peer->recvMeterSource.resize (peer->recvChannels, meterRmsWindow);

                        // for now if > 2, all on own changroup (by default)

                        if (!gotuserformat && !peer->recvdChanLayout) {
                            if (peer->recvChannels > 2) {
                                if (!peer->modifiedChanGroups) {
                                    for (int cgi=0; cgi < peer->recvChannels; ++cgi) {
                                        peer->chanGroups[cgi].params.chanStartIndex = cgi;
                                        peer->chanGroups[cgi].params.numChannels = 1;
                                    }
                                    peer->numChanGroups = peer->recvChannels;
                                }
                            }
                            else {
                                peer->chanGroups[0].params.numChannels = peer->recvChannels;
                                peer->numChanGroups = 1;

                                if (peer->recvChannels == 1) {
                                    peer->viewExpanded = false;
                                }
                            }
                        }

                        if (peer->recvChannels == 1) {
                            peer->viewExpanded = false;
                        }

                        /*
                        if (peer->recvChannels == 1) {
                            // center pan
                            peer->recvPan[0] = 0.0f;
                        } else if (peer->recvChannels == 2) {
                            // Left/Right
                            peer->recvStereoPan[0] = -1.0f;
                            peer->recvStereoPan[1] = 1.0f;
                        } else if (peer->recvChannels > 2) {
                            peer->recvStereoPan[0] = -1.0f;
                            peer->recvStereoPan[1] = 1.0f;
                            for (int i=2; i < peer->recvChannels; ++i) {
                                peer->recvPan[i] = 0.0f;
                            }
                        }
                         */
                    }


                    
                    AudioCodecFormatCodec codec = String(f.header.codec) == AOO_CODEC_OPUS ? CodecOpus : CodecPCM;
                    if (codec == CodecOpus) {
                        aoo_format_opus *fmt = (aoo_format_opus *)&f;
                        peer->recvFormat = AudioCodecFormatInfo(fmt->bitrate/fmt->header.nchannels, fmt->complexity, fmt->signal_type);
                        //peer->recvFormatIndex = findFormatIndex(codec, fmt->bitrate / fmt->header.nchannels, 0);
                    } else {
                        aoo_format_pcm *fmt = (aoo_format_pcm *)&f;
                        int bitdepth = fmt->bitdepth == AOO_PCM_INT16 ? 2 : fmt->bitdepth == AOO_PCM_INT24  ? 3  : fmt->bitdepth == AOO_PCM_FLOAT32 ? 4 : fmt->bitdepth == AOO_PCM_FLOAT64  ? 8 : 2;
                        peer->recvFormat = AudioCodecFormatInfo(bitdepth);
                        //peer->recvFormatIndex = findFormatIndex(codec, 0, fmt->bitdepth);
                    }
                    
                    clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientPeerChangedState, this, "format");
                }                
            }
            else { 
                DBG("format event to unknown " << e->id);
                
            }
            
            break;
        }
        case AOO_SOURCE_STATE_EVENT:
        {
            aoo_source_state_event *e = (aoo_source_state_event *)events[i];
            EndpointState * es = (EndpointState *)e->endpoint;

            DBG("Got source state event from " << es->ipaddr << ":" << es->port << " -- " << e->state);

            const ScopedReadLock sl (mCoreLock);        

            RemotePeer * peer = findRemotePeer(es, sinkId);
            if (peer) {
                peer->recvActive = peer->recvAllow && e->state > 0;
                if (!peer->recvActive && !peer->sendActive) {
                    peer->connected = false;
                } else {
                    peer->connected = true;                    
                }
            }
            
            //clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientPeerChangedState, this, "state");
            
            break;
        }
        case AOO_BLOCK_LOST_EVENT:
        {
            aoo_block_lost_event *e = (aoo_block_lost_event *)events[i];

            EndpointState * es = (EndpointState *)e->endpoint;

            DBG("Got source block lost event from " << es->ipaddr << ":" << es->port << "   " << e->id << " -- " << e->count);

            const ScopedReadLock sl (mCoreLock);                    
            RemotePeer * peer = findRemotePeer(es, sinkId);
            if (peer) {
                peer->dataPacketsDropped += e->count;
                
                if (peer->autosizeBufferMode != AutoNetBufferModeOff) {
                    // see if our drop rate exceeds threshold, and increase buffersize if so
                    double nowtime = Time::getMillisecondCounterHiRes();
                    const float dropratethresh = peer->autosizeBufferMode == AutoNetBufferModeInitAuto ? 1.0f : mAutoresizeDropRateThresh;
                    // During MEASURE each grow is a sink queue rebuild that itself causes drops on
                    // a slow client, a self-inflating measurement. MEASURE grows: at most one per 2
                    // s, none in the first 8 s.
                    const bool mcpMeasuring = peer->autosizeBufferMode == AutoNetBufferModeMeasureCommitPin && peer->mcpPhase == kMcpPhaseMeasure;
                    const float adjustlimit = mcpMeasuring ? 2.0f : 0.5f; // seconds between grows
                    const bool mcpJoinGrace = mcpMeasuring && peer->mcpMeasureStartTime > 0 && (nowtime - peer->mcpMeasureStartTime) * 1e-3 < 8.0;

                    bool autoinitdone = peer->autosizeBufferMode == AutoNetBufferModeInitAuto && peer->autoNetbufInitCompleted;

                    // Measure-commit-pin — once PINNED the
                    // loop stops reacting to individual loss events; they
                    // are only tallied into the 60s escalation window
                    // (evaluated at the PING site). During MEASURE the
                    // AutoFull machinery below runs unchanged.
                    bool mcppinned = peer->autosizeBufferMode == AutoNetBufferModeMeasureCommitPin && peer->mcpPhase == kMcpPhasePinned;
                    if (mcppinned) {
                        if (peer->mcpEscWindowStartTime <= 0) {
                            peer->mcpEscWindowStartTime = nowtime;
                            peer->mcpEscWindowCount = 0;
                        }
                        peer->mcpEscWindowCount++;
                    }

                    // LAN-isochronous sink (SB_AOO_ISO_BLOCKS) — depth is
                    // fixed in blocks inside the sink; never grow the ms pin (the sink
                    // would ignore it anyway; this keeps buffertimeMs/telemetry truthful).
                    static const bool sbIsoSink = [](){ const char* v = sbtap::tapConf("SB_AOO_ISO_BLOCKS"); return v && atoi(v) > 0; }();
                    if (peer->lastDroptime > 0 && !autoinitdone && !mcppinned && !mcpJoinGrace && !sbIsoSink && !sbIsoPeer(peer) && !sbAdaptPeer(peer)) {
                        double deltatime = (nowtime - peer->lastDroptime) * 1e-3;  
                        if (deltatime > adjustlimit) {
                            //float droprate =  (peer->dataPacketsDropped - peer->lastDropCount) / deltatime;
                            float droprate =  1.0f / deltatime; // treat any drops as one instance
                            if (droprate > dropratethresh) {
                                float adjms = 1000.0f * currSamplesPerBlock / getSampleRate();
                                // Floor-clamped apply (MCP: aux sinks are set once at COMMIT)
                                applyPeerSinkBufferMs(peer, peer->buffertimeMs + adjms, !mcpMeasuring);
                                peer->totalEstLatency = peer->smoothPingTime.xbar + 2*peer->buffertimeMs + (1e3*currSamplesPerBlock/getSampleRate());
                                peer->latencyDirty = true;
                                peer->fillRatioSlow.reset();
                                peer->fillRatio.reset();

                                DBG("AUTO-Increasing buffer time by " << adjms << " ms to " << (int)peer->buffertimeMs << " droprate: " << droprate);

                                if (isHostedMixModeEnabled()) {
                                    // One shared network path: keep the unified policy value
                                    // tracking the live auto landing so persistence and UI stay
                                    // truthful. Auto adjustments are deliberately not propagated
                                    // across peers (one peer's drops do not raise all sinks).
                                    mUnifiedReceiveBufferMs = jmax(peer->buffertimeMs, sbFeedBufferFloorMs());
                                }

                                if (peer->hasRealLatency) {
                                    peer->totalEstLatency = peer->totalLatency + (peer->buffertimeMs - peer->bufferTimeAtRealLatency);
                                }

                                // MeasureCommitPin's MEASURE
                                // phase runs the AutoFull machinery unchanged
                                // (only reaches here un-pinned), and records
                                // the working point it finds.
                                if (peer->autosizeBufferMode == AutoNetBufferModeMeasureCommitPin) {
                                    peer->mcpMaxReachedMs = jmax(peer->mcpMaxReachedMs, peer->buffertimeMs);
                                }

                                if (peer->autosizeBufferMode == AutoNetBufferModeAutoFull
                                    || peer->autosizeBufferMode == AutoNetBufferModeMeasureCommitPin) {

                                    const float timesincedecrthresh = 2.0;
                                    if (peer->lastNetBufDecrTime > 0 && (nowtime - peer->lastNetBufDecrTime)*1e-3 < timesincedecrthresh ) {
                                        peer->netBufAutoBaseline = peer->buffertimeMs;
                                        DBG("Got drop within short time thresh, setting minimum baseline for future decr to " << peer->netBufAutoBaseline);
                                    }
                                }

                                sendRemotePeerInfoUpdate(-1, peer); // send to this peer

                            }

                            float realdroprate =  (peer->dataPacketsDropped - peer->lastDropCount) / deltatime;
                            peer->fastDropRate.push(realdroprate);

                            peer->lastDroptime = nowtime;
                            peer->lastDropCount = peer->dataPacketsDropped;
                        }
                    }
                    else {
                        if (peer->lastDroptime > 0) {
                            double deltatime = (nowtime - peer->lastDroptime) * 1e-3;
                            float droprate =  (peer->dataPacketsDropped - peer->lastDropCount) / deltatime;
                            peer->fastDropRate.push(droprate);
                        }

                        peer->lastDroptime = nowtime;
                        peer->lastDropCount = peer->dataPacketsDropped;
                    }
                    

                    
                    //peer->lastNetBufDecrTime = 0; // reset auto-decr
                }
            }
            
            break;
        }
        case AOO_BLOCK_REORDERED_EVENT:
        {
            aoo_block_reordered_event *e = (aoo_block_reordered_event *)events[i];

            EndpointState * es = (EndpointState *)e->endpoint;

            DBG("Got source block reordered event from " << es->ipaddr << ":" << es->port << "  " << e->id << " -- " << e->count);

            break;
        }
        case AOO_BLOCK_RESENT_EVENT:
        {
            aoo_block_resent_event *e = (aoo_block_resent_event *)events[i];
            EndpointState * es = (EndpointState *)e->endpoint;

            DBG("Got source block resent event from " << es->ipaddr << ":" << es->port << "  " << e->id << " -- " << e->count);
            const ScopedReadLock sl (mCoreLock);                    
            RemotePeer * peer = findRemotePeer(es, sinkId);
            if (peer) {
                peer->dataPacketsResent += e->count;
            }

            break;
        }
        case AOO_BLOCK_GAP_EVENT:
        {
            aoo_block_gap_event *e = (aoo_block_gap_event *)events[i];

            EndpointState * es = (EndpointState *)e->endpoint;

            DBG("Got source block gap event from " << es->ipaddr << ":" << es->port << "  " << e->id << " -- " << e->count);

            break;
        }
        case AOO_PING_EVENT:
        {
            aoo_ping_event *e = (aoo_ping_event *)events[i];
            EndpointState * es = (EndpointState *)e->endpoint;


            double diff = aoo_osctime_duration(e->tt1, e->tt2) * 1000.0;
            DBG("Got source block ping event from " << es->ipaddr << ":" << es->port << "  " << e->id << " -- " << diff);


            RemotePeer * peer = findRemotePeer(es, sinkId);
            if (peer) {
                const ScopedReadLock sl (mCoreLock);

                double nowtime = Time::getMillisecondCounterHiRes();

                double deltadroptime = peer->lastDroptime > 0 ? (nowtime - peer->lastDroptime) * 1e-3 : (nowtime - peer->resetDroptime) * 1e-3;

                if (peer->autosizeBufferMode != AutoNetBufferModeOff) {
                    if (!peer->autoNetbufInitCompleted) {
                        const float nodropsthresh = 7.0;

                        if (deltadroptime > nodropsthresh) {
                            peer->autoNetbufInitCompleted = true;
                            peer->resetSafetyMuted = false;
                            // Floor the committed value at 1.5 processing blocks (~4 ms at
                            // 128/48k). A quiet connect window can measure well under one block,
                            // and even 1 block, while stable, has no margin.
                            {
                                const float floorMs = 1.5f * 1000.0f * currSamplesPerBlock / getSampleRate();
                                if (peer->buffertimeMs < floorMs) {
                                    applyPeerSinkBufferMs(peer, floorMs);
                                    DBG("InitAuto commit floored to " << floorMs << " ms");
                                }
                            }
                            DBG("Netbuf Initial auto time is done after no drops in " << nodropsthresh);

                            // clear drop count
                            // In hub mode the count is cumulative since join — it
                            // only clears on an explicit Reset. The rate bookkeeping re-bases instead.
                            peer->dataPacketsResent = 0;
                            if (isHostedMixModeEnabled()) { peer->lastDropCount = peer->dataPacketsDropped; }
                            else { peer->dataPacketsDropped = 0; peer->lastDropCount = 0; }
                            peer->resetDroptime = nowtime;
                            peer->fastDropRate.resetInitVal(0.0f);
                            //peer->lastDroptime = 0;
                        }

                    }

                }
                else {
                    // manual mode
                    peer->resetSafetyMuted = false;
                }


                // MeasureCommitPin's MEASURE phase runs the
                // full AutoFull machinery (incl. this decrease path); once
                // PINNED it must not enter here.
                if (peer->autosizeBufferMode == AutoNetBufferModeAutoFull
                    || (peer->autosizeBufferMode == AutoNetBufferModeMeasureCommitPin && peer->mcpPhase == kMcpPhaseMeasure)) {
                    // possibly adjust net buffer down, if it has been longer than threshold since last drop
                    double nowtime = Time::getMillisecondCounterHiRes();
                    const float nodropsthresh = 10.0; // no drops in 10 seconds
                    const float adjustlimit = 10; // don't adjust more often than once every 10 seconds

                    // Never step below the peer's floor.
                    const float decrFloorMs = jmax(peer->netBufAutoBaseline, peerBufferFloorMs(peer));
                    if (peer->lastNetBufDecrTime > 0 && peer->buffertimeMs > decrFloorMs + 0.01f && !peer->latencyMatched) {
                        double deltatime = (nowtime - peer->lastNetBufDecrTime) * 1e-3;
                        double deltadroptime = (nowtime - peer->lastDroptime) * 1e-3;
                        if (deltatime > adjustlimit) {
                            //float droprate =  (peer->dataPacketsDropped - peer->lastDropCount) / deltatime;
                            //if (droprate < dropratethresh) {
                            if (deltadroptime > nodropsthresh) {
                                float adjms = 1000.0f * currSamplesPerBlock / getSampleRate();
                                applyPeerSinkBufferMs(peer, std::max(peer->buffertimeMs - adjms, decrFloorMs));

                                peer->totalEstLatency = peer->smoothPingTime.xbar + 2*peer->buffertimeMs + (1e3*currSamplesPerBlock/getSampleRate());
                                peer->latencyDirty = true;

                                peer->fillRatioSlow.reset();
                                peer->fillRatio.reset();

                                if (peer->hasRealLatency) {
                                    peer->totalEstLatency = peer->totalLatency + (peer->buffertimeMs - peer->bufferTimeAtRealLatency);
                                }

                                DBG("AUTO-Decreasing buffer time by " << adjms << " ms to " << (int) peer->buffertimeMs);

                                if (isHostedMixModeEnabled()) {
                                    // Mirror the live auto landing into the unified policy value
                                    // (see the auto-increase note). The decrease itself is
                                    // floor-clamped.
                                    mUnifiedReceiveBufferMs = jmax(peer->buffertimeMs, sbFeedBufferFloorMs());
                                }

                                peer->lastNetBufDecrTime = nowtime;

                                sendRemotePeerInfoUpdate(-1, peer); // send to this peer

                            }

                            //peer->lastNetBufDropCount = peer->dataPacketsDropped;
                        }
                    }
                    else {
                        peer->lastNetBufDecrTime = nowtime;
                    }

                }

                // Measure-commit-pin lifecycle, driven off
                // the periodic source ping (event thread, ~1s cadence):
                //   MEASURE -> COMMIT after kMcpMeasureWindowSec;
                //   PINNED  -> escalation-only watchdog (60s windows).
                if (peer->autosizeBufferMode == AutoNetBufferModeMeasureCommitPin) {
                    double mcpnow = Time::getMillisecondCounterHiRes();
                    if (peer->mcpPhase == kMcpPhaseMeasure) {
                        if (peer->mcpMeasureStartTime <= 0) {
                            peer->mcpMeasureStartTime = mcpnow; // robustness: unset start
                        }
                        peer->mcpMaxReachedMs = jmax(peer->mcpMaxReachedMs, peer->buffertimeMs);
                        if ((mcpnow - peer->mcpMeasureStartTime) * 1e-3 >= kMcpMeasureWindowSec) {
                            commitMcpPinForPeer(peer, mcpnow);
                        }
                    }
                    else { // kMcpPhasePinned
                        if (peer->mcpEscWindowStartTime > 0
                            && (mcpnow - peer->mcpEscWindowStartTime) * 1e-3 >= kMcpEscWindowSec) {
                            if (peer->mcpEscWindowCount > kMcpEscEventsPerWindow) {
                                peer->mcpQuietWindows = 0;
                                escalateMcpPinForPeer(peer, mcpnow);
                            } else {
                                // Quiet pinned time earns its way down: a totally silent window
                                // bumps the streak; three in a row step the pin one block toward
                                // the floor. Any event resets the streak; real trouble re-escalates
                                // via the existing watchdog, so this can't oscillate faster than 3
                                // min down / 1 min up.
                                if (peer->mcpEscWindowCount == 0) {
                                    if (++peer->mcpQuietWindows >= 3
                                        && peer->buffertimeMs > mcpFloorMsFor(peer) + 0.01f) {   // Per-path floor (WAN >= 24)
                                        const float adjms = 1000.0f * currSamplesPerBlock / getSampleRate();
                                        applyPeerSinkBufferMs(peer, peer->buffertimeMs - adjms);   // clamps at the floor
                                        peer->mcpPinnedMs = peer->buffertimeMs;
                                        peer->latencyDirty = true;
                                        if (isHostedMixModeEnabled()) {
                                            mUnifiedReceiveBufferMs = jmax(peer->buffertimeMs, sbFeedBufferFloorMs());
                                        }
                                        commitCacheForPeer(peer);
                                        sendRemotePeerInfoUpdate(-1, peer);
                                        peer->mcpQuietWindows = 0;
                                        DBG("MCP STEP-DOWN: " << peer->userName << " to " << peer->buffertimeMs << " ms after 3 quiet windows");
                                    }
                                } else {
                                    peer->mcpQuietWindows = 0;
                                }
                                // clean window — restart tally
                                peer->mcpEscWindowStartTime = mcpnow;
                                peer->mcpEscWindowCount = 0;
                            }
                        }
                    }
                }
            }


            break;
        }
        default:
            break;
        }
    }
    return 1;
}

int32_t SonobusAudioProcessor::handleServerEvents(const aoo_event ** events, int32_t n)
{
    for (int i = 0; i < n; ++i){
        switch (events[i]->type){
            case AOONET_SERVER_USER_JOIN_EVENT:
            {
                aoonet_server_user_event *e = (aoonet_server_user_event *)events[i];
                
                DBG("Server - User joined: " << e->name);
                
                break;
            }
            case AOONET_SERVER_USER_LEAVE_EVENT:
            {
                aoonet_server_user_event *e = (aoonet_server_user_event *)events[i];
                
                DBG("Server - User left: " << e->name);
                
                
                break;
            }
            case AOONET_SERVER_GROUP_JOIN_EVENT:
            {
                aoonet_server_group_event *e = (aoonet_server_group_event *)events[i];
                
                DBG("Server - Group Joined: " << e->group << "  by user: " << e->user);
                
                break;
            }
            case AOONET_SERVER_GROUP_LEAVE_EVENT:
            {
                aoonet_server_group_event *e = (aoonet_server_group_event *)events[i];
                
                DBG("Server - Group Left: " << e->group << "  by user: " << e->user);
                
                break;
            }
            case AOONET_SERVER_ERROR_EVENT:
            {
                aoonet_server_event *e = (aoonet_server_event *)events[i];
                
                DBG("Server error: " << String::fromUTF8(e->errormsg));
                
                break;
            }
            default:
                DBG("Got unknown server event: " << events[i]->type);
                break;
        }
    }
    return 1;
}

// Shared priming for a relayed-sender row returned by doAddRemotePeerIfNecessary. That call dedups
// by (hub endpoint, userName), so the same RemotePeer comes back from the PREJOIN and the JOIN of
// one join, and from a rejoin whose LEAVE never reached us. Reset the layout only while no format
// has been received: zeroing chanGroups[0].params.numChannels on a row that already has its format
// leaves it with no mix path and no meters, because the AOO_SOURCE_FORMAT_EVENT handler's "channel
// count unchanged" gate never rebuilds the layout. A real channel-count change is handled by the
// FORMAT handler.
static void sb_primeRelayedPeer(SonobusAudioProcessor::RemotePeer* p)
{
    p->recvAllow  = true;
    p->recvActive = true;
    if (p->recvChannels <= 0) {
        p->modifiedChanGroups = false;
        p->modifiedMultiChanGroups = false;
        p->recvdChanLayout = false;
        p->numChanGroups = 1;
        p->chanGroups[0].params.numChannels = 0;
    }
}

int32_t SonobusAudioProcessor::handleClientEvents(const aoo_event ** events, int32_t n)
{
    for (int i = 0; i < n; ++i){
        switch (events[i]->type){
        case AOONET_CLIENT_CONNECT_EVENT:
        {
            aoonet_client_group_event *e = (aoonet_client_group_event *)events[i];

            if (e->result > 0){
                DBG("Connected to server!");
                mIsConnectedToServer = true;
                mSessionConnectionStamp = Time::getMillisecondCounterHiRes();
                // Latch initial auto-reconnect success so any queued retry
                // timers from the staggered launch chain bail without firing
                // another connectToServer — that would trigger hub eviction
                // of this session under same-username rules.
                mInitialAutoReconnectDone = true;
            } else {
                DBG("Couldn't connect to server - " << String::fromUTF8(e->errormsg));
                mIsConnectedToServer = false;
                mSessionConnectionStamp = 0.0;

                // The command-line launch connect failed -> reconnect-last may proceed.
                // "access denied" is excluded: the editor retries that itself with an auto-incremented user name.
                if (mLaunchConnectRequested.load() && !String::fromUTF8(e->errormsg).contains("access denied")) {
                    sbLaunchConnectFailed(e->errormsg);
                }

                // Self-extending retry chain on CONNECT failure that was an
                // auto-reconnect attempt. Network can take longer than expected
                // after launch (DNS/routing/NAT settling — "No route to host"
                // commonly seen for 1-3s before connect succeeds). Gated by
                // mInitialAutoReconnectDone so we don't keep retrying after a
                // successful connect that subsequently dropped (those are
                // handled by mReconnectTimer / reconnect-after-server-loss).
                if (mPendingReconnect && getAutoReconnectToLast()
                    && !mInitialAutoReconnectDone.load()) {
                    for (int delayMs : {5000, 10000, 20000, 40000}) {
                        Timer::callAfterDelay(delayMs, [this]() {
                            if (mInitialAutoReconnectDone.load()) return;
                            if (isConnectedToServer()) return;
                            if (!getAutoReconnectToLast()) return;
                            if (mLaunchConnectRequested.load()) {   
                                if (sbDiagOn()) fprintf(stderr, "[SB-CONNECT] retry chain: launch connect requested -> skip\n");
                                return;
                            }
                            reconnectToMostRecent();
                        });
                    }
                    // A player launched while the hub is down keeps trying every 30 s until
                    // connected or the user turns auto-reconnect off; a hub that is late, rebooting
                    // or power-cycled is normal.
                    if (!mLaunchRetryArmed) {
                        mLaunchRetryArmed = true;
                        sbScheduleLaunchRetry();
                    }
                }
            }
            mServerConnectInFlight = 0;

            if (mPendingReconnect) {
                
                if (mIsConnectedToServer && mPendingReconnectInfo.groupName.isNotEmpty()) {
                    mPendingReconnectInfo.timestamp = Time::getCurrentTime().toMilliseconds();
                    addRecentServerConnectionInfo(mPendingReconnectInfo);
                    setWatchPublicGroups(false);
                    DBG("Joining group after pending reconnect: " << mPendingReconnectInfo.groupName);
                    joinServerGroup(mPendingReconnectInfo.groupName, mPendingReconnectInfo.groupPassword, mPendingReconnectInfo.groupIsPublic);
                }
                
                mPendingReconnect = false;
            }

            if (mIsConnectedToServer && mReconnectTimer.isTimerRunning()) {
                DBG("Stopping reconnect timer");
                mReconnectTimer.stopTimer();
                mRecoveringFromServerLoss = false;
            }
            
            clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientConnected, this, e->result > 0, String::fromUTF8(e->errormsg));
            
            break;
        }
        case AOONET_CLIENT_DISCONNECT_EVENT:
        {
            aoonet_client_group_event *e = (aoonet_client_group_event *)events[i];
            if (e->result == 0){
                DBG("Disconnected from server - " << String::fromUTF8(e->errormsg));
                
                if (mCurrentJoinedGroup.isNotEmpty() && mReconnectAfterServerLoss.get() && !mReconnectTimer.isTimerRunning()) {
                    DBG("Starting reconnect timer");
                    mRecoveringFromServerLoss = true;
                    mReconnectTimer.startTimer(1000);
                }
            }

            // The library reports a
            // refused/dead TCP connect as a DISCONNECT (recv() failed) — surface it as a failed connect so the panel says so.
            const bool failedConnect = mServerConnectInFlight.get() != 0 && !mIsConnectedToServer;
            mPendingReconnect = false;
            mServerConnectInFlight = 0;

            // don't remove all peers?
            //removeAllRemotePeers();
            
            mIsConnectedToServer = false;
            mSessionConnectionStamp = 0.0;
            if (failedConnect) {
                String why = String::fromUTF8(e->errormsg);
                String msg = TRANS("could not reach ") + (mServerEndpoint ? mServerEndpoint->ipaddr + ":" + String(mServerEndpoint->port) : String("the server"));
                if (why.isNotEmpty()) msg << " (" << why << ")";
                clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientConnected, this, false, msg);
            }

            // The hub is
            // gone, so every per-listener feed it was sending us is gone with
            // it — but our relayed rows survive (peers_.clear() above emits no
            // PEER_LEAVE) with recvChannels still > 0. Mark each one stale so
            // the rebind watchdog armed by the reconnect's PREJOIN/JOIN
            // (scheduleHostedFeedRebind) does NOT bail on its first probe
            // and keeps re-requesting the feed until a fresh /format lands.
            // Short read only (we're on the event thread, inside
            // handleEvents' read); nothing here touches the audio thread.
            if (isHostedMixModeEnabled()) {
                int staleCount = 0;
                {
                    const ScopedReadLock sl (mCoreLock);
                    EndpointState* hubEp = nullptr;
                    for (auto* p : mRemotePeers) {
                        if (p && !p->infoOnly && p->userName == mHubPeerUsername) { hubEp = p->endpoint; break; }
                    }
                    if (hubEp) {
                        for (auto* p : mRemotePeers) {
                            if (!p || p->infoOnly || p->endpoint != hubEp || p->userName == mHubPeerUsername) continue;
                            p->hostedFeedStale = true;
                            ++staleCount;
                        }
                    }
                }
                if (sbDiagOn()) fprintf(stderr, "[SB-REBIND] hub disconnect → %d relayed feeds marked stale\n", staleCount);
            }

            clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientDisconnected, this, e->result > 0, String::fromUTF8(e->errormsg));

            break;
        }
        case AOONET_CLIENT_GROUP_JOIN_EVENT:
        {
            aoonet_client_group_event *e = (aoonet_client_group_event *)events[i];
            if (e->result > 0){
                DBG("Joined group - " << e->name);
                const ScopedLock sl (mClientLock);        
                mCurrentJoinedGroup = CharPointer_UTF8 (e->name);
                sbMarkLaunchRejoin(true);

                mSessionConnectionStamp = Time::getMillisecondCounterHiRes();


            } else {
                DBG("Couldn't join group " << e->name << " - " << String::fromUTF8(e->errormsg));
                // A failed rejoin (the hub restarted, e.g. with a new password) must surface like a
                // failed join. We are not in the group any more, so forget it; the editor then
                // reports the error ("wrong password"), opens the connect panel and disconnects
                // instead of retrying silently. Not for "already a group member": that is our own
                // duplicate launch-time JOIN answered by an older hub, and we are in the group.
                const String why = String::fromUTF8(e->errormsg);
                if (!why.containsIgnoreCase("already a group member")) {
                    const ScopedLock sl (mClientLock);
                    if (mCurrentJoinedGroup == String(CharPointer_UTF8 (e->name))) mCurrentJoinedGroup.clear();
                    // A refused player gets one explanation and stays put: no automatic retries of any kind.
                    mInitialAutoReconnectDone = true;
                    mPendingReconnect = false;
                    mRecoveringFromServerLoss = false;
                    mReconnectTimer.stopTimer();
                }
            }
            clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientGroupJoined, this, e->result > 0, CharPointer_UTF8 (e->name), String::fromUTF8(e->errormsg));
            break;
        }
        case AOONET_CLIENT_GROUP_LEAVE_EVENT:
        {
            aoonet_client_group_event *e = (aoonet_client_group_event *)events[i];
            if (e->result > 0){

                DBG("Group leave - " << e->name);

                const ScopedLock sl (mClientLock);        
                mCurrentJoinedGroup.clear();

                // assume they are all part of the group, XXX
                removeAllRemotePeers();

                //aoo_node_remove_group(x->x_node, gensym(e->name));
                

            } else {
                DBG("Couldn't leave group " << e->name << " - " << String::fromUTF8(e->errormsg));
            }

            clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientGroupLeft, this, e->result > 0, CharPointer_UTF8 (e->name), String::fromUTF8(e->errormsg));

            break;
        }
        case AOONET_CLIENT_GROUP_PUBLIC_ADD_EVENT:
        {
            aoonet_client_group_event *e = (aoonet_client_group_event *)events[i];
            DBG("Public group add/changed - " << e->name << " count: " << e->result);
            {
                const ScopedLock sl (mPublicGroupsLock);
                String group = CharPointer_UTF8 (e->name);
                AooPublicGroupInfo & ginfo = mPublicGroupInfos[group];
                ginfo.groupName = group;
                ginfo.activeCount = e->result;
                ginfo.timestamp = Time::getCurrentTime().toMilliseconds();
            }

            clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientPublicGroupModified, this, CharPointer_UTF8 (e->name), e->result,  String::fromUTF8(e->errormsg));
            break;
        }
        case AOONET_CLIENT_GROUP_PUBLIC_DEL_EVENT:
        {
            aoonet_client_group_event *e = (aoonet_client_group_event *)events[i];
            DBG("Public group deleted - " << e->name);
            {
                const ScopedLock sl (mPublicGroupsLock);
                String group = CharPointer_UTF8 (e->name);
                mPublicGroupInfos.erase(group);
            }

            clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientPublicGroupDeleted, this, CharPointer_UTF8 (e->name), String::fromUTF8(e->errormsg));
            break;
        }

        case AOONET_CLIENT_PEER_PREJOIN_EVENT:
        {
            aoonet_client_peer_event *e = (aoonet_client_peer_event *)events[i];

            if (e->result > 0){
                DBG("Peer attempting to join group " <<  e->group << " - user " << e->user);

                String peerUser = CharPointer_UTF8 (e->user);
                String peerGroup = CharPointer_UTF8 (e->group);
                if (!isHostedMixModeEnabled() || isHubPeer(peerUser)) {
                    clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientPeerPendingJoin, this, peerGroup, peerUser);
                }

                // In HostedMix mode for non-hub peers, AOO's real AOONET_CLIENT_PEER_JOIN_EVENT
                // requires the UDP handshake to succeed (deps/aoo/lib/src/client.cpp). For
                // WAN-to-LAN peer pairs the handshake can't succeed (no reachable path), so JOIN
                // never fires and the relayed-peer + feedreq path never triggers. Audio routes via
                // the hub, so direct peer reachability is irrelevant: run the relayed-peer path on
                // PREJOIN instead. JOIN's matching block is then redundant for LAN peers (it still
                // runs, idempotent via doAddRemotePeerIfNecessary's dedup).
                if (isHostedMixModeEnabled() && !isHubPeer(peerUser) && mAutoconnectGroupPeers) {
                    // Find
                    // the hub endpoint under a SHORT read, release, then run
                    // the stale-row GC with NO lock held (it takes the write
                    // lock internally — holding read here = upgrade deadlock
                    // against the main thread's force-add path).
                    EndpointState* hubEp = nullptr;
                    {
                        const ScopedReadLock slFind (mCoreLock);
                        for (auto * p : mRemotePeers) {
                            if (p && !p->infoOnly && p->userName == mHubPeerUsername) {
                                hubEp = p->endpoint; break;
                            }
                        }
                    }
                    if (hubEp) {
                        removeStaleSameNamePeers(peerUser, hubEp);
                    }
                    // doAdd takes the write lock first: find the hub under a short read and release
                    // before calling it. No blanket read over this block.
                    RemotePeer* hubPeer = nullptr;
                    {
                        const ScopedReadLock slFind2 (mCoreLock);
                        for (auto * p : mRemotePeers) {
                            if (p && !p->infoOnly && p->userName == mHubPeerUsername) {
                                hubPeer = p; break;
                            }
                        }
                    }
                    if (hubPeer && hubPeer->endpoint) {
                        auto* relayedPeer = doAddRemotePeerIfNecessary(hubPeer->endpoint, -1, peerUser, peerGroup);
                        if (relayedPeer) {
                            sb_primeRelayedPeer(relayedPeer);
                            String senderName = peerUser;
                            int32_t newOurId  = relayedPeer->ourId;

                            int32_t feedSrcId = sb_feedSourceIdFor(
                                getCurrentUsername().toStdString(),
                                senderName.toStdString());
                            if (relayedPeer->oursink && hubPeer->endpoint) {
                                relayedPeer->oursink->invite_source(
                                    hubPeer->endpoint, feedSrcId, endpoint_send);
                            }
                            Timer::callAfterDelay(200, [this, senderName, newOurId]() {
                                sendHubFeedReqForPeer(senderName, newOurId);
                            });
                            scheduleHostedFeedRebind(senderName, newOurId);

                            // Fire the UI "peer joined" callback so the
                            // peer row appears even though AOO's JOIN will
                            // never fire for unreachable WAN peers.
                            clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientPeerJoined, this, peerGroup, peerUser);
                        }
                    } else {
                        // Hub peer not in mRemotePeers yet: schedule retries until it appears. Same
                        // chain as the JOIN-side race handling. PREJOIN has no e->address, so skip
                        // the doAddInfoOnlyPeerIfNecessary placeholder.
                        String senderName = peerUser;
                        String senderGroup = peerGroup;
                        for (int delayMs : {200, 500, 1000, 2000, 4000}) {
                            Timer::callAfterDelay(delayMs, [this, senderName, senderGroup]() {
                                // removeRemotePeer and doAddRemotePeerIfNecessary are write-first,
                                // so never hold the read lock across them (a read->write upgrade
                                // can deadlock). Short read for the find, release, then the
                                // write-side ops.
                                EndpointState* hubEndpoint = nullptr;
                                {
                                    const ScopedReadLock sl (mCoreLock);
                                    for (auto * p : mRemotePeers) {
                                        if (p && !p->infoOnly && p->userName == mHubPeerUsername) {
                                            if (p->endpoint) hubEndpoint = p->endpoint;
                                            break;
                                        }
                                    }
                                    if (hubEndpoint) {
                                        // Already promoted?
                                        for (auto * p : mRemotePeers) {
                                            if (p && !p->infoOnly && p->userName == senderName) return;
                                        }
                                    }
                                }
                                if (!hubEndpoint) return;
                                // stale same-name rows: find under short read,
                                // remove outside it (removeRemotePeer is
                                // write-first; index re-checked each pass)
                                for (;;) {
                                    int staleIdx = -1;
                                    {
                                        const ScopedReadLock sl (mCoreLock);
                                        for (int i = mRemotePeers.size() - 1; i >= 0; --i) {
                                            auto * p = mRemotePeers.getUnchecked(i);
                                            if (p && p->userName == senderName) { staleIdx = i; break; }
                                        }
                                    }
                                    if (staleIdx < 0) break;
                                    removeRemotePeer(staleIdx, false);
                                }
                                auto* relayed = doAddRemotePeerIfNecessary(hubEndpoint, -1, senderName, senderGroup);
                                if (relayed) {
                                    sb_primeRelayedPeer(relayed);
                                    int32_t newOurId = relayed->ourId;
                                    if (relayed->oursink) {
                                        relayed->oursink->invite_source(hubEndpoint,
                                            sb_feedSourceIdFor(getCurrentUsername().toStdString(), senderName.toStdString()),
                                            endpoint_send);
                                    }
                                    sendHubFeedReqForPeer(senderName, newOurId);
                                    scheduleHostedFeedRebind(senderName, newOurId);
                                    clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientPeerJoined, this, senderGroup, senderName);
                                }
                            });
                        }
                    }
                }

            } else {
                DBG("bug bad result on join event");
            }

            break;
        }
        case AOONET_CLIENT_PEER_JOIN_EVENT:
        {
            aoonet_client_peer_event *e = (aoonet_client_peer_event *)events[i];

            if (e->result > 0){
                DBG("Peer joined group " <<  e->group << " - user " << e->user);

                EndpointState * endpoint = findOrAddRawEndpoint(e->address);
                if (endpoint) {
                 
                    // check if blocked
                    if (isAddressBlocked(endpoint->ipaddr)) {
                        
                        clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientPeerJoinBlocked, this, CharPointer_UTF8 (e->group), CharPointer_UTF8 (e->user), endpoint->ipaddr, endpoint->port);

                        // after a short delay
                        Timer::callAfterDelay(400, [this, endpoint] {
                            sendBlockedInfoMessage(endpoint, true);
                        });
                    }
                    else {
                        String peerUser = CharPointer_UTF8 (e->user);
                        String peerGroup = CharPointer_UTF8 (e->group);

                        if (mAutoconnectGroupPeers) {
                            if (isHostedMixModeEnabled()) {
                                // In hosted mode, only connect to the hub peer — skip direct P2P with other participants
                                if (isHubPeer(peerUser)) {
                                    DBG("Hosted mode: connecting to hub peer '" << peerUser << "'");
                                    connectRemotePeerRaw(e->address, peerUser, peerGroup, !mMainRecvMute.get());

                                    // Force-ensure send is active on the hub peer. Across many
                                    // reconnect cycles in a session the sendAllow/sendAllowCache
                                    // state on the hub peer can get stuck false (info-only path
                                    // dirties cached false, mute-toggle path restores only from
                                    // cache — toggle can't recover). Reset both and explicitly
                                    // start oursource so audio actually flows after handshake.
                                    {
                                        // Re-assert send state at multiple delays. Under rapid hub
                                        // bounces a transient mActiveSendChannels=0 or oursource=null
                                        // at a single 500 ms snapshot leaves the source
                                        // half-configured, sending silent samples even though input
                                        // meters keep flowing. Retrying at 500/1500/3000/6000 ms
                                        // catches late-arriving audio-bus reinit. Each retry is
                                        // idempotent.
                                        juce::String hubNameCap = peerUser;
                                        for (int delayMs : {500, 1500, 3000, 6000}) {
                                            juce::Timer::callAfterDelay(delayMs, [this, hubNameCap]() {
                                                const juce::ScopedReadLock sl(mCoreLock);
                                                for (int i = 0; i < mRemotePeers.size(); ++i) {
                                                    auto* p = mRemotePeers.getUnchecked(i);
                                                    if (p && !p->infoOnly && p->userName == hubNameCap) {
                                                        if (!mMainSendMute.get()) {
                                                            p->sendAllow      = true;
                                                            p->sendAllowCache = true;
                                                            if (p->oursource) p->oursource->start();
                                                            setRemotePeerSendActive(i, true);
                                                        }
                                                        if (p->oursource) {
                                                            // Force re-eval of sendChannels via sentinel.
                                                            p->sendChannels = -1;
                                                            updateRemotePeerSendChannels(i, p);
                                                        }
                                                        break;
                                                    }
                                                }
                                            });
                                        }
                                    }

                                    // The dummy-handshake invite at peer-join can race with cached
                                    // recvAllow=false state and leave the local sink without a
                                    // source_desc, so audio decode never starts. Force a
                                    // recv-active re-invite ~600 ms later: by then remoteSourceId
                                    // is populated and setRemotePeerRecvActive's
                                    // oursink->invite_source(endpoint, remoteSourceId, ...)
                                    // re-establishes the sink subscription regardless of cache
                                    // state.
                                    juce::String hubName = peerUser;
                                    // Retry several times: remoteSourceId only gets set after the
                                    // dummy-handshake completes, which can take more than 1 s after
                                    // peer-join. Re-invite for ~4 s to catch the moment.
                                    //
                                    // If remoteSourceId is still AOO_ID_NONE at retry time, replay
                                    // the blind invite to source 0. Calling setRemotePeerRecvActive
                                    // would forward AOO_ID_NONE (INT_MIN) into invite_source and
                                    // put /aoo/src/-2147483648/invite on the wire, which the hub
                                    // silently ignores. The blind invite nudges the hub to reply
                                    // with AOONET_SINK_ADDED_EVENT carrying a real source id, after
                                    // which a later tick can do the real setRemotePeerRecvActive.
                                    for (int delayMs : {500, 1000, 1800, 3000, 4500}) {
                                        juce::Timer::callAfterDelay(delayMs, [this, hubName]() {
                                            const juce::ScopedReadLock sl (mCoreLock);
                                            for (int i = 0; i < mRemotePeers.size(); ++i) {
                                                auto* p = mRemotePeers.getUnchecked(i);
                                                if (p && !p->infoOnly && p->userName == hubName) {
                                                    if (p->remoteSourceId == AOO_ID_NONE) {
                                                        if (p->endpoint != nullptr && p->oursink != nullptr) {
                                                            p->oursink->invite_source(p->endpoint, 0, endpoint_send);
                                                        }
                                                    } else {
                                                        setRemotePeerRecvActive(i, true);
                                                    }
                                                    break;
                                                }
                                            }
                                        });
                                    }
                                } else {
                                    // Create a real RemotePeer for this sender, sharing the hub's
                                    // EndpointState (audio arrives from the hub, not from the
                                    // sender's IP). Allocate a fresh ourId for the local oursink,
                                    // tell the hub to allocate a per-(listener, sender) feed
                                    // pointed at that ourId, and immediately invite the feed source
                                    // by its deterministic id so AOO emits format right away (no 10
                                    // s startup delay).
                                    RemotePeer* hubPeer = nullptr;
                                    {   // Short read for the find; doAdd below is write-first
                                        const ScopedReadLock slFind (mCoreLock);
                                        for (auto * p : mRemotePeers) {
                                            if (p && !p->infoOnly && p->userName == mHubPeerUsername) {
                                                hubPeer = p; break;
                                            }
                                        }
                                    }
                                    if (hubPeer && hubPeer->endpoint) {
                                        auto* relayedPeer = doAddRemotePeerIfNecessary(hubPeer->endpoint, -1, peerUser, peerGroup);
                                        if (relayedPeer) {
                                            sb_primeRelayedPeer(relayedPeer);
                                            String senderName = peerUser;
                                            int32_t newOurId  = relayedPeer->ourId;

                                            int32_t feedSrcId = sb_feedSourceIdFor(
                                                getCurrentUsername().toStdString(),
                                                senderName.toStdString());
                                            if (relayedPeer->oursink && hubPeer->endpoint) {
                                                relayedPeer->oursink->invite_source(
                                                    hubPeer->endpoint, feedSrcId, endpoint_send);
                                            }
                                            Timer::callAfterDelay(200, [this, senderName, newOurId]() {
                                                sendHubFeedReqForPeer(senderName, newOurId);
                                            });
                                            scheduleHostedFeedRebind(senderName, newOurId);
                                        }
                                    } else {
                                        // AOO server PEER_JOIN events can arrive with the non-hub peer
                                        // before SonoBus-Hub. Fall back to info-only and schedule
                                        // retries that promote it to a real relayed peer once the hub
                                        // peer appears in mRemotePeers.
                                        doAddInfoOnlyPeerIfNecessary(endpoint, peerUser, peerGroup);
                                        String senderName = peerUser;
                                        String senderGroup = peerGroup;
                                        for (int delayMs : {200, 500, 1000, 2000, 4000}) {
                                            Timer::callAfterDelay(delayMs, [this, senderName, senderGroup]() {
                                                // Same read->write upgrade rule as the PREJOIN chain (see
                                                // comment there): short read for the find, release, then the
                                                // write-first ops.
                                                EndpointState* hubEndpoint = nullptr;
                                                {
                                                    const ScopedReadLock sl (mCoreLock);
                                                    for (auto * p : mRemotePeers) {
                                                        if (p && !p->infoOnly && p->userName == mHubPeerUsername) {
                                                            if (p->endpoint) hubEndpoint = p->endpoint;
                                                            break;
                                                        }
                                                    }
                                                    if (hubEndpoint) {
                                                        // Already promoted?
                                                        for (auto * p : mRemotePeers) {
                                                            if (p && !p->infoOnly && p->userName == senderName) return;
                                                        }
                                                    }
                                                }
                                                if (!hubEndpoint) return; // try again later
                                                // Remove any orphan info-only entry for this username
                                                // before promoting (info-only entry's endpoint differs
                                                // from hub's, so doAddRemotePeerIfNecessary's dedup
                                                // wouldn't collide — explicit removal needed).
                                                for (;;) {
                                                    int staleIdx = -1;
                                                    {
                                                        const ScopedReadLock sl (mCoreLock);
                                                        for (int i = mRemotePeers.size() - 1; i >= 0; --i) {
                                                            auto * p = mRemotePeers.getUnchecked(i);
                                                            if (p && p->userName == senderName) { staleIdx = i; break; }
                                                        }
                                                    }
                                                    if (staleIdx < 0) break;
                                                    removeRemotePeer(staleIdx, false);
                                                }
                                                auto* relayed = doAddRemotePeerIfNecessary(hubEndpoint, -1, senderName, senderGroup);
                                                if (relayed) {
                                                    // Same cache-reset as the eager path above so multi-channel
                                                    // senders get auto-split into per-channel groups.
                                                    sb_primeRelayedPeer(relayed);
                                                    int32_t newOurId = relayed->ourId;
                                                    if (relayed->oursink) {
                                                        relayed->oursink->invite_source(hubEndpoint,
                                                            sb_feedSourceIdFor(getCurrentUsername().toStdString(), senderName.toStdString()),
                                                            endpoint_send);
                                                    }
                                                    sendHubFeedReqForPeer(senderName, newOurId);
                                                    scheduleHostedFeedRebind(senderName, newOurId);
                                                }
                                            });
                                        }
                                    }
                                }
                            } else {
                                connectRemotePeerRaw(e->address, peerUser, peerGroup, !mMainRecvMute.get());
                            }
                        }

                        clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientPeerJoined, this, peerGroup, peerUser);
                    }
                }
                
            } else {
                DBG("bug bad result on join event");
            }
            

            break;
        }
        case AOONET_CLIENT_PEER_JOINFAIL_EVENT:
        {
            aoonet_client_peer_event *e = (aoonet_client_peer_event *)events[i];
            
            if (e->result > 0){
                DBG("Peer failed to join group " <<  e->group << " - user " << e->user);
                
                clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientPeerJoinFailed, this, CharPointer_UTF8 (e->group), CharPointer_UTF8 (e->user));
                
            } else {
                DBG("bug bad result on join event");
            }
                        
            break;
        }
        case AOONET_CLIENT_PEER_LEAVE_EVENT:
        {
            aoonet_client_peer_event *e = (aoonet_client_peer_event *)events[i];

            if (e->result > 0){

                DBG("Peer leave group " <<  e->group << " - user " << e->user);

                EndpointState * endpoint = findOrAddRawEndpoint(e->address);
                if (endpoint) {

                    removeAllRemotePeersWithEndpoint(endpoint);
                }

                // In HostedMix mode relayed peers share the hub's endpoint, not the sender's own
                // address, so the by-endpoint sweep above misses them. Also remove by username so
                // the relayed entry for this departing sender is dropped; otherwise it persists as
                // an orphan UI row after the sender has left and reappears alongside a fresh
                // relayed entry when they rejoin.
                if (isHostedMixModeEnabled()) {
                    // removeRemotePeer is write-first, so it must not run while holding the read
                    // lock. Find under a short read, remove outside it.
                    String leavingUser = CharPointer_UTF8(e->user);
                    for (;;) {
                        int idx = -1;
                        {
                            const ScopedReadLock sl (mCoreLock);
                            for (int i = mRemotePeers.size() - 1; i >= 0; --i) {
                                auto * p = mRemotePeers.getUnchecked(i);
                                if (p && p->userName == leavingUser && !isHubPeer(p->userName)) {
                                    idx = i; break;
                                }
                            }
                        }
                        if (idx < 0) break;
                        DBG("HostedMix cleanup: removing relayed peer for departing user '"
                            << leavingUser << "' at index " << idx);
                        removeRemotePeer(idx, false);
                    }
                }

                //aoo_node_remove_peer(x->x_node, gensym(e->group), gensym(e->user));
                clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientPeerLeft, this, CharPointer_UTF8 (e->group), CharPointer_UTF8 (e->user));

            } else {
                DBG("bug bad result on leave event");
            }
            break;
        }
        case AOONET_CLIENT_ERROR_EVENT:
        {
            aoonet_client_event *e = (aoonet_client_event *)events[i];
            DBG("client error: " << String::fromUTF8(e->errormsg));
            clientListeners.call(&SonobusAudioProcessor::ClientListener::aooClientError, this, String::fromUTF8(e->errormsg));
            break;
        }
        default:
            DBG("Got unknown client event: " << events[i]->type);
            break;
        }
    }
    return 1;
}


int SonobusAudioProcessor::connectRemotePeerRaw(void * sockaddr, const String & username, const String & groupname, bool reciprocate)
{
    EndpointState * endpoint = findOrAddRawEndpoint(sockaddr);
    
    if (!endpoint) {
        DBG("Error getting endpoint from raw address");
        return 0;
    }
    
    RemotePeer * remote = doAddRemotePeerIfNecessary(endpoint, AOO_ID_NONE, username, groupname); // get new one

    remote->recvAllow = !mMainRecvMute.get();
    
    // special - use 0 
    bool ret = remote->oursink->invite_source(endpoint, 0, endpoint_send) == 1;
    
    if (ret) {
        DBG("Successfully invited remote peer at " << endpoint->ipaddr << ":" << endpoint->port << " - ourId " << remote->ourId);
        remote->connected = true;
        remote->invitedPeer = reciprocate;
        //remote->recvActive = reciprocate;
        if (!mMainSendMute.get()) {
            remote->sendActive = true;
            remote->oursource->start();
            updateRemotePeerUserFormat(-1, remote);
            sendRemotePeerInfoUpdate(-1, remote);
        }
        else {
            remote->sendActive = false;
            remote->oursource->stop();
        }
        sendBlockedInfoMessage(remote->endpoint, false);
        
    } else {
        DBG("Error inviting remote peer at " << endpoint->ipaddr << ":" << endpoint->port << " - ourId " << remote->ourId);
    }

    return ret;    
}

int SonobusAudioProcessor::connectRemotePeer(const String & host, int port, const String & username, const String & groupname, bool reciprocate)
{
    EndpointState * endpoint = findOrAddEndpoint(host, port);

    RemotePeer * remote = doAddRemotePeerIfNecessary(endpoint, AOO_ID_NONE, username, groupname); // get new one

    remote->recvAllow = !mMainRecvMute.get();

    // special - use 0 
    bool ret = remote->oursink->invite_source(endpoint, 0, endpoint_send) == 1;
    
    if (ret) {
        DBG("Successfully invited remote peer at " <<  host << ":" << port << " - ourId " << remote->ourId);
        remote->connected = true;
        remote->invitedPeer = reciprocate;
        //remote->recvActive = reciprocate;
        if (!mMainSendMute.get()) {
            remote->sendActive = true;
            remote->oursource->start();
            updateRemotePeerUserFormat(-1, remote);
        }

        sendRemotePeerInfoUpdate(-1, remote);
        sendBlockedInfoMessage(remote->endpoint, false);
        
    } else {
        DBG("Error inviting remote peer at " << host << ":" << port << " - ourId " << remote->ourId);
    }

    return ret;
}

bool SonobusAudioProcessor::disconnectRemotePeer(const String & host, int port, int32_t ourId)
{
    EndpointState * endpoint = findOrAddEndpoint(host, port);
    bool ret = false;

    {
        const ScopedReadLock sl (mCoreLock);        
        
        RemotePeer * remote = findRemotePeer(endpoint, ourId);
        
        if (remote) {
            if (remote->oursink) {
                DBG("uninviting all remote source " << remote->remoteSourceId);
                ret = remote->oursink->uninvite_all();
                //ret = remote->oursink->uninvite_source(endpoint, remote->remoteSourceId, endpoint_send) == 1;
            }
         
            // if we auto-invited the other end's remote source, remove that as a dest sink
            if (remote->oursource) {
                DBG("removing all remote sink " << remote->remoteSinkId);
                remote->oursource->remove_all();
                //ret |= remote->oursource->remove_sink(endpoint, remote->remoteSinkId) == 1;
            }
            
            remote->connected = false;
            remote->recvActive = false;
            remote->sendActive = false;
        }
    }

    //doRemoveRemotePeerIfNecessary(endpoint, ourId);        

    
    if (ret) {
        DBG("Successfully disconnected remote peer " << ourId << " at " << host << ":" << port);
    } else {
        DBG("Error disconnecting remote peer " << ourId << " at " << host << ":" << port);
    }

    return ret;
}

bool SonobusAudioProcessor::disconnectRemotePeer(int index)
{
    RemotePeer * remote = 0;
    bool ret = false;
    {
        const ScopedReadLock sl (mCoreLock);
        
        if (index < mRemotePeers.size()) {
            remote = mRemotePeers.getUnchecked(index);
            if (remote->oursink) {
                DBG("uninviting all remote source " << remote->remoteSourceId);
                ret = remote->oursink->uninvite_all();
            }

            // if we auto-invited the other end's remote source, remove that as a dest sink
            if (remote->oursource && remote->remoteSinkId >= 0) {
                DBG("removing all remote sink " << remote->remoteSinkId);
                remote->oursource->remove_all();
                //ret |= remote->oursource->remove_sink(remote->endpoint, remote->remoteSinkId) == 1;
            }
            
            remote->connected = false;
            remote->recvActive = false;
            remote->sendActive = false;
            
            //mRemotePeers.remove(index);
        }
    }
    
    return ret;
}

bool SonobusAudioProcessor::getPatchMatrixValue(int srcindex, int destindex) const
{
    if (srcindex < MAX_PEERS && destindex < MAX_PEERS) {
        return mRemoteSendMatrix[srcindex][destindex];
    }
    return false;
}

void SonobusAudioProcessor::setPatchMatrixValue(int srcindex, int destindex, bool value)
{

    if (srcindex < MAX_PEERS && destindex < MAX_PEERS) {
        mRemoteSendMatrix[srcindex][destindex] = value;

        const ScopedReadLock sl (mCoreLock);        
        if (destindex < mRemotePeers.size() && destindex >= 0) {
            auto * peer = mRemotePeers.getUnchecked(destindex);

            updateRemotePeerSendChannels(destindex, peer);
            
        }
    }
}


void SonobusAudioProcessor::adjustRemoteSendMatrix(int index, bool removed)
{
    if (removed) {
        // adjust mRemoteSendMatrix
        // shift rows
        for (int i=index+1; i < mRemotePeers.size(); ++i) {
            // shift values up 1 from index+1 on
            for (int j=0; j < mRemotePeers.size(); ++j) {
                mRemoteSendMatrix[i-1][j] = mRemoteSendMatrix[i][j];         
            }                
        }
        // shift cols (one less row
        for (int i=0; i < mRemotePeers.size() - 1; ++i) {
            // shift values back 1 from index+1 on
            for (int j=index+1; j < mRemotePeers.size(); ++j) {
                mRemoteSendMatrix[i][j-1] = mRemoteSendMatrix[i][j];                    
            }                
        }
    }
    else {
        // adjust mRemoteSendMatrix to insert a new row
        // shift rows
        for (int i=mRemotePeers.size(); i > index; --i) {
            // shift values down 1 from index on
            for (int j=0; j < mRemotePeers.size(); ++j) {
                mRemoteSendMatrix[i][j] = mRemoteSendMatrix[i-1][j];         
            }                
        }
        // shift cols (one more row)
        for (int i=0; i < mRemotePeers.size() + 1; ++i) {
            // shift values forward 1 from index+1 on
            for (int j=mRemotePeers.size(); j > index; --j) {
                mRemoteSendMatrix[i][j] = mRemoteSendMatrix[i][j-1];                    
            }            
        }                
        // now put in default crossroutings
        for (int i=0; i < mRemotePeers.size() + 1; ++i) {
            mRemoteSendMatrix[i][index] = false;
            mRemoteSendMatrix[index][i] = false;
        }                

    }
}

bool SonobusAudioProcessor::removeAllRemotePeers()
{
    const ScopedReadLock sl (mCoreLock);

    OwnedArray<RemotePeer> removed;

    for (int index = 0; index < mRemotePeers.size(); ++index) {  
        auto remote = mRemotePeers.getUnchecked(index);
        
        commitCacheForPeer(remote);

        if (remote->connected) {
            disconnectRemotePeer(index);
        }

        removed.add(remote);
    }


    {
        const ScopedWriteLock slw (mCoreLock);
        mRemotePeers.clearQuick(false); // not deleting objects here
    }
    
    // reset matrix
    for (int i=0; i < MAX_PEERS; ++i) {
        for (int j=0; j < MAX_PEERS; ++j) {
            mRemoteSendMatrix[i][j] = false;
        }
    }

    // they will be cleaned up when removed list goes out of scope

    return true;
}


bool SonobusAudioProcessor::removeRemotePeer(int index, bool sendblock)
{
    // Write-first: a read->write upgrade deadlocks with any concurrent writer queued. In JUCE's
    // ReadWriteLock the upgrade waits behind the queued writer, the writer waits for this thread's
    // read to release, and every new reader (send/recv/audio threads) piles up behind the queued
    // writer. The write lock is re-entrant on the same thread, so the nested helpers are safe.
    // Callers must not hold the read lock.
    RemotePeer * remote = 0;
    bool ret = false;
    std::unique_ptr<RemotePeer> removed; // destroyed AFTER the lock scope —
                                         // peer teardown must not run under
                                         // the write lock (audio thread
                                         // readers would wait on it)
    {
        const ScopedWriteLock sl (mCoreLock);

        if (index < mRemotePeers.size()) {
            remote = mRemotePeers.getUnchecked(index);

            commitCacheForPeer(remote);

            if (remote->connected) {
                disconnectRemotePeer(index);
            }

            if (sendblock) {
                sendBlockedInfoMessage(remote->endpoint, true);
            }

            adjustRemoteSendMatrix(index, true);

            removed.reset(remote);

            mRemotePeers.remove(index, false); // deletion via removed's dtor, outside the lock

        }
    }

    return ret;
}


int SonobusAudioProcessor::getNumberRemotePeers() const
{
    return mRemotePeers.size();
}

void SonobusAudioProcessor::setRemotePeerLevelGain(int index, float levelgain)
{
    const ScopedReadLock sl (mCoreLock);
    if (index < mRemotePeers.size()) {
        RemotePeer * remote = mRemotePeers.getUnchecked(index);
        remote->gain = levelgain;
        commitCacheForPeer(remote);   // Row fader survives a quit at any moment (hub mode fader is this local gain)
    }
}

float SonobusAudioProcessor::getRemotePeerLevelGain(int index) const
{
    float levelgain = 0.0f;

    const ScopedReadLock sl (mCoreLock);
    if (index < mRemotePeers.size()) {
        RemotePeer * remote = mRemotePeers.getUnchecked(index);
        levelgain = remote->gain;
    }
    return levelgain;
}


void SonobusAudioProcessor::setRemotePeerChannelGain(int index, int changroup, float levelgain)
{
    const ScopedReadLock sl (mCoreLock);        
    if (index < mRemotePeers.size() && changroup < MAX_CHANGROUPS) {
        RemotePeer * remote = mRemotePeers.getUnchecked(index);
        remote->chanGroups[changroup].params.gain = levelgain;
    }
}

float SonobusAudioProcessor::getRemotePeerChannelGain(int index, int changroup) const
{
    float levelgain = 0.0f;
    
    const ScopedReadLock sl (mCoreLock);        
    if (index < mRemotePeers.size() && changroup < MAX_CHANGROUPS) {
        RemotePeer * remote = mRemotePeers.getUnchecked(index);
        levelgain = remote->chanGroups[changroup].params.gain;
    }
    return levelgain;
}

void SonobusAudioProcessor::setRemotePeerChannelReverbSend(int index, int changroup, float rgain)
{
    const ScopedReadLock sl (mCoreLock);
    if (index < mRemotePeers.size() && changroup < MAX_CHANGROUPS) {
        RemotePeer * remote = mRemotePeers.getUnchecked(index);
        remote->chanGroups[changroup].params.monReverbSend = rgain;
    }
}

float SonobusAudioProcessor::getRemotePeerChannelReverbSend(int index, int changroup)
{
    float revsend = 0.0f;

    const ScopedReadLock sl (mCoreLock);
    if (index < mRemotePeers.size() && changroup < MAX_CHANGROUPS) {
        RemotePeer * remote = mRemotePeers.getUnchecked(index);
        revsend = remote->chanGroups[changroup].params.monReverbSend;
    }
    return revsend;
}

