bool SonobusAudioProcessor::getRemotePeerHubLatency(int index, float & toHubMs, float & fromHubMs) const
{
    const ScopedReadLock sl (mCoreLock);
    if (index < mRemotePeers.size()) {
        auto * remote = mRemotePeers.getUnchecked(index);
        if (remote->hubLatStampMs == 0 || remote->hubLatToMs < 0.0f) return false;
        if (Time::getMillisecondCounter() - remote->hubLatStampMs > 35000) return false;   // Hub broadcasts every 10 s; older means stale (hub gone quiet)
        toHubMs = remote->hubLatToMs; fromHubMs = remote->hubLatFromMs;
        return true;
    }
    return false;
}

// That player's ping (hub<->them RTT) and uplink rate, from the hub's 1-Hz line
