// The ONE decision point for AOO dynamic resampling (see addRemotePeer).
bool SonobusAudioProcessor::sbDynamicResamplingWanted() const
{
    static const int tap = [](){ const char* v = sbtap::tapConf("SB_DYNRESAMP"); return (v && *v) ? atoi(v) : -1; }();
    if (tap >= 0) return tap != 0;                 // explicit tap wins (0 = off, 1 = on)
    if (isHostedMixModeEnabled()) return false;    // hub-hosted: never (clock-lock + drift ASRC own the clocks)
    return mDynamicResampling.get();               // legacy P2P: the user's option
}

void SonobusAudioProcessor::updateDynamicResampling()
{
    const ScopedReadLock sl (mCoreLock);
    bool newval = sbDynamicResamplingWanted();
    for (int i=0; i < mRemotePeers.size(); ++i) {
        RemotePeer * remote = mRemotePeers.getUnchecked(i);
        remote->oursink->set_dynamic_resampling(newval ? 1 : 0);
        remote->oursource->set_dynamic_resampling(newval ? 1 : 0);
    }
}




