void SonobusAudioProcessor::updateRemotePeerSendChannels(int index, RemotePeer * remote) {
    // this is called while the corereadlock is already held
    int newchancnt = remote->sendChannels;

    if (remote->sendChannelsOverride < 0) {
        int totinchans = 0;
        for (int cgi=0; cgi < mInputChannelGroupCount && cgi < MAX_CHANGROUPS ; ++cgi) {
            totinchans += mInputChannelGroups[cgi].params.numChannels;
        }
        // met and file and soundboard
        if (mSendMet.get() && !isHostedMixModeEnabled()) {   // Hosted = mixed in, never appended
            totinchans += 1;
        }
        if (mSendPlaybackAudio.get() && !isHostedMixModeEnabled()) {
            totinchans += mFilePlaybackChannelGroup.params.numChannels;
        }
        if (mSendSoundboardAudio.get() && !isHostedMixModeEnabled()) {
            // The send path only provides getFileSourceNumberOfChannels() soundboard channels, so
            // count those, not the soundboard channel group width, or the upstream source is
            // configured wider than its buffer.
            totinchans += soundboardChannelProcessor->getFileSourceNumberOfChannels();
        }

        newchancnt = isAnythingRoutedToPeer(index) ? getMainBusNumOutputChannels() :  remote->nominalSendChannels <= 0 ? totinchans : remote->nominalSendChannels;
    }
    else {
        newchancnt = jmin(getMainBusNumOutputChannels(), remote->sendChannelsOverride);
    }
    
    if (remote->sendChannels != newchancnt) {
        {   // Diag: where does the upstream channel count come from (the hub Mac shows 17)
            int ins = 0; for (int cgi=0; cgi < mInputChannelGroupCount && cgi < MAX_CHANGROUPS; ++cgi) ins += mInputChannelGroups[cgi].params.numChannels;
            if (sbDiagOn()) fprintf(stderr, "[SB-SENDCH] peer='%s' %d -> %d | inputs=%d (groups %d) met=%d file=%d sb=%d | override=%d nominal=%d routedToPeer=%d mainOut=%d mainIn=%d sendChansParam=%d\n",
                    remote->userName.toRawUTF8(), remote->sendChannels, newchancnt, ins, mInputChannelGroupCount,
                    mSendMet.get() ? 1 : 0, mSendPlaybackAudio.get() ? mFilePlaybackChannelGroup.params.numChannels : 0,
                    mSendSoundboardAudio.get() ? soundboardChannelProcessor->getFileSourceNumberOfChannels() : 0,
                    remote->sendChannelsOverride, remote->nominalSendChannels, isAnythingRoutedToPeer(index) ? 1 : 0,
                    getMainBusNumOutputChannels(), getMainBusNumInputChannels(), mSendChannels.get());
        }
        remote->sendChannels = newchancnt;
        DBG("Peer " << index << "  has new sendChannel count: " << remote->sendChannels);
        if (remote->oursource) {
        g_sbFmtWhy = "sendchans";
            setupSourceFormat(remote, remote->oursource.get());
            //setupSourceUserFormat(remote, remote->oursource.get());

            remote->oursource->setup(getSampleRate(), currSamplesPerBlock, remote->sendChannels);

            updateRemotePeerUserFormat(index);
        }
    }
}

void SonobusAudioProcessor::changeListenerCallback (ChangeBroadcaster* source)
{
    if (source == &mTransportSource) {
        if (!mTransportSource.isPlaying() && mTransportSource.getCurrentPosition() >= mTransportSource.getLengthInSeconds()) {
            // at end, return to start
            mTransportSource.setPosition(0.0);
        }

#if 0
        if (mSendChannels.get() == 0) {
            if (mTransportSource.isPlaying() && mSendPlaybackAudio.get()) {
                // override sending
                int srcchans = mCurrentAudioFileSource ? mCurrentAudioFileSource->getAudioFormatReader()->numChannels : 2;
                setRemotePeerOverrideSendChannelCount(-1, jmax(getMainBusNumInputChannels(), srcchans));
            }
            else if (!mTransportSource.isPlaying()) {
                // remove override
                setRemotePeerOverrideSendChannelCount(-1, -1);
            }
        }
#endif
    }
}

// Hub-relayed feeds underrun at the auto-tuner's ~1-4 ms landing zone, so floor hosted-mix receive
// buffers at 8 ms (override via SB_FEED_BUF_FLOOR_MS in /tmp/sb_taps.conf; 0 disables). Applies to
// auto, manual and reset paths, which all flow through setRemotePeerBufferTime.
static float sbFeedBufferFloorMs()
{
    static float floorMs = -1.0f;
    if (floorMs < 0.0f) {
        floorMs = 2.67f;   // tested default
        if (FILE* cf = sb_taps_fopen()) {
            char line[256];
            while (fgets(line, sizeof(line), cf)) {
                if (!strncmp(line, "SB_FEED_BUF_FLOOR_MS=", 21)) floorMs = (float)atof(line+21);
            }
            fclose(cf);
        }
        if (const char* e = getenv("SB_FEED_BUF_FLOOR_MS")) floorMs = (float)atof(e);
    }
    return floorMs;
}

void SonobusAudioProcessor::setRemotePeerBufferTime(int index, float bufferMs)
{
    // In HostedMix every remote feed rides the SAME
    // hub->us network path, so a "per-peer" buffer change is really a
    // change to the ONE shared policy — delegate so all sinks move in
    // lockstep. P2P (separate paths per peer) keeps per-peer behavior.
    if (isHostedMixModeEnabled()) {
        setUnifiedReceiveBufferTime(bufferMs);
        return;
    }
    applyRemotePeerBufferTime(index, bufferMs);
}

// Unified policy setter — clamps to the hosted feed floor
// and applies the one value to every remote peer's sinks when HostedMix is
// enabled. Outside hosted mode it only stores the value (nothing to apply).
void SonobusAudioProcessor::setUnifiedReceiveBufferTime(float bufferMs)
{
    bufferMs = jmax(bufferMs, sbHostedManualPin() ? sbHostedManualFloorMs() : sbFeedBufferFloorMs());   // Manual may go down to 2 blocks
    // In Smart Pin mode the unified value (MEASURE seed for
    // every joining peer) is never below the pin floor either.
    if (mUnifiedReceiveAutoMode == AutoNetBufferModeMeasureCommitPin) {
        bufferMs = jmax(bufferMs, mMcpPinFloorMs);
    }
    mUnifiedReceiveBufferMs = bufferMs;
    // A manual unified set invalidates any committed
    // measure-commit pin (per-peer MEASURE restart happens in
    // applyRemotePeerBufferTime below).
    mUnifiedMcpPinned = false;

    if (!isHostedMixModeEnabled()) return;

    const ScopedReadLock sl (mCoreLock);
    for (int i = 0; i < mRemotePeers.size(); ++i) {
        applyRemotePeerBufferTime(i, bufferMs);
    }
}

void SonobusAudioProcessor::applyRemotePeerBufferTime(int index, float bufferMs)
{
    const ScopedReadLock sl (mCoreLock);
    if (isHostedMixModeEnabled()) {
        bufferMs = jmax(bufferMs, sbHostedManualPin() ? sbHostedManualFloorMs() : sbFeedBufferFloorMs());
    }
    if (index >= 0 && index < mRemotePeers.size()) {
        RemotePeer * remote = mRemotePeers.getUnchecked(index);
        // Floor-clamped apply. In Smart Pin mode the reset-to-minimum button (bufferMs 0) restarts
        // MEASURE at the floor instead of at 0; the applied value is what MEASURE seeds from and
        // what the safety-mute decision below sees.
        bufferMs = applyPeerSinkBufferMs(remote, bufferMs);
        remote->totalEstLatency = remote->smoothPingTime.xbar + 2*remote->buffertimeMs + (1e3*currSamplesPerBlock/getSampleRate());
        remote->fillRatioSlow.reset();
        remote->fillRatio.reset();
        remote->netBufAutoBaseline = (1e3*currSamplesPerBlock/getSampleRate()); // at least a process block
        remote->latencyDirty = true;
        remote->autoNetbufInitCompleted = false;
        remote->lastDroptime = Time::getMillisecondCounterHiRes();
        remote->resetSafetyMuted = bufferMs == 0.0f;
        remote->latencyMatched = false;

        // Measure-commit-pin: any manual buffer set lands here (incl. the reset-to-minimum button,
        // which passes 0): restart the MEASURE phase and clear the persisted pin. This is the
        // manual de-bloat lever. The commit/escalate paths apply sinks inline and never enter this
        // function.
        if (remote->autosizeBufferMode == AutoNetBufferModeMeasureCommitPin) {
            remote->mcpPhase = kMcpPhaseMeasure;
            remote->mcpMeasureStartTime = remote->lastDroptime;
            remote->mcpMaxReachedMs = bufferMs;
            remote->mcpPinnedMs = 0.0f;
            remote->mcpEscWindowStartTime = 0;
            remote->mcpEscWindowCount = 0;
            if (isHostedMixModeEnabled()) {
                mUnifiedMcpPinned = false;
            }
        }

        //if (remote->autosizeBufferMode == AutoNetBufferModeOff) {
        // Clear drop count (hub mode keeps the cumulative count; see resetRemotePeerPacketStats)
        remote->dataPacketsResent = 0;
        if (!isHostedMixModeEnabled()) remote->dataPacketsDropped = 0;
        remote->resetDroptime = remote->lastDroptime;
        remote->fastDropRate.resetInitVal(0.0f);

        // Commit the cache immediately; saving only on graceful quit would lose the manual buffer
        // setting on a force-kill or hang.
        commitCacheForPeer(remote);
        remote->lastDropCount = isHostedMixModeEnabled() ? remote->dataPacketsDropped : 0;
        //}

        if (remote->hasRealLatency) {
            remote->totalEstLatency = remote->totalLatency + (remote->buffertimeMs - remote->bufferTimeAtRealLatency);
        }

        sendRemotePeerInfoUpdate(index);
    }
}

// A peer is "WAN" when its endpoint is a
// non-private IPv4 (or unknown). Private = 10/8, 172.16/12, 192.168/16, 127/8.
// Used by upstream redundancy (LAN 1 / WAN 2) and by Smart Pin's WAN limits.
bool SonobusAudioProcessor::sbPeerIsWan(const RemotePeer * peer) const
{
    if (!peer || !peer->endpoint) return true;
    uint32_t v4 = peer->endpoint->ipv4;
    // A RELAYED row's feed arrives from the
    // HUB over MY link, paced — not from the player's own address. Classify by my link to the hub,
    // or every LAN listener gives a remote player's feed the WAN adaptive profile.
    if (peer->relayedViaHub) { const uint32_t h = mHubLinkIpv4.load(std::memory_order_relaxed); if (h) v4 = h; }
    if (v4 == 0) return true;
    const uint32_t a = ntohl(v4);
    const bool priv = ((a & 0xFF000000u) == 0x0A000000u)
                   || ((a & 0xFFF00000u) == 0xAC100000u)
                   || ((a & 0xFFFF0000u) == 0xC0A80000u)
                   || ((a & 0xFF000000u) == 0x7F000000u);
    return !priv;
}

// Smart Pin limits per path. A high-jitter WAN link can show p99 jitter around 6 ms but burst
// stalls of 20-75 ms, so a WAN pin must be allowed to cover the bursts; too low a cap forces the
// governor's hard-full drain and steady underruns. There is no WAN-specific floor: a floor set by
// the worst link is the wrong rule for a nearby fiber connection, and a high-jitter link gets its
// depth as a measured outcome.
float SonobusAudioProcessor::mcpFloorMsFor(const RemotePeer * peer) const   { (void) peer; return mMcpPinFloorMs; }
float SonobusAudioProcessor::mcpCeilingMsFor(const RemotePeer * peer) const { return sbPeerIsWan(peer) ? 96.0f : 32.0f; }
float SonobusAudioProcessor::mcpSanityMaxMsFor(const RemotePeer * peer) const { return sbPeerIsWan(peer) ? 80.0f : 24.0f; }

// One floor, one apply path: a peer's receive buffer is never applied below peerBufferFloorMs,
// during MEASURE as well as at COMMIT. Event/message thread only (same as every caller).
float SonobusAudioProcessor::peerBufferFloorMs(const RemotePeer * peer) const
{
    float floorMs = 0.0f;
    if (peer->autosizeBufferMode == AutoNetBufferModeMeasureCommitPin) {
        floorMs = mcpFloorMsFor(peer);                 // LAN floor / WAN >= 24
    }
    if (isHostedMixModeEnabled()) {
        floorMs = jmax(floorMs, sbFeedBufferFloorMs()); // hosted feed floor (was bypassed by the decrease path)
    }
    return floorMs;
}

// LAN-isochronous receive depth, per peer (LAN only).
//   SB_AOO_ISO_LAN_BLOCKS=<n>  (taps file / env, read once): every LAN peer's
//   sink is pinned to n blocks (no slack, no ms ratchet/escalation); WAN peers
//   keep the Smart Pin. n=2 is too shallow.
int SonobusAudioProcessor::sbIsoLanBlocks() const
{
    static const int n = [](){ const char* v = sbtap::tapConf("SB_AOO_ISO_LAN_BLOCKS"); return v ? jlimit(0, 8, atoi(v)) : 3; }();   // default 3
    return n;
}
// WAN variant: SB_AOO_ISO_WAN_BLOCKS=<n> pins every WAN peer's sink to n blocks (e.g. 12 blocks = 8
// ms @32smp/48k) and conceals loss with PLC instead of escalating the pin.
int SonobusAudioProcessor::sbIsoWanBlocks() const
{
    static const int n = [](){ const char* v = sbtap::tapConf("SB_AOO_ISO_WAN_BLOCKS"); return v ? jlimit(0, 64, atoi(v)) : 0; }();
    return n;
}
int SonobusAudioProcessor::sbIsoBlocksFor(const RemotePeer * peer) const
{
    // The adaptive WAN sink (SB_AOO_ADAPT_WAN=1) takes precedence over a fixed WAN depth
    return sbPeerIsWan(peer) ? (sbAdaptWan() ? 0 : sbIsoWanBlocks()) : (sbAdaptLan() ? 0 : sbIsoLanBlocks());   // LAN adaptive takes precedence over fixed iso
}
// WAN ADAPTIVE receive depth — SB_AOO_ADAPT_WAN=1 (taps/env, read once) puts every
// WAN peer's sink under the JackTrip-style adaptive policy inside aoo (sink.cpp adapt_*): the depth
// follows measured arrival jitter (fast up, slow down) plus a glitch-budget headroom that decays;
// grow = PLC refill, shrink = one splice. LAN peers keep iso/canonical. The ms pin/ratchet/escalation
// are bypassed for these peers (the sink ignores ms changes once adaptive).
bool SonobusAudioProcessor::sbAdaptWan() const
{
    static const bool on = [](){ const char* v = sbtap::tapConf("SB_AOO_ADAPT_WAN"); return v ? atoi(v) > 0 : true; }();   // default on
    return on;
}
bool SonobusAudioProcessor::sbAdaptLan() const
{
    // LAN peers adapt too (floor = the 3-block iso depth, max 8 ms). SB_AOO_ADAPT_LAN=0 → fixed iso.
    static const bool on = [](){ const char* v = sbtap::tapConf("SB_AOO_ADAPT_LAN"); return v ? atoi(v) > 0 : true; }();
    return on;
}
bool SonobusAudioProcessor::sbAdaptPeer(const RemotePeer * peer) const
{
    if (sbHostedManualPin()) return false;   // Manual = the user owns the depth
    return sbPeerIsWan(peer) ? sbAdaptWan() : sbAdaptLan();
}
bool SonobusAudioProcessor::sbIsoPeer(const RemotePeer * peer) const
{
    if (sbHostedManualPin()) return false;
    return sbIsoBlocksFor(peer) > 0;
}
// The stock buffer control keeps its stock meaning in hub mode. Manual = pin the hub feed at the
// slider value (iso + adapt options cleared, floor = 2 blocks); any Auto mode = adaptive.
bool SonobusAudioProcessor::sbHostedManualPin() const
{
    return isHostedMixModeEnabled() && mUnifiedReceiveAutoMode == AutoNetBufferModeOff;
}
float SonobusAudioProcessor::sbHostedManualFloorMs() const
{
    const double sr = getSampleRate() > 0 ? getSampleRate() : 48000.0;
    return (float) (2.0 * 1000.0 * jmax(1, currSamplesPerBlock) / sr);
}
// The depth actually in force for ONE row —
// that row's sink target in blocks (aoo_opt_depth_blocks: adaptive/iso/pinned, published by the sink) × block ms.
// Returns -1 when the row has no live source yet. Caller holds mCoreLock (read).
float SonobusAudioProcessor::sbRowLiveDepthMs(const RemotePeer * remote) const
{
    if (!remote || remote->infoOnly || !remote->oursink || !remote->endpoint || remote->remoteSourceId == AOO_ID_NONE) return -1.0f;
    int32_t blocks = 0;
    aoo_format_storage f{};
    if (remote->oursink->get_sourceoption(remote->endpoint, remote->remoteSourceId, aoo_opt_depth_blocks, AOO_ARG(blocks)) > 0
        && blocks > 0
        && remote->oursink->get_source_format(remote->endpoint, remote->remoteSourceId, f) > 0
        && f.header.samplerate > 0) {
        return (float) (blocks * 1000.0 * f.header.blocksize / f.header.samplerate);
    }
    return -1.0f;
}

float SonobusAudioProcessor::getHostedFeedDepthMs() const
{
    const ScopedReadLock sl (mCoreLock);
    // The adaptive depth lives in the relayed player rows' sinks (one sink per player fed by the
    // hub). The hub pseudo-row's sink carries no audio and only holds the ms setting. Report the
    // largest live depth across the relayed rows, i.e. the depth the listener is actually behind
    // (what the hub's "From hub" leg must count); fall back to the hub row, then the setting.
    float best = -1.0f;
    for (int i = 0; i < mRemotePeers.size(); ++i) {
        RemotePeer * remote = mRemotePeers.getUnchecked(i);
        if (!remote || !remote->relayedViaHub) continue;
        const float ms = sbRowLiveDepthMs(remote);
        if (ms > best) best = ms;
    }
    if (best > 0.0f) return best;
    for (int i = 0; i < mRemotePeers.size(); ++i) {
        RemotePeer * remote = mRemotePeers.getUnchecked(i);
        if (!remote || remote->infoOnly || !remote->oursink || !isHubPeer(remote->userName)) continue;
        const float ms = sbRowLiveDepthMs(remote);
        return ms > 0.0f ? ms : remote->buffertimeMs;
    }
    return mUnifiedReceiveBufferMs;
}

float SonobusAudioProcessor::applyPeerSinkBufferMs(RemotePeer * peer, float bufferMs, bool auxSinks)
{
    bufferMs = jmax(bufferMs, sbHostedManualPin() ? sbHostedManualFloorMs() : peerBufferFloorMs(peer));
    peer->buffertimeMs = bufferMs;
    if (sbHostedManualPin()) {
        // Manual — clear iso + adaptive so the sink honours the ms request below (both idempotent)
        int32_t z = 0;
        peer->oursink->set_option(aoo_opt_iso_blocks, AOO_ARG(z));
        peer->oursink->set_option(aoo_opt_adapt, AOO_ARG(z));
    }
    if (sbIsoPeer(peer)) {
        int32_t n = sbIsoBlocksFor(peer);
        peer->oursink->set_option(aoo_opt_iso_blocks, AOO_ARG(n));   // idempotent; before the ms set so the first rebuild already sees iso
    }
    if (sbAdaptPeer(peer)) {
        int32_t prof = sbPeerIsWan(peer) ? 1 : 2;   // 1 = WAN profile, 2 = LAN profile
        peer->oursink->set_option(aoo_opt_adapt, AOO_ARG(prof));      // Idempotent; adaptive depth owns this sink from here
    }
    peer->oursink->set_buffersize(bufferMs);
    if (auxSinks && peer->echosink && peer->latencysink) {
        peer->echosink->set_buffersize(bufferMs);
        peer->latencysink->set_buffersize(bufferMs);
    }
    return bufferMs;
}

void SonobusAudioProcessor::loadMcpTaps()
{
    //   SB_MCP_FLOOR_MS=<2..24>  pin floor (default 8)
    //   SB_MCP_RESET_PIN=1       discard every persisted pin this launch -> fresh MEASURE from the floor
    if (const char* fl = sbtap::tapConf("SB_MCP_FLOOR_MS"); fl && *fl) {
        const float v = (float) atof(fl);
        if (v >= 2.0f && v <= 24.0f) mMcpPinFloorMs = v;
    }
    if (const char* rp = sbtap::tapConf("SB_MCP_RESET_PIN"); rp && rp[0] == '1') {
        mMcpResetPinTap = true;
    }
    DBG("MCP taps: floor " << mMcpPinFloorMs << " ms, reset persisted pins = " << (int) mMcpResetPinTap);
}

// Smart Pin observability — append "ts event peer ms" to the
// sink event log file (SB_SINK_EVLOG) so a pin is provable on machines whose
// stderr we cannot capture. Event thread only; opens/closes per event (rare).
void SonobusAudioProcessor::sbMcpEvlog(const char* ev, const RemotePeer* peer, float ms)
{
    const char* path = sbtap::tapConf("SB_SINK_EVLOG");
    if (!path || !*path || !peer) return;
    if (FILE* f = fopen(path, "a")) {
        fprintf(f, "%.3f %s %s %.1f%s\n", Time::getMillisecondCounterHiRes() * 1e-3, ev,
                peer->userName.toRawUTF8(), ms, sbPeerIsWan(peer) ? " wan" : " lan");
        fclose(f);
    }
}

// Measure-commit-pin COMMIT — pin the peer's receive
// jitter buffer at max(measured working point, clean floor). Called on the
// event thread (mCoreLock read-held by the caller); applies sinks inline
// (like the AutoFull adjust paths) rather than via applyRemotePeerBufferTime
// so the manual-set/reset semantics of that function stay distinct.
void SonobusAudioProcessor::commitMcpPinForPeer(RemotePeer * peer, double nowtimeMs)
{
    const float pinMs = jmax(jmax(peer->mcpMaxReachedMs, peer->buffertimeMs), mcpFloorMsFor(peer));

    applyPeerSinkBufferMs(peer, pinMs);   // One apply path (pinMs already >= floor)
    peer->mcpPinnedMs = pinMs;
    peer->mcpPhase = kMcpPhasePinned;
    sbMcpEvlog("mcp_commit", peer, pinMs);
    peer->mcpEscWindowStartTime = nowtimeMs;
    peer->mcpEscWindowCount = 0;

    peer->totalEstLatency = peer->smoothPingTime.xbar + 2*peer->buffertimeMs + (1e3*currSamplesPerBlock/getSampleRate());
    peer->latencyDirty = true;
    peer->fillRatioSlow.reset();
    peer->fillRatio.reset();
    if (peer->hasRealLatency) {
        peer->totalEstLatency = peer->totalLatency + (peer->buffertimeMs - peer->bufferTimeAtRealLatency);
    }

    if (isHostedMixModeEnabled()) {
        // one shared network path -> the unified policy value carries the
        // pin, and the pinned flag arms the reconnect fast path.
        mUnifiedReceiveBufferMs = jmax(peer->buffertimeMs, sbFeedBufferFloorMs());
        mUnifiedMcpPinned = true;
    }

    commitCacheForPeer(peer); // instant persistence — pin survives relaunch

    sendRemotePeerInfoUpdate(-1, peer);

    DBG("MCP COMMIT: pinned " << peer->userName << " at " << pinMs
        << " ms (maxReached " << peer->mcpMaxReachedMs << ")");
}

// Measure-commit-pin ESCALATE: sustained underruns while pinned (> kMcpEscEventsPerWindow loss
// events across a full 60 s window) raise the pin one block and re-arm the watchdog. The
// reset-to-minimum button is the manual de-bloat lever (restarts MEASURE via
// applyRemotePeerBufferTime).
void SonobusAudioProcessor::escalateMcpPinForPeer(RemotePeer * peer, double nowtimeMs)
{
    const float adjms = 1000.0f * currSamplesPerBlock / getSampleRate();
    const int prevcount = peer->mcpEscWindowCount;

    // Escalation ceiling: more buffer does not cure bursts, and without a ceiling churny periods
    // ratchet pins upward. Hold at the ceiling and let step-down recover.
    const float kMcpEscCeilingMs = mcpCeilingMsFor(peer);   // 32 LAN / 96 WAN
    if (peer->buffertimeMs + adjms > kMcpEscCeilingMs) {
        peer->mcpEscWindowStartTime = nowtimeMs;
        peer->mcpEscWindowCount = 0;
        DBG("MCP ESCALATE: " << peer->userName << " at ceiling " << peer->buffertimeMs << " ms — holding");
        return;
    }

    {   // LAN-isochronous sink — no escalation, depth is fixed in blocks
        static const bool sbIsoSink = [](){ const char* v = sbtap::tapConf("SB_AOO_ISO_BLOCKS"); return v && atoi(v) > 0; }();
        if (sbIsoSink || sbIsoPeer(peer) || sbAdaptPeer(peer)) { peer->mcpEscWindowStartTime = nowtimeMs; peer->mcpEscWindowCount = 0; sbMcpEvlog("mcp_escalate_iso_ignored", peer, peer->buffertimeMs); return; }
    }
    applyPeerSinkBufferMs(peer, peer->buffertimeMs + adjms);   // One apply path
    peer->mcpPinnedMs = peer->buffertimeMs;
    sbMcpEvlog("mcp_escalate", peer, peer->buffertimeMs);
    peer->mcpMaxReachedMs = jmax(peer->mcpMaxReachedMs, peer->buffertimeMs);
    peer->mcpEscWindowStartTime = nowtimeMs;
    peer->mcpEscWindowCount = 0;

    peer->totalEstLatency = peer->smoothPingTime.xbar + 2*peer->buffertimeMs + (1e3*currSamplesPerBlock/getSampleRate());
    peer->latencyDirty = true;
    peer->fillRatioSlow.reset();
    peer->fillRatio.reset();
    if (peer->hasRealLatency) {
        peer->totalEstLatency = peer->totalLatency + (peer->buffertimeMs - peer->bufferTimeAtRealLatency);
    }

    if (isHostedMixModeEnabled()) {
        mUnifiedReceiveBufferMs = jmax(peer->buffertimeMs, sbFeedBufferFloorMs());
        mUnifiedMcpPinned = true;
    }

    commitCacheForPeer(peer); // persist the new pin

    sendRemotePeerInfoUpdate(-1, peer);

    DBG("MCP ESCALATE: " << peer->userName << " re-pinned at " << peer->buffertimeMs
        << " ms (+" << adjms << ") after " << prevcount << " loss events in window");
}

float SonobusAudioProcessor::getRemotePeerBufferTime(int index) const
{
    float buftimeMs = 30.0f;
    
    const ScopedReadLock sl (mCoreLock);        
    if (index < mRemotePeers.size()) {
        RemotePeer * remote = mRemotePeers.getUnchecked(index);
        buftimeMs = remote->buffertimeMs;
        // A relayed player row in hosted Auto shows the depth its sink is actually running,
        // not the stored ms setting (Manual keeps the setting = the pin).
        if (remote->relayedViaHub && !sbHostedManualPin()) {
            const float live = sbRowLiveDepthMs(remote);
            if (live > 0.0f) buftimeMs = live;
        }
        // reflect actual truth
        buftimeMs = jmax((double)buftimeMs, 1000.0f * currSamplesPerBlock / getSampleRate());
    }
    return buftimeMs;    
}

void SonobusAudioProcessor::setRemotePeerAutoresizeBufferMode(int index, SonobusAudioProcessor::AutoNetBufferMode flag)
{
    // Hosted mode — one auto-mode flag for all sinks (one
    // network path, one policy); delegate like setRemotePeerBufferTime.
    if (isHostedMixModeEnabled()) {
        setUnifiedReceiveAutoresizeBufferMode(flag);
        return;
    }
    applyRemotePeerAutoresizeBufferMode(index, flag);
}

// Unified auto-mode setter — applies the one flag to every
// remote peer when HostedMix is enabled; store-only outside hosted mode.
void SonobusAudioProcessor::setUnifiedReceiveAutoresizeBufferMode(SonobusAudioProcessor::AutoNetBufferMode flag)
{
   #if SONOBUSPLUS_BUILD
    if (flag != AutoNetBufferModeOff) flag = AutoNetBufferModeMeasureCommitPin;   // Manual / Auto only
   #endif
    mUnifiedReceiveAutoMode = flag;
    // Any explicit mode change starts fresh — a committed
    // measure-commit pin does not survive it.
    mUnifiedMcpPinned = false;

    if (!isHostedMixModeEnabled()) return;

    {
        const ScopedReadLock sl (mCoreLock);
        for (int i = 0; i < mRemotePeers.size(); ++i) {
            applyRemotePeerAutoresizeBufferMode(i, flag);
        }
    }

    if (flag == AutoNetBufferModeInitAuto) {
        // restart the unified value from the floor, matching the per-peer
        // InitAuto reset-to-zero-and-start-over behavior
        setUnifiedReceiveBufferTime(0.0f);
    } else {
        // Re-apply so the hub feed sink flips Manual (pinned) <-> Auto (adaptive) immediately
        setUnifiedReceiveBufferTime(mUnifiedReceiveBufferMs);
    }
}

void SonobusAudioProcessor::applyRemotePeerAutoresizeBufferMode(int index, SonobusAudioProcessor::AutoNetBufferMode flag)
{
    const ScopedReadLock sl (mCoreLock);
    if (index < mRemotePeers.size()) {
        RemotePeer * remote = mRemotePeers.getUnchecked(index);
        remote->autosizeBufferMode = flag;

        if (flag == AutoNetBufferModeAutoFull) {
            remote->netBufAutoBaseline = (1e3*currSamplesPerBlock/getSampleRate()); // at least a process block
        } else if (flag == AutoNetBufferModeInitAuto) {
            applyRemotePeerBufferTime(index, 0.0f); // reset to zero and start it over
        } else if (flag == AutoNetBufferModeMeasureCommitPin) {
            // Selecting Smart Pin starts a fresh MEASURE
            // phase from the current buffer value (AutoFull machinery takes
            // it from here for kMcpMeasureWindowSec, then commits).
            remote->netBufAutoBaseline = (1e3*currSamplesPerBlock/getSampleRate()); // at least a process block
            remote->mcpPhase = kMcpPhaseMeasure;
            remote->mcpMeasureStartTime = Time::getMillisecondCounterHiRes();
            applyPeerSinkBufferMs(remote, remote->buffertimeMs);   // MEASURE never starts below the floor
            remote->mcpMaxReachedMs = remote->buffertimeMs;
            remote->mcpPinnedMs = 0.0f;
            remote->mcpEscWindowStartTime = 0;
            remote->mcpEscWindowCount = 0;
        }

        // Clear drop count (hub mode keeps the cumulative count)
        remote->dataPacketsResent = 0;
        if (isHostedMixModeEnabled()) { remote->lastDropCount = remote->dataPacketsDropped; }
        else { remote->dataPacketsDropped = 0; remote->lastDropCount = 0; }
        remote->resetDroptime = Time::getMillisecondCounterHiRes();
        remote->fastDropRate.resetInitVal(0.0f);

        //remote->lastDroptime = 0;
    }
}

SonobusAudioProcessor::AutoNetBufferMode SonobusAudioProcessor::getRemotePeerAutoresizeBufferMode(int index, bool & initCompleted) const
{
    const ScopedReadLock sl (mCoreLock);        
    if (index < mRemotePeers.size()) {
        RemotePeer * remote = mRemotePeers.getUnchecked(index);
        initCompleted = remote->autoNetbufInitCompleted;
        return remote->autosizeBufferMode;
    }
    return AutoNetBufferModeOff;    
}

// acceptable limit for drop rate in dropinstance/second, above which it will adjust the jitter buffer in Auto modes
void SonobusAudioProcessor::setAutoresizeBufferDropRateThreshold(float thresh)
{
    mAutoresizeDropRateThresh = thresh;
}



bool SonobusAudioProcessor::getRemotePeerReceiveBufferFillRatio(int index, float & retratio, float & retstddev) const
{
    retratio = 0.0f;
    retstddev = 0.0f;
    const ScopedReadLock sl (mCoreLock);
    if (index < mRemotePeers.size()) {
        RemotePeer * remote = mRemotePeers.getUnchecked(index);
        retratio = remote->fillRatio.xbar;
        retstddev = remote->fillRatioSlow.s2xx;
        return true;
    }
    return false;
}

// LIVE sink resampler backlog in ms —
// the one queue the fill ratio doesn't cover. Same addressing as the fill
// query at the periodic stats site (endpoint + remoteSourceId).
float SonobusAudioProcessor::getRemotePeerResamplerBacklogMs(int index) const
{
    const ScopedReadLock sl (mCoreLock);
    if (index < mRemotePeers.size()) {
        RemotePeer * remote = mRemotePeers.getUnchecked(index);
        if (remote->oursink && remote->endpoint && remote->remoteSourceId != AOO_ID_NONE) {
            float samples = 0.0f;
            if (remote->oursink->get_sourceoption(remote->endpoint, remote->remoteSourceId,
                    aoo_opt_resampler_backlog, &samples, sizeof(samples)) > 0) {
                return samples * 1000.0f / (float)jmax(1, (int)getSampleRate());
            }
        }
    }
    return -1.0f;
}

