SonobusAudioProcessor::RemotePeer * SonobusAudioProcessor::doAddRemotePeerIfNecessary(EndpointState * endpoint, int32_t ourId, const String & username, const String & groupname)
{
    // Write lock only, never a read-scan with a nested write upgrade, which deadlocks when two
    // threads do it concurrently. Inner nested ScopedWriteLocks are safe because JUCE write locks
    // are re-entrant on the same thread. Callers must not hold the read lock.
    // processBlock takes mCoreLock for read every block and the recv thread for every packet, so
    // holding the write lock across the peer build (five aoo sink/source creates + setups +
    // formats, ms) would disturb every existing feed. The write lock covers only dedupe, id choice
    // and matrix resize; the build runs unlocked; the insert re-checks for a race.
    RemotePeer * retpeer = nullptr;
    bool doadd = true;
    int32_t newid = 1;
    {
        const ScopedWriteLock sl (mCoreLock);
        for (auto s : mRemotePeers) {
            if (s->endpoint == endpoint && s->userName == username) {
                doadd = false;
                retpeer = s;
                break;
            }
        }
        if (!doadd && retpeer) {
            DBG("Remote peer already exists, setting name and group");
            if (username.isNotEmpty() && retpeer->userName.isEmpty()) {
                retpeer->userName = username;
                retpeer->groupName = groupname;
                retpeer->relayedViaHub = !isHubPeer(username);   
                if (findAndLoadCacheForPeer(retpeer)) {
                    g_sbFmtWhy = "addpeer-or-cache";
                    setupSourceFormat(retpeer, retpeer->oursource.get());
                    if (retpeer->latencysource) setupSourceFormat(retpeer, retpeer->latencysource.get(), true);
                    if (retpeer->echosource) setupSourceFormat(retpeer, retpeer->echosource.get(), true);
                    applyPeerSinkBufferMs(retpeer, retpeer->buffertimeMs);   // Cached value floor-clamped
                    for (auto i=0; i < retpeer->numChanGroups && i < MAX_CHANGROUPS; ++i) {
                        retpeer->chanGroups[i].commitCompressorParams();
                        retpeer->chanGroups[i].commitExpanderParams();
                        retpeer->chanGroups[i].commitEqParams();
                    }
                }
            }
            return retpeer;
        }
        bool hasit = false;
        while (!hasit) {
            bool safe = true;
            for (auto s : mRemotePeers) {
                if (s->ourId == newid) {
                    safe = false;
                    ++newid;
                    break;
                }
            }
            if (safe) hasit = true;
        }
        adjustRemoteSendMatrix(mRemotePeers.size(), false);
    }

    if (doadd) {
        retpeer = new RemotePeer(endpoint, newid);


        retpeer->userName = username;
        retpeer->groupName = groupname;
        retpeer->relayedViaHub = !isHubPeer(username);   // Only the hub row sends
        if (!retpeer->relayedViaHub && endpoint && endpoint->ipv4) mHubLinkIpv4.store(endpoint->ipv4, std::memory_order_relaxed);
        
        retpeer->buffertimeMs = mBufferTime.get() * 1000.0f;
        if (isHostedMixModeEnabled()) {   // Feed-buffer floor
            retpeer->buffertimeMs = jmax(retpeer->buffertimeMs, sbFeedBufferFloorMs());
        }
        retpeer->formatIndex = mDefaultAudioFormatIndex;
        retpeer->autosizeBufferMode = (AutoNetBufferMode) defaultAutoNetbufMode;

        retpeer->resetDroptime = Time::getMillisecondCounterHiRes();
        retpeer->fastDropRate.resetInitVal(0.0f);

        // default
        retpeer->numChanGroups = 1;
        retpeer->chanGroups[0].params.numChannels = 0;
        retpeer->chanGroups[0].params.gain = 1.0f;

        retpeer->gain = mDefUserLevel.get();

        findAndLoadCacheForPeer(retpeer);

        // HostedMix — every feed shares the hub->us path,
        // so a joining peer inherits the ONE unified receive-buffer policy,
        // overriding whatever name-keyed cached values findAndLoadCacheForPeer
        // just restored (those caches are per-peer P2P settings; in hub mode
        // they'd reintroduce the meaningless per-player duplication).
        if (isHostedMixModeEnabled()) {
            retpeer->buffertimeMs = jmax(mUnifiedReceiveBufferMs, sbFeedBufferFloorMs());
            retpeer->autosizeBufferMode = (AutoNetBufferMode) mUnifiedReceiveAutoMode;

            // The ONE upload to the hub is
            // always PCM 16-bit — override whatever name-keyed cache value
            // findAndLoadCacheForPeer just restored for the hub peer.
            // setupSourceFormat enforces this too; pinning formatIndex here
            // keeps the cache/UI reading the truth.
            if (isHubPeer(username)) {
                const int hubidx = getHubUpstreamFormatIndex();
                if (hubidx >= 0) retpeer->formatIndex = hubidx;
            }
        }

        if (retpeer->autosizeBufferMode == AutoNetBufferModeInitAuto) {
            retpeer->buffertimeMs = 0;
        }

        // Measure-commit-pin lifecycle init. With a
        // persisted pin (per-peer cache in P2P, unified pinned flag in
        // hosted mode) take the fast path: skip MEASURE, go straight to
        // PINNED at the saved value — escalation watchdog stays armed.
        // Otherwise start a fresh MEASURE window.
        if (retpeer->autosizeBufferMode == AutoNetBufferModeMeasureCommitPin) {
            double mcpnow = Time::getMillisecondCounterHiRes();
            // Per-path floor: the one value nothing below may be applied, MEASURE included.
            const float floorMs = mcpFloorMsFor(retpeer);
            float persistedPin = 0.0f;
            if (isHostedMixModeEnabled()) {
                persistedPin = mUnifiedMcpPinned ? jmax(mUnifiedReceiveBufferMs, sbFeedBufferFloorMs()) : 0.0f;
            } else {
                persistedPin = retpeer->mcpPinnedMs; // restored by findAndLoadCacheForPeer, 0 = none (also 0 under SB_MCP_RESET_PIN)
            }
            // Sanity guard: a persisted pin above any musically usable value is left over from a
            // runaway. Discard it and re-MEASURE instead of resurrecting it; re-measuring costs 45
            // quiet seconds.
            // The taps
            //   SB_MCP_FLOOR_MS=<2..24>  pin floor (default 8)
            //   SB_MCP_RESET_PIN=1       discard every persisted pin -> fresh MEASURE from the floor
            // are read once in loadMcpTaps() (constructor) so the cache and unified state loaders
            // honour them too.
            if (mMcpResetPinTap) {
                DBG("MCP: SB_MCP_RESET_PIN — discarding persisted pin " << persistedPin << " ms");
                persistedPin = 0.0f;
                if (isHostedMixModeEnabled()) { mUnifiedMcpPinned = false; mUnifiedReceiveBufferMs = jmax(mMcpPinFloorMs, sbFeedBufferFloorMs()); }
                // seed MEASURE at the floor: neither above it (stale value) nor below it
                retpeer->buffertimeMs = floorMs;
            }
            const float kMcpPinSanityMaxMs = mcpSanityMaxMsFor(retpeer);   // 24 LAN / 80 WAN
            if (persistedPin > kMcpPinSanityMaxMs) {
                DBG("MCP: discarding insane persisted pin " << persistedPin << " ms — re-measuring");
                persistedPin = 0.0f;
                if (isHostedMixModeEnabled()) {
                    mUnifiedMcpPinned = false;
                    // the stale value seeds starting buffers too, so reset it to the floor
                    mUnifiedReceiveBufferMs = jmax(mMcpPinFloorMs, sbFeedBufferFloorMs());
                }
                retpeer->buffertimeMs = floorMs;
            }
            if (persistedPin > 0.0f) {
                // A persisted pin below the floor resolves to the floor here, once, with no
                // MEASURE.
                retpeer->buffertimeMs = jmax(persistedPin, floorMs);
                retpeer->mcpPinnedMs = retpeer->buffertimeMs;
                retpeer->mcpMaxReachedMs = retpeer->buffertimeMs;
                retpeer->mcpPhase = kMcpPhasePinned;
                retpeer->mcpEscWindowStartTime = mcpnow;
                retpeer->mcpEscWindowCount = 0;
                DBG("MCP fast path: " << retpeer->userName << " pinned at persisted " << retpeer->buffertimeMs << " ms");
            } else {
                // MEASURE starts AT OR ABOVE the floor — the
                // first do_update the sink ever sees is already >= floor, so
                // there is no 1-block start and no 1→2→3→4 ramp under it.
                retpeer->buffertimeMs = jmax(retpeer->buffertimeMs, floorMs);
                retpeer->mcpPhase = kMcpPhaseMeasure;
                retpeer->mcpMeasureStartTime = mcpnow;
                retpeer->mcpMaxReachedMs = retpeer->buffertimeMs;
                retpeer->mcpPinnedMs = 0.0f;
                DBG("MCP: " << retpeer->userName << " MEASURE from " << retpeer->buffertimeMs << " ms (floor " << floorMs << ")");
            }
        }

        retpeer->resetSafetyMuted = retpeer->buffertimeMs < 3.0f;
        retpeer->blockedUs = false;
        
        retpeer->oursink->setup(getSampleRate(), currSamplesPerBlock, getMainBusNumOutputChannels());
        applyPeerSinkBufferMs(retpeer, retpeer->buffertimeMs, false);   // Floor-clamped; first do_update lands at >= floor

        static const bool sbIdleMaskOn = [] { const char* e = std::getenv("SB_IDLE_MASK"); return !(e && e[0] == '0'); }();
        int32_t flags = AOO_PROTOCOL_FLAG_COMPACT_DATA | (sbIdleMaskOn ? AOO_PROTOCOL_FLAG_IDLE_MASK : 0);   // We decode idle-masked blocks
        retpeer->oursink->set_option(aoo_opt_protocol_flags, &flags, sizeof(int32_t));
        {   // No resend requests — at a 1.33 ms hold a resend can never arrive in time,
            // and the requests grow exactly when the link is already losing packets.
            int32_t noresend = 0;
            retpeer->oursink->set_option(aoo_opt_resend_limit, AOO_ARG(noresend));
        }

        retpeer->nominalSendChannels = mSendChannels.get();
        retpeer->sendChannels =  mSendChannels.get() <= 0 ?  mActiveSendChannels : mSendChannels.get();

        setupSourceFormat(retpeer, retpeer->oursource.get());
        float sendbufsize = jmax(10.0, SENDBUFSIZE_SCALAR * 1000.0f * currSamplesPerBlock / getSampleRate());
        retpeer->oursource->setup(getSampleRate(), currSamplesPerBlock, retpeer->sendChannels);
        retpeer->oursource->set_buffersize(sendbufsize);
        retpeer->oursource->set_packetsize(retpeer->packetsize);
        // Upstream redundancy on client-to-hub, mirroring the hub's --redundancy-lan/-wan. Latency
        // cost: none, copies are sent in parallel. Bandwidth scales with the copy count. Must come
        // after setup()/buffersize/packetsize (matching the hub's order); setting it in the
        // RemotePeer constructor before setup() leaves the source half-initialized on first
        // connect. SB_UP_RED=N (1..4) forces a value for A/B; SB_UP_RED1=1 means 1.
        {
            int red = 1;   // Default: 1 copy on LAN and WAN (one copy halves the tail and the bandwidth)
            // env or /tmp/sb_taps.conf (same mechanism as every other tap)
            if (const char* r = sbtap::tapConf("SB_UP_RED"); r && r[0] >= '1' && r[0] <= '4') red = r[0] - '0';
            if (const char* r1 = sbtap::tapConf("SB_UP_RED1"); r1 && r1[0] == '1') red = 1;
            retpeer->oursource->set_redundancy(red);
            DBG("upstream redundancy to " << retpeer->userName << " = " << red);
        }
        //setupSourceUserFormat(retpeer, retpeer->oursource.get());

        if (retpeer->latencysource) setupSourceFormat(retpeer, retpeer->latencysource.get(), true);
        if (retpeer->latencysource) retpeer->latencysource->setup(getSampleRate(), currSamplesPerBlock, 1);
        if (retpeer->latencysource) retpeer->latencysource->set_packetsize(retpeer->packetsize);
        if (retpeer->echosource) setupSourceFormat(retpeer, retpeer->echosource.get(), true);
        if (retpeer->echosource) retpeer->echosource->setup(getSampleRate(), currSamplesPerBlock, 1);
        if (retpeer->echosource) retpeer->echosource->set_buffersize(1000.0f * currSamplesPerBlock / getSampleRate());
        if (retpeer->echosource) retpeer->echosource->set_packetsize(retpeer->packetsize);

        if (retpeer->latencysink) retpeer->latencysink->setup(getSampleRate(), currSamplesPerBlock, 1);
        if (retpeer->echosink) retpeer->echosink->setup(getSampleRate(), currSamplesPerBlock, 1);

        if (retpeer->latencysink) retpeer->latencysink->set_option(aoo_opt_protocol_flags, &flags, sizeof(int32_t));
        if (retpeer->echosink) retpeer->echosink->set_option(aoo_opt_protocol_flags, &flags, sizeof(int32_t));

        applyPeerSinkBufferMs(retpeer, retpeer->buffertimeMs);   // aux sinks (oursink unchanged -> no rebuild)

        // never dynamic resampling the latency and echo ones
        if (retpeer->latencysink) retpeer->latencysink->set_dynamic_resampling(0);
        if (retpeer->echosink) retpeer->echosink->set_dynamic_resampling(0);
        if (retpeer->latencysource) retpeer->latencysource->set_dynamic_resampling(0);
        if (retpeer->echosource) retpeer->echosource->set_dynamic_resampling(0);

        
        retpeer->oursource->set_ping_interval(2000);
        if (retpeer->latencysource) retpeer->latencysource->set_ping_interval(2000);
        if (retpeer->echosource) retpeer->echosource->set_ping_interval(2000);

        retpeer->oursource->set_respect_codec_change_requests(1);
        if (retpeer->latencysource) retpeer->latencysource->set_respect_codec_change_requests(1);
        if (retpeer->echosource) retpeer->echosource->set_respect_codec_change_requests(1);
        
        //retpeer->latencyProcessor.reset(new MTDM(getSampleRate()));
        retpeer->latencyMeasurer.reset(new LatencyMeasurer());
        
        // AOO dynamic resampling is a wall-clock-referenced, 2-tap-linear resampler on every sink
        // and source, which resamples every feed continuously. In hub-hosted mode it is never
        // wanted: clock drift is handled by the hub clock-lock (word-clock hosts) and the sinc
        // DRIFT ASRC (free-running hosts). Forced off here and in updateDynamicResampling();
        // SB_DYNRESAMP=1 in the taps re-enables it for experiments only.
        const bool dynres = sbDynamicResamplingWanted();
        if (sbDiagOn()) fprintf(stderr, "[SB-DYNRES] addRemotePeer '%s' ourId=%d dynamic_resampling=%d (option %d, hosted %d)\n", retpeer->userName.toRawUTF8(), (int) retpeer->ourId, (int) dynres, (int) mDynamicResampling.get(), (int) isHostedMixModeEnabled());
        retpeer->oursink->set_dynamic_resampling(dynres ? 1 : 0);
        retpeer->oursource->set_dynamic_resampling(dynres ? 1 : 0);

        
        retpeer->workBuffer.setSize(2, currSamplesPerBlock, false, false, true);

        int outchannels = getMainBusNumOutputChannels();
        
        retpeer->recvMeterSource.resize (outchannels, meterRmsWindow);
        retpeer->sendMeterSource.resize (retpeer->sendChannels, meterRmsWindow);

        retpeer->sendAllow = !mMainSendMute.get();
        retpeer->sendAllowCache = true; // cache is allowed for new ones, so when it is unmuted it actually does
        
        retpeer->recvAllow = !mMainRecvMute.get();
        retpeer->recvAllowCache = true;
        
        retpeer->lastSendPingTimeMs = Time::getMillisecondCounterHiRes() - PEER_PING_INTERVAL_MS/2; // so that first ping doesn't happen immediately
        retpeer->haveSentFirstPeerInfo = false;

        //retpeer->chanGroups[0].init(getSampleRate());
        for (auto chgrpi = 0; /*chgrpi < s->numChanGroups && */ chgrpi < MAX_CHANGROUPS; ++chgrpi) {
            retpeer->chanGroups[chgrpi].init(getSampleRate());
        };


        // now add it, once initialized
        {
            const ScopedWriteLock slw (mCoreLock);
            // The build ran unlocked — if another thread added the same peer (or took our id) meanwhile,
            // discard ours and hand back theirs / rebuild once with a fresh id.
            for (auto s : mRemotePeers) {
                if (s->endpoint == endpoint && s->userName == username) {
                    delete retpeer;
                    return s;
                }
            }
            for (auto s : mRemotePeers) {
                if (s->ourId == newid) { delete retpeer; retpeer = nullptr; break; }
            }
            if (retpeer) mRemotePeers.add(retpeer);
        }
        if (!retpeer) {
            return doAddRemotePeerIfNecessary(endpoint, ourId, username, groupname);
        }
    }
    return retpeer;
}

SonobusAudioProcessor::RemotePeer * SonobusAudioProcessor::doAddInfoOnlyPeerIfNecessary(EndpointState * endpoint, const String & username, const String & groupname)
{
    // Write lock only, never a read-scan with a nested write upgrade, which deadlocks when two
    // threads do it concurrently. Inner nested ScopedWriteLocks are safe because JUCE write locks
    // are re-entrant on the same thread. Callers must not hold the read lock.
    // RemotePeer's constructor builds five aoo objects, and processBlock needs the lock for read
    // every block, so lock only the dedupe and id choice, build unlocked, and re-check on insert.
    constexpr int32_t kInfoOnlyOurIdBase = 1000;
    int32_t newid = kInfoOnlyOurIdBase;
    {
        const ScopedWriteLock sl (mCoreLock);
        for (auto s : mRemotePeers) {
            if (s->endpoint == endpoint && s->infoOnly) return s;
            if (!username.isEmpty() && s->userName == username) return s;
        }
        while (true) {
            bool safe = true;
            for (auto s : mRemotePeers) {
                if (s->ourId == newid) { safe = false; break; }
            }
            if (safe) break;
            ++newid;
        }
        adjustRemoteSendMatrix(mRemotePeers.size(), false);
    }
    auto * retpeer = new RemotePeer(endpoint, newid);
    retpeer->infoOnly = true;
    retpeer->userName = username;
    retpeer->groupName = groupname;
    retpeer->connected = true;
    retpeer->sendActive = false;
    retpeer->recvActive = false;
    retpeer->sendAllow = false;
    retpeer->recvAllow = false;

    // Info-only peers don't otherwise initialize their meter source. Sized to 2 ch like the regular
    // peer-add path uses for outchannels=2.
    //
    // RMS window sizing: foleys::LevelMeterSource averages rmsHistory entries for the displayed RMS
    // bar. A short window (4 entries) keeps the bar from trailing behind silence; peak hold is
    // similarly short (120 ms).
    {
        const int meterRmsWindow = 4;
        retpeer->recvMeterSource.resize(2, meterRmsWindow);
        retpeer->recvMeterSource.setMaxHoldMS(120);
    }

    {
        const ScopedWriteLock slw (mCoreLock);
        for (auto s2 : mRemotePeers) {   // Raced by another add while we built unlocked?
            if ((s2->endpoint == endpoint && s2->infoOnly) || (!username.isEmpty() && s2->userName == username)) { delete retpeer; return s2; }
        }
        mRemotePeers.add(retpeer);
    }

    DBG("Added info-only peer: " << username << " (group=" << groupname << ", ourId=" << newid << ")");

    return retpeer;
}

void SonobusAudioProcessor::commitCacheForPeer(RemotePeer * retpeer)
{
    if (retpeer->userName.isEmpty()) {
        DBG("username empty, can't commit");
        return;
    }
    // An info-only row is a placeholder with default values. Removing it during a reconnect must
    // not commit its default gain over the player's saved level. Same rule as the save loop.
    if (retpeer->infoOnly) return;

    PeerStateCache newcache;
    newcache.netbuf = retpeer->buffertimeMs;
    newcache.netbufauto = retpeer->autosizeBufferMode;
    // Persist the committed measure-commit pin (0 while
    // measuring / not in that mode) — reconnect fast path reads it back.
    newcache.netbufmcppin = (retpeer->autosizeBufferMode == AutoNetBufferModeMeasureCommitPin
                             && retpeer->mcpPhase == kMcpPhasePinned) ? retpeer->mcpPinnedMs : 0.0f;
    newcache.name = retpeer->userName;
    newcache.sendFormat = retpeer->formatIndex;
    newcache.numChanGroups = retpeer->numChanGroups;
    newcache.mainGain = retpeer->gain;
    newcache.numMultiChanGroups = retpeer->lastMultiNumChanGroups;
    newcache.modifiedChanGroups = retpeer->modifiedMultiChanGroups;
    newcache.orderPriority = retpeer->orderPriority;
    sbFillHubMixCache(newcache);   // Row MUTE/SOLO (hub-mix override) ride along with the entry

    for (int i=0; i < retpeer->numChanGroups && i < MAX_CHANGROUPS; ++i) {
        newcache.channelGroupParams[i] = retpeer->chanGroups[i].params;
    }
    for (int i=0; i < retpeer->lastMultiNumChanGroups && i < MAX_CHANGROUPS; ++i) {
        newcache.channelGroupMultiParams[i] = retpeer->lastMultiChanParams[i];
    }

    PeerStateCacheMap::iterator found  = mPeerStateCacheMap.find(retpeer->userName);
    
    if (found != mPeerStateCacheMap.end()) {
        found->second = newcache;
    }
    else {
        mPeerStateCacheMap.insert(PeerStateCacheMap::value_type(retpeer->userName, newcache));
    }
}

bool SonobusAudioProcessor::findAndLoadCacheForPeer(RemotePeer * retpeer)
{
    if (retpeer->userName.isEmpty()) {
        DBG("username empty, can't match");
        return false;
    }
    
    // look for current peer by user name in peer cache and apply settings
    PeerStateCacheMap::iterator found  = mPeerStateCacheMap.find(retpeer->userName);
    if (found == mPeerStateCacheMap.end()) {
        // no exact match, look for ones starting with the same beginning
        String namebase = retpeer->userName;
        StringArray nametoks = StringArray::fromTokens(retpeer->userName, false);
        if (nametoks.size() > 1) {
            nametoks.remove(nametoks.size()-1);
            namebase = nametoks.joinIntoString(" ").trim();
        }
        
        for (PeerStateCacheMap::iterator iter = mPeerStateCacheMap.begin(); iter != mPeerStateCacheMap.end(); ++iter) {
            if (iter->first.startsWith(namebase)) {
                // close match
                DBG("Found close peer match: " << namebase << "  with cachename: " << iter->first);
                found = iter;
                break;
            }
        }
    }
    else {
        DBG("Found exact peer match: " << retpeer->userName);
    }
    
    if (found != mPeerStateCacheMap.end()) {
        PeerStateCache & cache = found->second;
        // SB_MCP_RESET_PIN applies to every peer as it is added (and to the cached entry itself, so
        // a later re-add in this session cannot resurrect it).
        if (mMcpResetPinTap && cache.netbufmcppin > 0.0f) {
            DBG("MCP: SB_MCP_RESET_PIN — clearing cached pin " << cache.netbufmcppin << " ms for " << cache.name);
            cache.netbufmcppin = 0.0f;
        }
        retpeer->autosizeBufferMode = (AutoNetBufferMode) cache.netbufauto;
        retpeer->buffertimeMs = cache.netbuf;
        retpeer->mcpPinnedMs = cache.netbufmcppin; // Persisted measure-commit pin (0 = none)
        retpeer->formatIndex = cache.sendFormat;
        retpeer->numChanGroups = cache.numChanGroups; // restore this?
        retpeer->gain = cache.mainGain;
        retpeer->lastMultiNumChanGroups = cache.numMultiChanGroups;
        retpeer->modifiedChanGroups = retpeer->modifiedMultiChanGroups = cache.modifiedChanGroups;
        retpeer->orderPriority  = cache.orderPriority;


        for (int i=0; i < retpeer->numChanGroups  && i < MAX_CHANGROUPS; ++i) {
            retpeer->chanGroups[i].params = cache.channelGroupParams[i];
        }

        for (int i=0; i < retpeer->lastMultiNumChanGroups  && i < MAX_CHANGROUPS; ++i) {
            retpeer->lastMultiChanParams[i] = cache.channelGroupMultiParams[i];
        }

        sendRemotePeerInfoUpdate(-1, retpeer); // send to this peer

        return true;
    }
    return false;
}

// In hub mode the row MUTE / SOLO
// buttons toggle the per-listener hub-mix override (mHubMixOverrides, sent to the hub as /sb/hxmute|hxsolo), not
// recvAllow / soloed — so that is what gets persisted, per player name, in the same PeerStateCache the settings
// file already carries. While "Mute Everyone" is held the row's own intent is mutedBeforeMuteAll. The hub's own row
// and the local input mixer never persist these.
void SonobusAudioProcessor::sbFillHubMixCache(PeerStateCache & cache) const
{
    cache.hubMixMuted = cache.hubMixSoloed = false;
    if (cache.name.isEmpty() || isHubPeer(cache.name)) return;
    auto it = mHubMixOverrides.find(cache.name);
    if (it == mHubMixOverrides.end()) return;
    cache.hubMixMuted  = mMainRecvMute.get() ? it->second.mutedBeforeMuteAll : it->second.muted;
    cache.hubMixSoloed = it->second.soloed;
}

void SonobusAudioProcessor::sbPersistHubMixOverride(const String & senderUserName)
{
    if (senderUserName.isEmpty() || isHubPeer(senderUserName)) return;
    const ScopedReadLock sl (mCoreLock);
    for (auto * p : mRemotePeers) {
        if (p && !p->infoOnly && p->userName == senderUserName) { commitCacheForPeer(p); return; }   // full entry, hub-mix fields included
    }
    // no live row for that name (info-only / absent): refresh an existing entry only — a default-constructed
    // PeerStateCache must never be created here (netbuf fields are not meaningful defaults)
    auto found = mPeerStateCacheMap.find(senderUserName);
    if (found != mPeerStateCacheMap.end()) sbFillHubMixCache(found->second);
}


bool SonobusAudioProcessor::removeAllRemotePeersWithEndpoint(EndpointState * endpoint)
{
    // Whole function under the write lock: a read-scan with a nested write upgrade deadlocks when
    // two threads do it concurrently. Inner nested ScopedWriteLocks are safe because JUCE write
    // locks are re-entrant on the same thread. Callers must not hold the read lock.
    const ScopedWriteLock sl (mCoreLock);

    bool didremove = false;

    OwnedArray<RemotePeer> removed;

    // go from end, so deletions don't mess it up
    for (int i = mRemotePeers.size()-1; i >= 0;  --i) {
        auto * s = mRemotePeers.getUnchecked(i);
        if (s->endpoint == endpoint) {

            if (s->connected && !s->infoOnly) {
                disconnectRemotePeer(i);
            }

            adjustRemoteSendMatrix(i, true);

            if (!s->infoOnly) {
                commitCacheForPeer(s);
            }

            didremove = true;

            {
                const ScopedWriteLock slw (mCoreLock);

                removed.add(mRemotePeers.removeAndReturn(i));
            }
        }
    }

    // remote peers will be deleted when removed list goes out of scope

    return didremove;
}


// Called at relayed-row (re)creation so a rejoining sender's stale row dies the moment its
// authoritative replacement is being made.
bool SonobusAudioProcessor::removeStaleSameNamePeers(const String & username, EndpointState * keepEndpoint)
{
    // No read->write upgrade here: two threads each holding a read and waiting to upgrade deadlock
    // forever. Pure write lock from the start, and the caller must not hold mCoreLock at all.
    bool didremove = false;
    OwnedArray<RemotePeer> removed;
    {
        const ScopedWriteLock slw (mCoreLock);
        for (int i = mRemotePeers.size(); --i >= 0; ) {
            auto* s = mRemotePeers.getUnchecked(i);
            if (s && !s->infoOnly && s->userName == username && s->endpoint != keepEndpoint) {
                DBG("[REJOIN-GC] removing stale peer row '" << username << "' (endpoint changed)");
                removed.add(mRemotePeers.removeAndReturn(i));
                didremove = true;
            }
        }
    }
    // Cache commits outside the lock — the rows are owned by `removed` now.
    for (auto* p : removed) commitCacheForPeer(p);
    return didremove;
}

bool SonobusAudioProcessor::doRemoveRemotePeerIfNecessary(EndpointState * endpoint, int32_t ourId)
{
    // Whole function under the write lock: a read-scan with a nested write upgrade deadlocks when
    // two threads do it concurrently. Inner nested ScopedWriteLocks are safe because JUCE write
    // locks are re-entrant on the same thread. Callers must not hold the read lock.
    const ScopedWriteLock sl (mCoreLock);

    bool didremove = false;
    OwnedArray<RemotePeer> removed;

    int i=0;
    for (auto s : mRemotePeers) {
        if (s->endpoint == endpoint && s->ourId == ourId) {
            didremove = true;
            commitCacheForPeer(s);

            {
                const ScopedWriteLock slw (mCoreLock);
                removed.add(mRemotePeers.removeAndReturn(i));
            }
            break;
        }
        ++i;
    }
    
    return didremove;
    
}

bool SonobusAudioProcessor::isAnythingRoutedToPeer(int index) const
{
    bool ret = false;

    for (int i=0; i < mRemotePeers.size(); ++i) {
        if (mRemoteSendMatrix[i][index]) {
            ret = true;
            break;
        }
    }

    return ret;
}



